/* 《焦氏易林》林辭 4096 條（舊題漢・焦延壽撰）。鍵為「本卦文王卦序-之卦文王卦序」，本卦之本卦＝六爻皆靜。
   底本：維基文庫《焦氏易林（四部叢刊本）》（景北京圖書館藏元刊本）逐字轉錄；校以今人排印本的原文（掃描辨識，只取原文，
   不取該書的標題與白話）補缺字、斷句，並刪去混入的注文。異體字改為通行繁體。由 yijing.html 載入。 */
window.YILIN = {
"1-1":"道陟石阪，胡言連謇。譯瘖且聾，莫使道通。請謁不行，求事無功。",
"1-2":"招禍來螫，害我邦國。病在手足，不得安息。",
"1-3":"陽孤亢極，多所恨惑。車傾盖亡，身常憂惶。乃得其願，雌雄相從。",
"1-4":"鴶鵴鳲鳩，專一無尤。君子是則，長受嘉福。",
"1-5":"目瞤足動，喜如其願，舉家蒙寵。",
"1-6":"龍馬上山，絕無水泉。喉噍唇乾，舌不能言。",
"1-7":"倉盈𢈔億，宜稼黍稷。國家富有，民人蕃息。",
"1-8":"中夜狗吠，盜在墻外。神明祐助，銷散皆去。",
"1-9":"据斗運樞，順天無憂。與樂並居。",
"1-10":"空拳握手，倒地更起。富饒豐衍，快樂無巳。",
"1-11":"不風不雨，白日皎皎。宜出驅馳，通利大道。",
"1-12":"戴日精光，驂駕六龍。祿命徹天，封為燕王。",
"1-13":"子號索哺，母行求食。反見空巢，訾我長息。",
"1-14":"上帝之生，福祐日成。修德行惠，樂安且寧。",
"1-15":"山險難登，澗中多石。車馳轊擊，載重傷軸。儋負善躓，跌踒右足。",
"1-16":"禹鑿龍門，通利水源。東注滄海，民得安存。",
"1-17":"乘龍上天，兩蛇為輔。踴躍雲中，遊觀滄海。安樂長處。",
"1-18":"彭祖九子，據得不殆。南山松柏，長受嘉福。",
"1-19":"南山昊天，刺政關身。疾悲無辜，背憎為仇。",
"1-20":"江河淮海，天之奧府。眾利所聚，可以饒有。樂我君子，百福是受。",
"1-21":"堅冰黃鳥，啼哀悲愁。不見甘粒，但觀藜蒿。數驚鷙鳥，為我心憂。",
"1-22":"室如懸磬，既危且殆。蚤見之士，依山處谷。",
"1-23":"大禹式路，蚩尤除道。周匝萬里，不危不殆。見其所使，無所不在。",
"1-24":"三人為旅，俱歸北海。入門昇堂，拜謁王母，勞賜我酒。",
"1-25":"傳言相誤，非干徑路。鳴鼓逐狐，不知跡處。",
"1-26":"三羊爭雌，相逐奔馳。終日不食，精氣勞疲。",
"1-27":"純服黃裳，戴上與與。德義以生，天下歸仁。",
"1-28":"桀跖並處，人民勞苦。雍兵荷糧，戰於齊魯。",
"1-29":"黃鳥采菉，既嫁不荅。念我父兄，思復邦國。",
"1-30":"胎生孚乳，長息成就。充滿帝室，家國昌富。",
"1-31":"三人求橘，反得丹穴。女貴以富，黃金百鎰。",
"1-32":"東山西岳，會合俱食。百家送從，以成恩福。",
"1-33":"弱雞無距，與鵲交鬥。翅折目盲，為鳩所傷。",
"1-34":"隙大墻壞，蠹眾木折。狼虎為政，天降罪罰。高弑望夷，胡亥以斃。",
"1-35":"三痴俱走，迷路失道。或不知歸，反入患口。",
"1-36":"弓矢俱張，弝彈折弦。丸發不至，道遇害患。",
"1-37":"三女求夫，伺候山隅。不見復關，長思歎憂。",
"1-38":"陽旱炎炎，傷害禾糓。穡人無食，耕夫歎息。",
"1-39":"騎㹠逐羊，不見所望。經涉虎穴，亡羊失羔。",
"1-40":"闇昧冥語，轉相詿誤。鬼魅所舍，誰知臥處。",
"1-41":"姬姜祥淑，二人偶食。論仁議福，以安王室。",
"1-42":"公孫駕𮪜，載眄東齊。延陵說產，遺季紵衣。",
"1-43":"孤竹之墟，失婦亡夫，傷於蒺藜，不見少妻。東郭棠姜，武氏以亡。",
"1-44":"仁政不暴，鳳凰來舍。四時順節，民安其處。",
"1-45":"任劣力薄，駑孱恐怯，如猬見鵲，不敢拒格。",
"1-46":"衛侯東遊，惑於少姬。亡我考妣，久迷不來。",
"1-47":"噂噂所言，莫知我垣。歡喜堅固，可以長安。",
"1-48":"鸑鳴岐山，龜應幽淵。男女搆精，萬物化生。文王以成，為周開庭。",
"1-49":"玄黃虺隤，行者勞疲。役夫憔悴，踰時不歸。",
"1-50":"弱足刖跟，不利出門。市賈無利，折亡為患。",
"1-51":"懸狟素饕，居非其官。失輿剝廬，休坐徙居。",
"1-52":"民怯城惡，姦人所伏。寇賊大至，入我郛郭，妻子俘獲。",
"1-53":"陽低頭，陰仰首。水為災，傷我足。進不利，難生子。",
"1-54":"背北相憎，心意不同，如火與金。",
"1-55":"太徽帝室，黃帝所宜。蕃屏周衛，不可得入，常安無患。",
"1-56":"繭栗犧牲，敬享鬼神。神嗜飲食，受福多孫。",
"1-57":"出門逢惡，與禍為怨。更相擊刺，傷我手端。",
"1-58":"鷁飛中退，舉事不遂。眾人亂潰。",
"1-59":"跛踦相隨，日暮牛罷。陵遲後旅，失利亡雌。",
"1-60":"龍角博預，位至公卿。世祿久長，起動安寧。",
"1-61":"舜升大禹，石夷之野。徵詣王庭，拜治水圡。",
"1-62":"從風放火，荻芝俱死。三害集房，叔子中傷。",
"1-63":"楩生荊山，命制輸班。袍衣剝脫，夏熱冬寒。飢餓枯槁，莫人震憐。",
"1-64":"長面大鼻，來解已憂。遺吾福子，與我惠妻。惠吾嘉喜。",
"2-1":"谷風布氣，萬物出生。萌庶長養，華葉茂成。",
"2-2":"不風不雨，白日皎皎。宜出驅馳，通利大道。",
"2-3":"蒼龍單獨，與石相觸。摧折兩角，家室不足。",
"2-4":"城上有烏，自名破家。招呼酖毒，為國患災。",
"2-5":"霜降閉戶，蟄虫隱處。不見日月，與死為伍。",
"2-6":"天之德室，溫仁受福。衣裳所在，凶惡不起。",
"2-7":"皇階九重，絕不可登。未見王公，謂天蓋高。",
"2-8":"孔德如玉，出於幽谷。升高鼓翼，輝光照國。",
"2-9":"五軛四軌，復得饒有。陳力就列，騶虞悅喜。",
"2-10":"四足無角，君子所服。南征𫐠職，以惠我國。",
"2-11":"雷行相逐，無有攸息。戰于平陸，為夷所覆。",
"2-12":"六龍爭極，服在下飾。謹慎管籥，結禁毋出。",
"2-13":"長男少女，相向共語。福祿歡喜。",
"2-14":"奸延惡人，使德不通。炎火為殃，年榖大傷。",
"2-15":"脩其翰翼，隨風向北。至虞夏國，與舜相得。年歲大樂，邑無盜賊。",
"2-16":"鉛刀攻玉，堅不可得。盡我筋力，胝繭為疾。",
"2-17":"舉被覆目，不見日月。衣衾簠簋，就長夜室。",
"2-18":"賊仁傷德，天怒不福。斬刈宗社，失其邦域。",
"2-19":"白龍赤虎，戰鬥俱怒。蚩尤敗走，死於魚口。",
"2-20":"北辰紫宮，衣冠立中。含和建德，常受天福。",
"2-21":"稷為堯使，西見王母。拜請百福，賜我善子。",
"2-22":"三人異趨，反覆迷惑。一身五心，亂無所得。",
"2-23":"南山大玃，盜我媚妾。怯不敢逐，退然獨宿。",
"2-24":"眾鬼所趨，反作大怪。九身無頭，魂驚魄去，不可以居。",
"2-25":"延頸遠望，眯為目疾。不見叔姬，使伯心憂。",
"2-26":"典冊法書，藏在蘭臺。雖遭亂潰，獨不遇災。",
"2-27":"自衛反魯，時不我與。冰炭異室，仁道隔塞。",
"2-28":"瘤癭禿疥，為身瘡害。病疾癃殘，常不遠逮。",
"2-29":"齊東郭盧，嫁我洛都。俊良美好，媒利過倍。",
"2-30":"齊魯爭言，戰於龍門。構怨連禍，三世不安。",
"2-31":"芳澤肥壤，農人豐敵。利居長安，歷世無患。",
"2-32":"倉盈𢈔憶，宜種黍稷。年豐歲熟，民得安息。",
"2-33":"鴟鴞破斧，邦人危殆。賴其忠德，轉禍為福。負危復立。",
"2-34":"歲飢無年，虐政害民。乾溪驪山，秦楚結冤。",
"2-35":"椡挈累累，締結難解。嫫母衙嫁，媒不得坐。自為身禍。",
"2-36":"訾陬開門，鵲鳴彈冠。章甫進用，舞韶和鸞。三人翼事，國無災患。",
"2-37":"弟姊合居，與類相扶。願慕群醜，不離其處。",
"2-38":"邯鄲反言，兄弟生患。涉叔憂恨，卒死不還。",
"2-39":"三人逐兔，各爭有得。愛亡善走，多獲鹿子。",
"2-40":"北辰紫宮，衣冠立中。含和建德，常受天福。",
"2-41":"拜跪請免，不得其哺。俛首銜枝，低頭北去。",
"2-42":"鶴盜我珠，逃於東隅。求之郭墟，不見所居。",
"2-43":"一簧兩舌，妄言𮘸語。三姦成虎，曾母投杼。",
"2-44":"孤獨特處，莫與為旅。身日勞苦，使布五榖。陰陽順序。伯虎仲熊，德乂四布。",
"2-45":"褰衣涉河，澗流浚多。賴遇舟子，濟脫無他。",
"2-46":"憑河登山，道里阻難，求事少便。",
"2-47":"兔置之容，不失其㳟。和謙致樂，君子攸同。",
"2-48":"三女求夫，伺候山隅。不見復關，泣涕漣如。",
"2-49":"螟蟲為賊，害我黍榖。中霤空虛，家無所食。",
"2-50":"望尚阿衡，太宰周公。藩屏輔弼，福祿來同。",
"2-51":"三年生狗，以戌為母。荊夷上侵，姬伯出走。",
"2-52":"塗遏道塞，求事不得。",
"2-53":"探懷得蚤，無有凶憂。所願失道，善居漸好。",
"2-54":"飛樓屬道，趾多攪垣。居之不安，覆壓為患。",
"2-55":"義不勝情，以欲自傾。幾利危寵，折角摧頸。",
"2-56":"潼滃蔚薈，林木來會。津液下降，流潦霈霈。",
"2-57":"白駒生芻，猗猗盛姝。赫咺君子，樂以忘憂。",
"2-58":"車馳人趨，卷甲相仇。齊魯寇戰，敗於犬丘。",
"2-59":"舉首望城，不見子貞，使我悔生。",
"2-60":"龍鬥時門，失理傷賢。內畔外賊，則生禍難。",
"2-61":"安如太山，福喜屢臻。雖有豺虎，不致危身。",
"2-62":"初憂後喜，與福為市。八佾列陳，飲御嘉友。",
"2-63":"持刃操肉，對酒不食。夫行從軍，小子入獄，抱膝獨宿。",
"2-64":"陰衰老極，陽建其德。履离戴光，天下昭明。功業不長，蝦蟆代王。",
"3-1":"汎汎柏舟，流行不休。耿耿寤寐，心裡大憂。仁不逢時，復隱窮居。",
"3-2":"采薪得麟，大命隕顛。豪雄爭名，天下四分。",
"3-3":"兵征大宛，北出玉門。與胡寇戰，平城道西。七日絕糧，身幾不全。",
"3-4":"山崩谷絕，天福盡竭。涇渭失紀，玉歷既巳。",
"3-5":"夏臺羑里，湯文所厄。鬼侯俞賄，商王解舍。",
"3-6":"泥滓汙辱，棄捐溝瀆。為眾笑哭，然不顯録。",
"3-7":"李梅冬實，國多盜賊。擾亂並作，君不能息。",
"3-8":"獐鹿逐牧，飽歸其居。反還次舍，無有疾故。",
"3-9":"夾河為婚，期至無船。搖心失望，不見所歡。",
"3-10":"百足俱行，相輔為強。三聖翼事，王室寵光。",
"3-11":"坐立失處，不能自居。賊破王邑，陰陽顛倒。",
"3-12":"登几上轝，駕駟南遊。合從散衡，燕齊以強。",
"3-13":"三孫荷弩，無益於輔。城弱不守，邦君受討。",
"3-14":"河伯大呼，津不可渡。船空無人，往來亦難。",
"3-15":"甘露醴泉，太平機關。仁德感應，歲樂民安。",
"3-16":"重茵厚席，循皋采藿。雖躓不懼，反復其處。猿墮高木，不踒手足。還歸其室，保我金玉。",
"3-17":"太一駕騮，從天上來。徵我叔季，封為魯侯。",
"3-18":"南巴六安，石解㦸天。所指不巳，耋老復丁。弊室舊墟，更為新家。",
"3-19":"家給人足，頌聲並作。四夷賓伏，干戈韜閣。",
"3-20":"東鄰嫁女，為王妃后。莊公築館，以尊王母。歸于京師，季姜說喜。",
"3-21":"陳妻敬仲，兆興齊姜。營丘是適，八世大昌。",
"3-22":"路多枳棘，步刺我足。不利旅客，為心作毒。",
"3-23":"天宮列宿，五神共舍。宮闕光堅，君安其居。",
"3-24":"牧羊稻園，聞虎呻喧，懼畏惕息，終無禍患。",
"3-25":"鳴條之圖，北奔犬胡。左袵為長，國𭈹匈奴。主君旄頭，立尊單于。",
"3-26":"剋身潔巳，逢禹巡守。錫我玄珪，拜受福祐。",
"3-27":"冬華不食，國多盜賊。疾病難醫，鬼哭其室。",
"3-28":"襄送季女，至于蕩道。齊子旦夕，留連久處。",
"3-29":"朽根倒樹，花葉落去。卒逢火焱，隨風偃仆。",
"3-30":"陰變為陽，女化作男。治道得通，君臣相承。",
"3-31":"炎絕續光，火滅復明。簡易理得，以成乾功。",
"3-32":"多載重負，捐棄於野。予母誰子，但自勞苦。",
"3-33":"江河海澤，眾利室宅。可以富有，飲御嘉客。",
"3-34":"冬採薇蘭，地凍堅拆。利走室北，暮毋所得。",
"3-35":"烏鳴嘻嘻，天火將起。燔我館屋，災及妃后。",
"3-36":"蠆室蜂戶，螫我手足。不可進取，為身害速。蠆螫我足，蜂螫我手。",
"3-37":"崔嵬北岳，天神貴客。溫人正直，主布恩德。開衣不巳，蒙受大祿。",
"3-38":"伯蹇叔盲，莫與守牧。失我衣裘，代已除服。",
"3-39":"為季求婦，家在東海。水長無船，不見所懽。",
"3-40":"山陵丘墓，魂魄室舍。精誠盡竭，長寢不覺。",
"3-41":"騎牛折角，下山傷軸，失其利祿。",
"3-42":"水載舟船，無根以浮。往來濟濟，心勞且憂。",
"3-43":"有鳥來飛，集于宮樹。鳴聲可惡，主將出去。",
"3-44":"東徙不時，觸患離憂。井泥無濡，思叔舊居。",
"3-45":"黃帝所生，宓羲之宇。兵刃不至，利以居止。",
"3-46":"東山救亂，處婦思夫。勞我君子，役無休巳。",
"3-47":"跛躓未起，先利後市，不得鹿子。",
"3-48":"大蛇當路，使季畏懼。湯火之災，切近我膚。賴其天𦍒，趨于王廬。",
"3-49":"魚鱉列市，河海饒有。長錢善價，商李悅喜。",
"3-50":"區脫康居，慕義入朝。湛露之懽，三爵畢恩。後歸野廬，與母相扶。",
"3-51":"從容常閑，遊戲南山。拜祠禱神，使神無患。",
"3-52":"年常蒙慶，今歲受福。三夫採葩，出必有得。",
"3-53":"二人俱東，道怒爭訟。意乖不同，使君忷忷。",
"3-54":"樹我藿豆，鹿兔為食。君不恤護，秋無收入。",
"3-55":"黃鳥悲鳴，愁不見星。因於鷙鳥，鸇使我驚。",
"3-56":"雙鳧惧飛，欲歸稻食。經涉龿澤，為矢所射，傷我胸臆。",
"3-57":"久客無依，思歸我鄉。雷雨盛溢，道未得通。",
"3-58":"道路辟除，南至東遼。衛子善辭，使國無憂。",
"3-59":"同枕同袍，中年相知。少賈無失，獨居愁思。",
"3-60":"眾神集聚，相與議語。南國虐亂，百姓愁苦。興師征討，更立賢主。",
"3-61":"北陸閉蟄，隱伏不出。目盲耳聾，道路不通。",
"3-62":"痴狂妄作，心狂善惑。迷行失路，不知南北。",
"3-63":"棟隆強輔，寵貴日光。福善並作，樂以高明。",
"3-64":"愛我嬰女，牽衣不與。冀幸高貴，反日賤下。",
"4-1":"海為水王，聰聖且明。百流歸德，無有叛逆。常饒優足。",
"4-2":"天之所有，禍不過家。左輔右弼，金玉滿堂。常盈不亡，富如敖倉。",
"4-3":"安息康居，異國穹廬。非吾習俗，使我心憂。",
"4-4":"何草不黃，至未盡玄。室家分離，悲憂於心。",
"4-5":"范公鴟夷，善賈飾資。東之營丘，易字子皮。把珠戴金，多得利歸。",
"4-6":"老楊日衰，條多枯枝。爵級不進，遂下摧隤。",
"4-7":"小孤渡水，汙濡其尾。利得無幾，與道合契。",
"4-8":"豕生魚魴，鼠舞庭堂。姦佞施毒，上下昏荒，君失其國。",
"4-9":"天地配享，六位光明。陰陽順敘，以成和平。",
"4-10":"踝踵足傷，右足病擁。失旅後時，利走不來。",
"4-11":"異體殊患，各有所屬。西鄰孤嫗，欲寄我室。王母罵詈，求不可得。",
"4-12":"操穜鄉畝，折貨稷黍。飲食充口，安利無咎。",
"4-13":"所受大喜，福祿重來。樂且日富，蒙慶得財。",
"4-14":"舉盃飲酒，無益溫寒。指直失取，亡利不歡。",
"4-15":"日月相望，光明盛昌。三聖茂承，功德大𨺚。",
"4-16":"猾夫爭強，民去其鄉。公孫叔子，戰於瀟湘。",
"4-17":"猿墮高木，不踒手足。還歸其室，保我金玉。",
"4-18":"逐狐東山，水遏我前。深不可涉，失利後便。",
"4-19":"鑿井求玉，非卞氏寶。名因身辱，勞無所得。",
"4-20":"黃玉溫厚，君子所服。甘露溽暑，萬物生茂。",
"4-21":"畫龍頭頸，文章不成。甘言善語，說辭無名。",
"4-22":"招禍致凶，來弊我邦。病在手足，不得安息。",
"4-23":"履位乘勢，靡有絕斃。皆為𨽻圉，與眾庶位。",
"4-24":"獐鹿雉兔，群聚東囿。盧黃白脊，俱往趨逐。九齚十得，君子有喜。",
"4-25":"織錦未成，緯盡無名。長子逐兔，鹿起失路。後利不得，因無所據。",
"4-26":"天厭周德，命與仁國。以禮静民，兵革休息。",
"4-27":"重譯賀芝，來除我憂。善說遂良，與喜相求。",
"4-28":"膏壤肥澤，人民孔樂。宜利居止，長安富貴。",
"4-29":"白龍黑虎，起鬐暴怒。戰於涿鹿，蚩尤敗走。居止不殆，君安其所。",
"4-30":"抱關傳語，聾跛摧殆。眾賤無下，災殃所在。",
"4-31":"憂禍解除，喜至慶來。坐立歡門，與樂為鄰。",
"4-32":"折鋒戴殳，轝馬放休。行軍依營，天下安寧。",
"4-33":"至德之君，仁政且溫。伊呂股肱，國富民安。",
"4-34":"千里望城，不見山青，老兔蝦蟆，遠絕無家。",
"4-35":"有莘季女，為夏妃后。貴夫壽子，母字四海。",
"4-36":"不虞之患，禍至無門。奄忽暴卒，痛傷我心。",
"4-37":"飛鷹退去，不食鄰鳥。憂患解除，主君安居。",
"4-38":"跮差側跌，申酉為祟。亥戍滅明，顏子隱藏。",
"4-39":"司祿憑怒，謀議無道。商氏失政，殷人乏祀。",
"4-40":"望雞得雉，冀馬獲駒。大德生少，有瘳從居。",
"4-41":"忉忉怛怛，如將不活。黍稷之恩，靈輒以存。",
"4-42":"莫莫輯輯，夜作晝匿。謀議我資，求攻我室。空盡以財，幾無以食。",
"4-43":"天之所壞，不可強支。眾口指笑，雖貴必危。",
"4-44":"目動睫瞤，喜來加身。舉家蒙歡，吉利無殃。",
"4-45":"黿𡙡芬薌，染指弗嘗。口飢於手，子公恨饞。",
"4-46":"天福所豐，兆如飛龍。成子得志，六二以興。",
"4-47":"氓伯易𢇁，抱布自媒。棄禮急情，卒離悔憂。",
"4-48":"三人為旅，俱歸北海。入門上堂，拜謁王母。勞賜我酒，歡樂無疆。",
"4-49":"愆淫旱疾，傷害稼穡。喪制病來，農人無食。",
"4-50":"攫飯把肉，以就口食。萬往必得，無有虛乏。",
"4-51":"夏姬親附，心聽悅喜。利以搏取，無言不許。",
"4-52":"南山昊天，刺政閔身。疾悲無辜，背憎為仇。",
"4-53":"鳥飛無翼，兔走折足。雖欲會同，未得所欲。",
"4-54":"體重飛難，未能踰關。不離室垣。",
"4-55":"四雄並處，人民愁苦。擁兵西東，不得安所。",
"4-56":"重驛關牢，求解巳憂。心惑乃成，與喜俱居。",
"4-57":"患解憂除，皇母相於。與喜俱來，使我安居。",
"4-58":"冬生不華，老女無家。霜冷蓬室，更為枯株。",
"4-59":"震慄恐懼，多所畏惡。行道留難，不可以步。",
"4-60":"三人共妻，莫適為雌。子無名氏，公不可知。",
"4-61":"草彫被霜，花葉不長。非時為落，家受其殃。",
"4-62":"雉兔之東，狼虎所從。貪叨凶惡，不可止息。",
"4-63":"馬驚車破，主墮深溝。身死魂去，離其室廬。",
"4-64":"山林麓藪，非人所處。鳥獸無禮，使我心苦。",
"5-1":"火滅復息，君明其德。仁人可遇，身受利福。",
"5-2":"溫山松柏，常茂不落。鸞鳳以庇，得其歡樂。",
"5-3":"西誅不復，恃強負力。倍道趨敵，師徒敗覆。",
"5-4":"三塗五嶽，陽城太室。神明所伏，獨無兵革。",
"5-5":"久旱三年，草木不生。粢盛空乏，無以供靈。",
"5-6":"二牛生狗，以戍為母。荊夷上侵，姬伯出走。",
"5-7":"鳧遊江海，役行千里，以為死亡。復見空素，長主凶憂。",
"5-8":"太一駕騮，從天上求。徵召叔季，封為魯侯。無有凶憂。",
"5-9":"絍績獨居，寡處無夫。陰陽失忘，為人僕使。",
"5-10":"兵征大宛，北出玉門。與胡寇戰，平城道西。七日絕糧，身幾不全。",
"5-11":"楚靈暴虐，罷極民力。禍起乾谿，棄疾作毒。扶伏奔逃，死申亥室。",
"5-12":"雌單獨居，歸其本巢。毛羽憔悴，志如死灰。",
"5-13":"兩矛相刺，勇力鈞敵。交綏結和，不破不缺。",
"5-14":"乘船渡濟，載水逢火。賴幸免患，蒙我生全。",
"5-15":"喪寵溢尤，政傾家覆。我宗失國，秦滅周室。",
"5-16":"冬無藏冰，春陽不通。陰流為賊，國被其殃。",
"5-17":"田鼠野雞，意常欲逃。拘制籠檻，不得動搖。",
"5-18":"佩玉蕊𠔃，無所繫之。旨酒一盛，莫與笑語。孤寡獨特，常愁憂苦。",
"5-19":"沒遊原口，求鮫為寶。家危自懼，復出生道。",
"5-20":"河水孔穴，壞敗我室。水深無岸，魚鱉傾側。",
"5-21":"教羊牧兔，使魚相捕。任非其人，費日無功。",
"5-22":"升戶入室，就溫燠食。水凍北陸，不能相賊。",
"5-23":"孤竹之墟，老婦無夫。傷於蒺蔾，不見少妻。東郭棠姜，武氏破亡。",
"5-24":"凶憂災殃，日益明章。福不可屋，三郤痍傷。",
"5-25":"戴璧秉珪，請命于河。周公作誓，沖人瘳愈。",
"5-26":"鳥升鵲舉，照臨東海。尨降庭堅，為陶叔後。封圻英六，履祿綏厚。",
"5-27":"危坐至暮，請求不得。膏澤不降，政戾民忒。",
"5-28":"宜昌娶婦，東家歌舞。燕樂有序，長樂嘉喜。",
"5-29":"鑿井求玉，非卞和寶。名困身辱，勞無所得。",
"5-30":"鵠思其雄，欲隨鳳東。順理羽翼，出次須日。中留北邑，復反其室。",
"5-31":"早霜晚雪，傷害禾麥。損功棄力，飢無所食。",
"5-32":"蝙䘃生子，深目黑醜。雖飾相就，眾人莫取。",
"5-33":"去如飛鴻，避凶直東。遂得全脫，與福相逢。",
"5-34":"婚姻合配，同枕共牢。以降嘉休，子孫封侯。",
"5-35":"咸陽辰巳，長安戌亥。丘陵生止，非魚鰍市。不可辭阻，終無悔咎。",
"5-36":"螟蟲為賊，害我五榖。簞食空虛，家無所食。",
"5-37":"謀恩拜德，東歸吾國。慷慨歡笑，歡樂有福。",
"5-38":"齎貝贖貍，不聽我辤。繫於虎鬚，牽不得來。",
"5-39":"比目附翼，歡樂相得。行止集周，終不離忒。",
"5-40":"一指食肉，口無所得。染其鼎鼐，舌饞於腹。",
"5-41":"曳綸江海，釣挂魴鯉。王孫利德，以饗仲友。",
"5-42":"商紂牧野，顛敗所在。賦歛重數，黎元愁苦。",
"5-43":"北辰紫宮，衣冠中立。含和建德，常受天福。",
"5-44":"輕戰上勇，不知兵權。為敵所制，從師北奔。",
"5-45":"大口宣唇，神使仲言。黃龍景星，出應德門。與福上天，天下安昌。",
"5-46":"凶子禍孫，伏劍向門。凶訟讙囂，驚駭我家。",
"5-47":"祝伯善言，能事鬼神。拜辭萬歲，使君延年。",
"5-48":"珪璧琮璋，執贄見王。百里寗越，應聘齊秦。",
"5-49":"昧旦乘車，履危陷溝。亡失裠𥜗，摧折兩軸。",
"5-50":"膠著木連，不出牛攔。斯享羔羊，家室相安。",
"5-51":"卷領遁世，仁德不舍。三聖攸同，周國茂興。",
"5-52":"黍稷苗稻，垂秀方造。中旱不雨，傷風枯槁。",
"5-53":"冠帶南遊，與福喜逢。期於嘉貞，拜為公卿。",
"5-54":"一巢九子，同公共母。柔順利貞，出入不殆，福祿所在。",
"5-55":"韓氏長女，嫁於東海。宜家富主，柔順以居，利得過倍。",
"5-56":"因禍受福，喜盈我室，所願必得。",
"5-57":"晉平有疾，迎醫秦國。病乃大患，分為二豎。逃匿膏肓，和不能愈。",
"5-58":"杜飛門啟，患憂大解。修福行善，不為身禍。",
"5-59":"追亡逐北，至止而得。稚叔相呼，反其室廬。",
"5-60":"鳥鳴廐端，一呼三顛。搖動東西，危慄不安，疾病無患。",
"5-61":"龍化為虎，太山之陽。眾多從者，莫敢敉藏。",
"5-62":"猋風忽起，車馳揭揭。棄名追亡，失其和節，憂心恨恨。",
"5-63":"遊居石門，祿安身全。受福西鄰，歸飲玉泉。",
"5-64":"登高上山，見王自言。申理我讒，得職蒙恩。",
"6-1":"文王四乳，仁愛篤厚。子畜十男，夭折無有。",
"6-2":"日入望東，不見子家。長女無夫，左手搔頭。",
"6-3":"東上太山，見堯自言。申理我冤，以解憂患。",
"6-4":"奎軫溫湯，過角宿房。宣時布和，無所不通。",
"6-5":"引船牽頭，雖拘無憂。王母善禱，禍不成災。",
"6-6":"文巧俗𡚁，將反大質。僵死如麻，流血濡樐。皆知其母，不識其父，干戈乃止。",
"6-7":"鳧得水沒，喜笑自啄。毛羽悅懌，利以攻玉。公出不復，伯氏客宿。",
"6-8":"水流趨下，欲至東海。求我所有，買魴與鯉。足關路止。",
"6-9":"獐鹿逐牧，安飽其居。反還次舍，無有疾故。",
"6-10":"樹植藿豆，不得芸鋤。王事無盬，秋無所收。",
"6-11":"弱水之西，有西王母。生不知死，與天相保。",
"6-12":"數窮廓落，困於歷室。卒登玉堂，與堯侑食。",
"6-13":"子鉏執麟，春秋作元。陰聖將終，尼父悲心。",
"6-14":"尹氏伯奇，父子生離。無罪被辜，長舌所為。",
"6-15":"蟠枚折枝，與母別離。九皋難扣，絕不相知。",
"6-16":"弱雞無距，與鵲格𨷖。趐折目盲，為鳩所傷。",
"6-17":"甲乙丙丁，俱歸我庭。三丑六子，入門見母。",
"6-18":"桑葉螟蠹，衣弊如絡。女功不成，絲布為玉。",
"6-19":"關牢闢門，巡狩釋冤。夏臺羑里，湯文悅喜。",
"6-20":"欽明之德，坐前玉食。必保嘉美，長受安福。",
"6-21":"武夫司空，多口爭訟。金火當戶，民不安處。年飢無有。",
"6-22":"紫閣九重，尊嚴在中。黃帝堯舜，履行至公。冠帶垂裳，天下康寧。",
"6-23":"負牛上山，力劣行難。烈風雨雪，遮遏我前。出道復還，憂者自歡。",
"6-24":"蹇兔缺唇，行難齒寒。口病不言，為身生患。",
"6-25":"合體比翼，嘉偶相得。與君同好，使我有福。",
"6-26":"口啄卒卒，憂從中出。喪我寶貝，妻妾失位。",
"6-27":"兩心不同，或從西東。明論中日，莫適相從。",
"6-28":"啞啞笑言，與善飲食。長樂行觴，千秋起舞，拜受大福。",
"6-29":"初憂後喜，與福為市。八佾列陳，飲御嘉友。",
"6-30":"西徙無家，破其新車。王孫失利，不如止居。",
"6-31":"鳳凰在左，麒麟處右。仁聖相遇，伊呂集聚。時無殃咎，福為我母。",
"6-32":"甌脫康居，慕仁入朝。湛露之歡，三爵畢恩。復歸舊廬。",
"6-33":"疾貧望幸，使伯行販。關牢擇羊，多得大牂。",
"6-34":"處高不傷，雖危不亡。握珠懷玉，還歸其鄉。",
"6-35":"右手棄酒，左手牧牂。行逢禮御，餌得玉杯。",
"6-36":"養虎牧狼，還自賊傷。大勇小捷，雖危不亡。",
"6-37":"戴堯扶禹，從喬彭祖。西過王母，道路夷易。無敢難者。",
"6-38":"秋冬探巢，不得鵲鶵。銜指北去，塊我少姬。",
"6-39":"兩羝三牂，俱之代鄉。留連多難，損其食糧。",
"6-40":"南徙無廬，烏破其巢。伐木思初，不利動搖。",
"6-41":"爭訟不巳，更相擊劍。張季弱口，披𩬊北走。",
"6-42":"延頸望酒，不入我口。初喜後否，得利無有。",
"6-43":"被𩬊傾走，寇逐我後。亡失刀兵，身全不傷。",
"6-44":"麟鳳所遊，安樂無憂。君子撫民，世代千秋。",
"6-45":"褰衣涉河，水深漬罷。賴幸舟子，濟脫無他。",
"6-46":"憒憒不悅，憂從中出。荅我金罌，無妄失位。",
"6-47":"絆跳不遠，心與言反。尼父望家，菡蓞未華。",
"6-48":"大壯肥牸，惠我諸舅。內外和穆，不憂飢渴。",
"6-49":"黃帝建元，文德在身。祿若陽春，封為魯君。",
"6-50":"虎聚摩牙，以待豚豬。往必傷亡，宜利止居。",
"6-51":"天地配享，六位光明。陰陽順序，以成和平。",
"6-52":"猿墜高木，不踒手足。保我金玉，還歸其室。",
"6-53":"營室紫宮，堅不可攻。明神建德，君受大福。",
"6-54":"孤翁寡婦，獨宿悲苦。目張耳明，無與笑語。",
"6-55":"低頭窺視，有所畏避。行者不利，酒酸魚敗。眾莫貪嗜。",
"6-56":"載金販狗，利棄我走。藏匿淵底，悔折為咎。",
"6-57":"行觸大忌，與司命牾。執囚束縳，拘制於吏。",
"6-58":"執玉歡喜，佩之解攣。危詳反安，使我無患。",
"6-59":"機杼紛擾，女巧不成。長妹許嫁，衣無𥜗褲。聞禍不成，凶惡消去。",
"6-60":"金人鐵距，火燒左右。雖懼不恐，獨得全處。",
"6-61":"謝恩拜德，東歸吾國。舞蹈欣躍，歡樂受福。",
"6-62":"青牛白咽，呼我俱田。歷山之下，可以多耕。歲樂時節，民人安寧。",
"6-63":"白雉群雊，慕德朝貢。湛露之恩，使我得懽。",
"6-64":"避患東西，反入禍門。糟糠不足，憂愁我心。",
"7-1":"一簧兩舌，佞言謟語。三姦成市，曾母投杼。",
"7-2":"春桃生花，季女宜家。受福且多，在師中吉，男為封君。",
"7-3":"殊類異路，心不相慕。壯牛牡猳，獨無室家。",
"7-4":"折苦蔽目，不見稚叔。三足孤烏，遠其元夫。",
"7-5":"雀東求粒，誤入罔域。賴仁君子，脫腹歸息。",
"7-6":"王孫季子，相與孝友。明允篤誠，升擢家舉，為國榦輔。",
"7-7":"烏鳴呼子，哺以酒脯。高樓之處，子來歸母。穡人成功，年歲大有，姤婦無子。",
"7-8":"刖樹無枝，與子分離。飢寒莫食，獨泣哀悲。",
"7-9":"舜升大禹，石夷之野。徵詣玉闕，拜理水土。",
"7-10":"義不勝情，以欲自營。見利危寵，滅君令名。",
"7-11":"三人北行，六位光明。道逢淑女，與我驥子。",
"7-12":"羿張烏號，彀射天狼。柱國雄勇，鬥死榮陽。",
"7-13":"季姬踟躕，結袊待時。終日至暮，百兩不來。",
"7-14":"鴻鴈翩翩，始怨苦勞。災疫病民，鰥寡愁憂。",
"7-15":"穿胸狗邦，僵离旁美。天地易紀，日月更始。",
"7-16":"北山有棗，使叔壽考。東嶺多粟，宜行賈市。陸梁雌雉，所至利喜。",
"7-17":"干旄旌旗，撫幟在郊。雖有寶玉，無路致之。",
"7-18":"精潔淵塞，為讒所言。證訊詰問，繫於枳溫。甘棠聽斷，怡然蒙恩。",
"7-19":"玄黃瘣隤，行者勞罷。役夫憔悴，踰時不歸。",
"7-20":"膚敏之德，發憤晨食。虜豹禽說，以成德主。",
"7-21":"采唐沬鄉，要我桑中。失信不會，憂思約帶。",
"7-22":"伯寧子福，惠我邦國。蠲除苛殘，使季無患。",
"7-23":"讒言佞雄，敗亂邦國。生雖忠孝，敗恩不足。",
"7-24":"淵泉隄防，水道利通。順注湖海，邦國富有。",
"7-25":"江南多蝮，螫我手足。冤䌓詰屈，痛徹心腹。",
"7-26":"三人俱行，別離獨食。一身五心，反覆迷惑，亂無所得。",
"7-27":"鴉鳴庭中，以戒災凶。重門擊柝，備不速客。",
"7-28":"功成事就，拱手安居。立德有言，坐飾貢賦。",
"7-29":"國亂不安，兵革為患。掠我妻子，家中飢寒。",
"7-30":"戴堯扶禹，從喬彭祖。西過王母，道路夷易，無敢難者。",
"7-31":"長尾蜲蛇，畫地成河。深不可涉，絕無以比，惆悵會息。",
"7-32":"乘龍從蜺，徵詣北闕。乃見宣室，拜守東城。鎮慰𥠖元，舉家蒙福。",
"7-33":"土與山連，終身無患。天地高明，萬歲長安。",
"7-34":"久旱水涸，枯槁無澤。虛修其德，未有所獲。",
"7-35":"依天𠋣地，凶危不至。上清下浄，受福大明。君受其利。",
"7-36":"火烈不去，必殪僵仆。燔我衣裾，禍不可悔。",
"7-37":"配合相迎，利之四鄉。欣喜興釋，所言得當。",
"7-38":"清人高子，久屯外野。逍遙不歸，思我慈母。",
"7-39":"武庫軍府，甲兵所聚。非里邑居，不可舍止。",
"7-40":"三德五才，和合四時。陰陽順敘，國無咎災。",
"7-41":"解衣毛羽，飛入大都。晨門戒守，鄭忽失家。",
"7-42":"刖根燒株，不生飢膚。病在心腹，日以焦枯。",
"7-43":"文山紫芝，雍梁朱草。生長和氣，福祿多處。",
"7-44":"多載重負，棄捐于野。予母誰子，但自勞苦。",
"7-45":"鳧鴈啞啞，以水為家。雌雄相和，心至娛樂。得其歡欲。",
"7-46":"耳目盲聾，所言不通。佇立以泣，事無成功。",
"7-47":"天官列宿，五神所舍。宮闕堅固，君安其居。",
"7-48":"范子妙材，戮辱傷膚。然後相國，封為應侯。",
"7-49":"秋冬探巢，不得鵲雛。銜指北去，慚我少夫。",
"7-50":"子畏於匡，厄困陳蔡。德行不危，竟脫厄害。",
"7-51":"鴻飛在陸，公出不復。仲氏任止，伯氏客宿。",
"7-52":"鶴鳴九皋，避世隱居。抱朴守真，竟不隨時。",
"7-53":"舜升大禹，石夷之野。徵諸玊闕，拜治水土。",
"7-54":"左輔右弼，金玉滿堂。常盈不亡，富如敖倉。",
"7-55":"崔嵬北岳，天神貴客。衣冠不巳，蒙彼恩德。",
"7-56":"空槽注豬，獖彘不到。張弓祝雞，雄父飛去。",
"7-57":"胡蠻戎狄，大陰所積。涸冰凍寒，君子不存。",
"7-58":"甘露醴泉，太平機關。仁德感應，歲樂民安。",
"7-59":"惡來呼伯，慎驚外客。甲守閉宅，以備凶急。臨折之憂，將滅無災。",
"7-60":"日月相望，光明盛昌。三聖茂功，仁德大隆。",
"7-61":"葛藟蒙棘，華不得實。讒佞亂政，使恩壅塞。",
"7-62":"鄰不我顧，而望玉女。身多癩疾，誰肻媚者。",
"7-63":"精誠所在，神之為輔。德教尚忠，彌世長久。三聖尚功，多受福祐。",
"7-64":"鑽木求火，掘地索水。主母飢渴，手為心禍。",
"8-1":"繼祖復宗，追明成康。光照萬國，享世久長。",
"8-2":"取火流泉，釣魴山顛。魚不可得，火不肯燃。",
"8-3":"麟子鳳雛，生長家國。和氣所居，康樂溫仁。邦多聖人。",
"8-4":"彭名為娛，白龍作菑。盜堯舜裳，桀蹠荷兵。青禽照火，三日夷傷。",
"8-5":"黍稷醇釀，敬奉山宗。神嗜飲食，甘雨嘉降。庶物蕃殖，獨蒙福祉。",
"8-6":"李花再實，鴻飛降集。仁哲權輿，廕國受福。",
"8-7":"千歲之墟，大國所屠。不見子都，城空無家。",
"8-8":"鹿得美草，鳴呼其友。九族和穆，不憂飢乏。長子入獄，霜降族哭。",
"8-9":"公子王孫，把彈攝丸。發輒有得，室家饒足。",
"8-10":"驪姬讒喜，與二嬖謀。譛殺㳟子，害賊忠孝。申生以縊，重耳奔迯。",
"8-11":"長生無極，子孫千億。柏柱載青，堅固不傾。",
"8-12":"失意懷憂，如幽狴牢。亡子喪夫，附托寄居。",
"8-13":"仁智隱伏，麟不可得。龍蛇潛藏，虛居堂室。",
"8-14":"挒絜累累，締結難解。嫫母衒嫁，媒不得坐，自為身禍。",
"8-15":"蜩飛墮木，不毀頭足。保我羽翼，復歸其室。",
"8-16":"陳媯敬仲，兆興齊姜。乃適營丘，八世大昌。",
"8-17":"過時不歸，雄雌苦悲。徘徊外國，與母分離。",
"8-18":"齊魯爭言，戰於龍門。搆怨結禍，三世不安。",
"8-19":"府藏之富，王以振貸。捕魚河海，苟願多得。",
"8-20":"鳴鶴北飛，下就稻池。鱣鮪鰋鯉，眾多饒有。一狗獲兩，利得過倍。",
"8-21":"蒼梧鬱林，道易利通。元龜象齒，寶貝南金。為吾福功。",
"8-22":"兩火爭明，雖鬥不傷。分离且忍，全我弟兄。",
"8-23":"伯夷叔齊，貞廉之師。以德防患，憂禍不存。",
"8-24":"季去我東，𩬊櫛如蓬。展轉空抹，內懷憂傷。",
"8-25":"百足俱行，相輔為強。三聖翼事，王室𠖥光。",
"8-26":"壅遏隄防，水不得行。火盛陽光，陰蜺伏藏，退還其鄉。",
"8-27":"滕蛇乘龍，年歲飢凶，民食草蓬。",
"8-28":"鈆刀攻玉，堅不可得。盡我筋力，胝繭為候。",
"8-29":"恆山浦壽，高邑所在。陰氣下淋，洪水不處，勞人開戶。",
"8-30":"比目四翼，來安我國。福善上堂，與我同床。",
"8-31":"杜口結舌，心中拂鬱。去菑患生，莫所告冤。",
"8-32":"牽尾不前，逆理失臣，忠莫往來，衛朔以奔。",
"8-33":"早霜晚雪，傷害禾麥。損功棄力，飢無所食。",
"8-34":"適戌失期，患生無斯。懼以懷憂，發藏閉塞，邦國騷愁。",
"8-35":"昊天白日，照臨我國。萬民康寧，咸賴嘉福。",
"8-36":"元吉無咎，安寧不殆。時行則行，勿之有悔。",
"8-37":"懿公淺愚，不深受謀。無援失國，為狄所賊。",
"8-38":"城上有烏，自名破家。喚呼鴆毒，為國患災。",
"8-39":"長股善走，趨步千里。王良嘉言，伯來在道。申見王母。",
"8-40":"耕石山顛，費種家貧。無聊處作，苗𩬊不生。",
"8-41":"二人異路，東趨西步。千里之外，不相知處。",
"8-42":"純服黃裳，載土以興。德義茂生，天下歸仁。",
"8-43":"五銑鐵頤，倉庫空虛。賈市無盈，與利為仇。",
"8-44":"登崑崙，入天門。過糟丘，宿玉泉。問惠觀，見仁君。",
"8-45":"團團白日，為月所食。損上毀下，鄭昭出走。",
"8-46":"倉盈𢈔億，宜稼黍稷。年歲有息，國家富有。",
"8-47":"狼虎結謀，相聚為保。伺齧牛羊，道絕不通，傷我商人。",
"8-48":"木年摧折，常恐不活。老賴福慶，光榮輔相。",
"8-49":"同載共輿，中道分去。喪我元夫，獨為孤居。",
"8-50":"飲酒醉酗，跳躍爭鬥。伯傷叔僵，東家治喪。",
"8-51":"出值凶災，逢五赤頭。姚言死格，扶伏伏聽，不敢動搖。",
"8-52":"狼虎爭強，禮義不行。兼吞其國，齊晉無主。",
"8-53":"南國少子，才畧美好。求我長女，薄賤不與。反得醜惡，後乃大悔。",
"8-54":"一身兩頭，莫適其驅。亂不可治，孰為湯漢。",
"8-55":"李耳彚鵲，更相恐怯。偃爾以腹，不能距格。",
"8-56":"松柏棟梁，相輔為強。八哲五教，王室寧康。",
"8-57":"雀行求食，暮歸孚乳。反其室舍，安寧無故。",
"8-58":"四尾六頭，為凶作妖。陰不奉陽，上失其明。",
"8-59":"一衣三闕，結緝不便。歧道異路，日暮不到。",
"8-60":"牙孽生齒，室當啟戶。幽人利貞，鼓翼起舞。",
"8-61":"春鴻飛東，以馬質金。利得十倍，重載歸鄉。",
"8-62":"懽悅以喜，子孫具在。守發能忍，不見殃咎。",
"8-63":"精華消落，形體醜惡。齬齚挫頓，枯槁腐蠹。",
"8-64":"登高上山，見王自言。申理我冤，得職蒙恩。",
"9-1":"東過虎地，牛馬奔驚。道絕不通，南困無功。",
"9-2":"子鉏執麟，春秋作經。元聖將終，尼父悲心。",
"9-3":"取火泉源，釣魴山巔。魚不可得，火不可燃。",
"9-4":"機關不便，不能出言。精誠不通，為人所冤。",
"9-5":"故室舊廬，稍弊且除。不如新巢，可治樂居。",
"9-6":"蜲蛇循流，東求大魚。預且舉網，庖人謌謳。",
"9-7":"鑿山通道，南至嘉國。周公祝祖，襄適荊楚。",
"9-8":"鵲近郤縮，不見頭目。日以困急，不能自復。",
"9-9":"白鳥㗸餌，鳴呼其子。斡枝張翅，來從其母。伯仲叔季，尤賀舉手。",
"9-10":"五舌啄難，各自有言。異國殊俗，使心迷惑，所求不得。",
"9-11":"天門開闢，牢戶寥廓。桎梏解脫，拘囚縱釋。",
"9-12":"堅冰黃鳥，當哀悲秋。數驚鷙鳥，雛為我憂。",
"9-13":"日走月步，趨不同舍。夫妻反目，主君失居。",
"9-14":"金牙鐵齒，西王母子。無有患殃，扶舍涉道，到來不久。",
"9-15":"拭牧拭牧，憂禍相半。隔以巖山，室家分散。",
"9-16":"眾神聚集，相與議語。南國虛亂，百姓勞苦。興師征伐，更立賢主。",
"9-17":"狼虎爭食，禮義不行。兼吞其國，齊魯無主。",
"9-18":"寄生無根，如過浮雲。立本不固，斯須落去，更為枯樹。",
"9-19":"子啼索哺，母行求食。反見空巢，長息訾弋。",
"9-20":"駕駟逐狐，輪挂荊棘。車不結轍，公子無得。",
"9-21":"方喙廣口，仁智聖厚。釋解倒懸，唐國大安。",
"9-22":"駕福乘喜，來至家國。戴慶南行，離我安居。",
"9-23":"孔鯉伯魚，北至高奴。乘馬金車，駕遊大都。王毋送我，來牝字駒。",
"9-24":"三足無頭，不知所之。心狂精傷，莫使為明，不見日光。",
"9-25":"獹牝龍身，刄取三千。南止蒼梧，與福為婚。道里夷易，安全無患。",
"9-26":"辰次降婁，王駕巡時。廣祐施惠，安國無憂。",
"9-27":"望幸不到，文章未就。王子逐走，馬騎銜傷。昳跡不得，曷其有常。",
"9-28":"中原有菽，以待饔食。飲御諸友，所求大得。",
"9-29":"亂茅縮酒，靈巫拜禱。神怒不許，瘁愁憂苦。",
"9-30":"李花再實，鴻卵降集。仁哲以興，廕國受福。",
"9-31":"源出陵足，行於山趾。不為暴害，民得安處。",
"9-32":"客入其門，奔走東西。童女不織，士棄耕畝。暴骨千里，歲寒無年。",
"9-33":"天之所子，福祿常在。以永康寧，不憂危殆。",
"9-34":"蝗食我稻，驅不可去。實穂無有，但見空藳。",
"9-35":"牛驥同堂，郭氏巳亡。國破空虛，君奔走逃。",
"9-36":"狗無前足，陰謀其北。為身害賊，何以安息。",
"9-37":"兩輪自轉，南上大阪。四馬共轅，無有屯難。與禹笑言，鶴鳴竅穴，不離其室。",
"9-38":"牙孽生達，陽昌於外。左手執籥，公言錫爵。",
"9-39":"秋華冬蕚，數被嚴霜。甲兵當庭，萬物不生。雄犬夜鳴，民擾大驚。",
"9-40":"霜降閉戶，蟄虫隱處。不見日月，與死為伍。",
"9-41":"身載百里，功如四海。為文開基，武立大柱。",
"9-42":"禹作神鼎，伯益銜指。斧斤高閣，憧位獨坐。賣庸不讎，苦困為禍。",
"9-43":"福祚之家，喜至憂除。如風兼雨，出車入魚。如魚逢水，長樂受喜。",
"9-44":"倉龍隱伏，麟鳳遠匿。冠履同處，未得安息。",
"9-45":"旦生夕死，名曰嬰鬼。不可得視。",
"9-46":"白鶴銜珠，夜食為明。懷安德音，身受光榮。",
"9-47":"役行未巳，新事復起。姬姜勞苦，不得休息。",
"9-48":"憂患解除，喜至慶來。坐立懽忻，與樂為鄰。",
"9-49":"晨風之翰，大舉就溫。昧過我邑，羿無所得。",
"9-50":"下田稷黍，方華生齒。大雨集降，紛澇滿甕。",
"9-51":"君子碌碌，鳥庇茂木。見春百榖，心勞願德。",
"9-52":"折臂踒足，不能進酒。祠祀曠開，神怒不喜。",
"9-53":"學靈三年，聖且神明。光見喜祥，吉喜福慶。鳴鳩飛來，告我無憂。",
"9-54":"三婦同夫，忽不相思。心懷不平，志常愁悲。",
"9-55":"中田膏黍，以享王母。受福千億，所求大得。",
"9-56":"陽火不災，喜至慶來。降福送喜，鼓琴歌謳。",
"9-57":"陽明不甘，君無恩德。伯氏失利，農喪其力。",
"9-58":"鷰雀銜茅，以生孚乳。兄弟六人，姣好悌孝。各得其願，和悅相樂。",
"9-59":"鶉尾奔奔，火中成軍。賊叔出奔，下失其君。",
"9-60":"兩人相距，止不同舍。夫妻離散，衛侯失居。",
"9-61":"魁為畨虎，風推雲郤。欲上不得，反歸其宅。",
"9-62":"關雎淑女，配我君子。少妻在門，君子嘉喜。",
"9-63":"慈母赤子，饗賜得士。襄夷服除，以安王家。",
"9-64":"三足孤烏，靈鳴督郵。伺過討惡，自賊其家。",
"10-1":"東嚮藩垣，相與笑言。子般執鞭，圉人作患。",
"10-2":"循河摘舟，旁淮東游。漁父舉網，先得大鰍。",
"10-3":"轅折輪破，馬𠋣僕臥。後旅先宿，右足跌踒。",
"10-4":"兩人相絆，相與悖戾。心不同爭，訟忷忷然。",
"10-5":"北辰紫宮，衣冠立中。含和建德，常受天福。",
"10-6":"遊居石門，祿身安全。受福西鄰，歸飲玉泉。",
"10-7":"羊腸九縈，相推併前。止須王孫，乃能上天。",
"10-8":"爭訟相倍，和氣不處。陰陽俱否，榖風母子。",
"10-9":"郭叔距頤，為棘所拘。龍額重顙，禍不成殃，復歸其鄉。",
"10-10":"十烏俱飛，羿得九雌。雄雖得全，且驚不危。",
"10-11":"蠆室蜂戶，螫我手足。不得進止，為吾害咎。",
"10-12":"怒非其怨，因拘有遷。貪垢腐鼠，而呼鴞鳶。失反被困。",
"10-13":"嬰孩求乳，母歸其子。黃麑悅喜，自樂甘餌。",
"10-14":"針縷勝服，錦繡不成。鷹逐雉兔，爪折不得。",
"10-15":"雨潦集降，河梁不通。鄒魯閉塞，破費市空。",
"10-16":"封豕溝瀆，水潦空谷。客止舍宿，泥塗至腹。處無黍稷。",
"10-17":"三姦相擾，桀跖為交。上下騷離，隔絕天道。",
"10-18":"齊景惑疑，為孺子牛。嫡庶不明，賊孽為患。",
"10-19":"三羊俱亡，走奔南行。會暮失跡，不知所藏。",
"10-20":"請伯行賈，代山之野。夜歷險阻，不逢危殆，利如澆酒。",
"10-21":"葉之將落，隕其黃葉。失勢傾側，而無所立。",
"10-22":"上山求魚，入水捕狸。市非其歸，自令久留。",
"10-23":"名成德就，項領不試。景公耋老，尼父逝去。",
"10-24":"天之奧隅，堯舜所居。以存保身，為我國家。",
"10-25":"雎鳩淑女，賢聖配偶。宜家壽福，吉慶長久。",
"10-26":"兩人俱爭，莫能有定。心乖不同，訟言起凶。",
"10-27":"涉伯徇名，棄禮誅身。不得其道，成子奔燕。",
"10-28":"踰江求橘，并得大栗。烹羊食肉，飲酒歌笑。",
"10-29":"山險難升，澗中多石。車馳轊擊，重傷載軸。擔負善躓，跌踒右足。",
"10-30":"元利孔福，神所子畜。般樂無苦，得其歡欲。",
"10-31":"烏鵲食榖，張口受哺。蒙被恩福，長大成就。柔順利貞，君臣合好。",
"10-32":"潼滃蔚薈，膚寸來會。津液下降，流潦滂沛。",
"10-33":"路多枳棘，步刺我足。不利旅客，為心作毒。",
"10-34":"虺蝮所聚，難以居處。毒螫痛甚，瘡不可愈。",
"10-35":"麟鳳相隨，觀察安危。東郭聖人，后稷周公。共和政令，君子攸同。利以居止，長無憂凶。",
"10-36":"築亂不時，使民恨憂。立趾為笑，君危臣騷。",
"10-37":"黃帝所生，伏羲之宅。兵刃不至，利以居止。",
"10-38":"雀行求食，暮歸屋宿。及其室舍，安寧無故。",
"10-39":"大倉積榖，天下饒食。陰陽和調，年歲時熟。",
"10-40":"履機蹈顛，墮入寒淵。行不能前，足踒不便。",
"10-41":"竿旄旌旗，執幟在郊。雖有寶珠，無路致之。",
"10-42":"銜命上車，和合兩家。蛾眉皓齒，二國率殭。",
"10-43":"吉日車攻，田弋獲禽。宣王飲酒，以告嘉功。",
"10-44":"重伯黃寶，宜以我市。嫁娶有息，利得過毋。",
"10-45":"延頸望酒，不入我口。深以自喜，利得無有。",
"10-46":"牧為代守，饗食甘賜，得吏士意。戰大破胡，長安國家。",
"10-47":"日出溫谷，臨照萬國。高明淑仁，虞夏配德。",
"10-48":"逐兔索鳥，破我弓車。日暮不及，失利後時。",
"10-49":"譌言妄語，傳相詿誤。道左失跡，不知所處。",
"10-50":"履虎躡蛇，貶損我威。君子失車，去其國家。",
"10-51":"本根不固，花葉落去。更為孤嫗，不得相親。",
"10-52":"五軛四軏，優得饒有。陳力就列，騶虞喜悅。",
"10-53":"黃帝紫雲，聖且神明。光見福祥，告我無殃。",
"10-54":"五利四福，俱佃高邑。黍稷盛茂，多獲藳稻。",
"10-55":"群虎入邑，求索肉食。大人衛守，君不失國。",
"10-56":"烏子鵲雛，嘗與母居。顧慕群侶，不離其巢。",
"10-57":"蹇驢不材，駿驥失時。筋勞力盡，罷於沙丘。",
"10-58":"玄鬛黑顙，東歸高鄉。朱鳥道引，靈龜載荘。遂抵天門，見我貞君。",
"10-59":"探巢得雛，鳩鵲來俱，使我音娛。",
"10-60":"安上宜官，一日九遷。升擢超等，牧養常山，君臣獲安。",
"10-61":"大頭目明，戴受嘉福。三雀飛來，與祿相得。",
"10-62":"遠視千里，不見黑子。離婁之明，無益於光。",
"10-63":"三女為姦，俱遊高園。背夫夜行，與伯笑言。不忍主母，失禮酒冤，皇天誰告。",
"10-64":"日辰不和，強弱相振。一雌兩雄，客勝主人。",
"11-1":"伯夷叔齊，貞㢘之師。以德防患，憂禍不存。",
"11-2":"濟深難渡，濡我衣褲。五子善櫂，脫無他故。",
"11-3":"倚立相望，適得道通。驅駕奔馳，比目同床。",
"11-4":"葛藟蒙棘，花不得實。讒佞為政，使恩壅塞。",
"11-5":"四足無角，君子所服。南征述職，與福相得。",
"11-6":"踝踵之傷，左指病癰。失旅後時，利走不來。",
"11-7":"春城夏國，生長之域。可以服食，保全家國。",
"11-8":"望驥不來，駒蹇為憂。雨驚我心，風撼我肌。",
"11-9":"久客無床，思歸我鄉。雷雨涌盈，道不得通。",
"11-10":"舫船備水，旁可燃火。積善有徵，終身無禍。",
"11-11":"求玉陳國，留連東域。須我王孫，四日來復。主君有德，蒙恩受福。",
"11-12":"陟岵望母，役事未巳。王政無盬，不得相保。",
"11-13":"多載重負，捐棄於野。子母誰子，但自勞苦。",
"11-14":"生直地乳，上皇大喜。賜我福祉，受命無極。",
"11-15":"翕翕䡘䡘，稍墮崩顛。滅其今名，長沒不全。",
"11-16":"東鄰嫁女，為王妃后。莊公築館，以尊王母。歸于京師，季姜悅喜。",
"11-17":"伯虎仲熊，德義淵閎。使布五榖，陰陽順敘。",
"11-18":"敏捷敬疾，如猿升木。彤弓雖調，終不能獲。",
"11-19":"舉被覆目，不見日月。衣裘蕈床，就長夜室。",
"11-20":"忍醜少羞，無面有頭。虛日以弊，消寡耗減。",
"11-21":"涸陰冱寒，常冰不溫。凌人墮怠，雹大為菑。",
"11-22":"夏麥麩䵃，霜擊其芒。疾君敗國，使民夭傷。",
"11-23":"淵涸龍憂，箕子為奴。午叔殞命，殷破其家。",
"11-24":"跛踦相隨，日暮牛罷。陵遲後旅，失利亡雌。",
"11-25":"桑之將落，隕其黃葉。失勢傾側，如無所立。",
"11-26":"生長以時，長育根本。陰陽和德，歲樂無憂。",
"11-27":"童女無夫，未有匹配。陰陽不和，空坐獨宿。",
"11-28":"春令原宥，仁德不合。三聖攸同，周國茂興。",
"11-29":"金精耀怒，帶劍過午。兩虎相距，雖驚無咎。",
"11-30":"危坐至暮，請求不得。膏澤不降，政戾民忒。",
"11-31":"老楊日衰，條多枯枝。爵級不進，日下摧隤。",
"11-32":"蔡侯適楚，留連江濵。踰時歷月，思其君后。",
"11-33":"右撫劍頭，左受鉤帶。凶訟不止，相與爭戾，失利市肆。",
"11-34":"水流趨下，遠至東海。求我所有，買鮪與鯉。",
"11-35":"登几上輿，駕駟南遊。合從散衡，燕秦以強。",
"11-36":"求兔得獐，過其所望。懽以相迎，高位夷傷。",
"11-37":"過時不歸，道遠且迷。旅人心悲，使我徘徊。",
"11-38":"魂孤無室，銜指含食。盜張民饋，見敵失肉。",
"11-39":"居如轉丸，危不得安。東西不寧，動生憂患。",
"11-40":"坤厚地德，庶物蕃息。平康正直，以綏大福。",
"11-41":"挒蔽牡荊，生賢山旁。仇敵背憎，孰肯相迎。",
"11-42":"鳳凰銜書，賜我玄珪。封為晉侯。",
"11-43":"作凶不善，相牽入井。溺陷辜罪，禍至憂有。",
"11-44":"悲鳴北行，失其長兄。伯仲不幸，骸骨散亡。",
"11-45":"羔衣豹裘，高易我家，君子惟好。",
"11-46":"日中為市，各抱所有，交易資貨。貪珠懷寶，心悅懽喜。",
"11-47":"振急絕理，常陽不雨。物病焦乾，華實無有。",
"11-48":"狐貉載剝，徙溫厚蓐。寒棘為疾，有所不足。",
"11-49":"履踐危難，脫執去患。入福喜門，見誨大君。",
"11-50":"四亂不安，東西為患。退止我足，毋出國城。乃得全完，賴其生福。",
"11-51":"南國少子，才略美好。求我長女，賤薄不與。反得醜惡，後乃大悔。",
"11-52":"妄怒失理，陽孤無輔。物病焦枯，年飢於黍。",
"11-53":"倬然遠咎，避患害早。田獲三狐，見民為寶。",
"11-54":"逐鹿山顛，利去我西。維邪南北，無所不得。",
"11-55":"龍蛇所聚，大水來處。滑滑泲泲，使我無賴。",
"11-56":"從風吹火，牽騏驥尾。易為功力，因催受福。",
"11-57":"澤狗水鳧，難畜少雛。不為家饒，心其函憂。",
"11-58":"水壞我里，東流為海。龜鳧讙囂，不睹慈母。",
"11-59":"褰衣涉行，水深漬多。賴幸舟子，濟脫無他。",
"11-60":"龜厭河海，陸行不止。自令枯槁，失其都市。憂悔為咎，亦無及巳。",
"11-61":"同本異業，樂仁政德。東鄰慕義，來興我國。",
"11-62":"桃李花實，累累日息。長大成熟，甘美可食，為我利福。",
"11-63":"重瞳四乳，聰明順理。無隱不形，微視千里。災害不作，君子集聚。",
"11-64":"實沈參墟，以義討尤。次止結盟，以成霸功。",
"12-1":"天之奧府，眾利所聚。可以饒有，樂我君子。",
"12-2":"天之所菑，凶不可居。轉徙獲福，留止危憂。",
"12-3":"名成德就，項領不試。景公耋老，尼父逝去。",
"12-4":"特善避患，福祿長存。雖有犲虎，不能危患。",
"12-5":"避患東西，反入禍門。糟糠不屬，憂動我心。",
"12-6":"珪璧琮璋，執贄見王。百里寗越，應聘齊秦。",
"12-7":"揚水潛鑿，使君潔白。衣素朱表，遊戲皋沷。得君所願，心志娛樂。",
"12-8":"官爵相保，居之無咎。求兔不得，怕使恨悔。",
"12-9":"戴元無褌，臝裎出門。小兒作笑，君為憂患。",
"12-10":"把珠入口，為我利寶。得吾所有，欣然嘉喜。",
"12-11":"行不如還，直不如屈。進不若退，可以安吉。",
"12-12":"秦為虎狼，與晉爭強。併吞其國，號曰始皇。",
"12-13":"眾鬼凢聚，還生大怪，九身無頭。魂驚魄去，不可以居。",
"12-14":"家給人足，訟聲並作。四夷賓服，干戈囊閣。",
"12-15":"人面鬼口，長舌為斧。斫破瑚璉，殷商絕祀。",
"12-16":"南山之峻，真人所在。德配唐虞，天命為子。保祐飲享，身受大慶。",
"12-17":"春桃生花，季女宜家。受福多年，男為邦君。",
"12-18":"鴟鴞破斧，沖人危殆。賴其忠德，轉禍為福，傾危復立。",
"12-19":"猿墮高木，不踒手足。保我金玉，還歸其室。",
"12-20":"天之奧隅，堯舜所居。可以存身，保我邦家。",
"12-21":"伯蹇叔盲，足病難行。終日至暮，不離其鄉。",
"12-22":"日月相望，光明盛昌。三聖茂功，仁德大隆。",
"12-23":"桃李花實，累累日息。長大成就，甘美可食。",
"12-24":"入和出明，動作有光。運轉休息，動作尤康。",
"12-25":"陰冥老極，陽建其德。履離載光，天下昭明。功業不長，蝦蟆代王。",
"12-26":"行役未巳，新事復起。姬姜勞苦，不得休息。",
"12-27":"狐鳴室北，飢無所食。困於空丘，莫與同力。",
"12-28":"雄聖伏，名人匿。麟遠走，鳳飛北。櫌亂未息。",
"12-29":"病貧望幸，使伯行販。開牢擇羊，多得大牂。",
"12-30":"翕翕䡘䡘，稍稍崩顛。滅其令名，長沒不存。",
"12-31":"花落實槁，衣弊如絡。女功不成，絲布如玉。",
"12-32":"溫山松柏，常茂不落。鸑鳳所止，得以歡樂。",
"12-33":"失恃母友，嘉偶出走。玃如失兔，傫如虐狗。",
"12-34":"太一駕騮，從天上求。徵我叔季，封為魯侯。",
"12-35":"雙鳧俱飛，欲歸稻池。經涉雚澤，為矢所射，傷我胸臆。",
"12-36":"深坑復平，天下安寧。意娛心樂，賴福長生。",
"12-37":"俱為天民，雲過吾西。風伯雨師，與我無恩。",
"12-38":"野鳥山鵲，來集六博。三鳥四散，主人勝客。",
"12-39":"北陰司寒，堅冰不溫。凌人情怠，大雹為災。",
"12-40":"伊尹智士，去桀耕野。執順以傳，反和無咎。",
"12-41":"北風牽手，相從笑語。伯歌季舞，讌樂以喜。",
"12-42":"從巢去家，南過白馬。東西受福，與母相得。",
"12-43":"鳥飛跌跛，兩兩相和。不病四支，但去莫疑。",
"12-44":"三馬生駒，以戍為母。荊夷上侵，姬伯出走。",
"12-45":"破筐弊筥，棄捐於道。壞落穿敗，不復為寶。",
"12-46":"結紐得解，憂不為禍。食利供家，受福安坐。",
"12-47":"白日陽光，雷車避藏。雲雨不行，各自止鄉。",
"12-48":"杜口結舌，心中怫鬱。凶災生患，無所告冤。",
"12-49":"齎貝贖狸，不聽我辭。繫於虎髯，牽不得來。",
"12-50":"持鶴抱子，見蛇何咎。室家俱在，不失其所。",
"12-51":"逐兔山西，利走入門。賴我仁德，獲為我福。",
"12-52":"興役不休，與民爭時。牛生五趾，行危為憂。",
"12-53":"春粟夏梨，少鮮希有。斗千石萬，貴不可販。",
"12-54":"悲號北行，失其長兄。伯仲不幸，骸骨散亡。",
"12-55":"賦歛重數，政為民賊。杼軸空盡，家去其室。",
"12-56":"履服白縞，殃咎並到，憂不敢笑。",
"12-57":"杜口結舌，言為禍母。代伯受患，無所禱冤。",
"12-58":"免冠進賢，步行出朝。門體不正，賊孽為患。",
"12-59":"娶於姜女，駕迎新婦。少齊在門，夫子悅喜。",
"12-60":"牧羊稻園，聞虎喧嚾。思恐悚息，終無禍患。",
"12-61":"老妾据機，緯絕不知。女功不成，冬寒無衣。",
"12-62":"乘龍吐光，使陰復明。燎獵載聖，六師以昌。",
"12-63":"東鄰嫁女，為王妃后。莊公築館，以尊王母。歸于京師，季姜悅喜。",
"12-64":"灌鴶東從，道頓趺跱。日食不退，病為身禍。",
"13-1":"一臂六手，不便於口。莫肯與用，利棄我走。",
"13-2":"獐鹿逐牧，飽歸其居。安寧無悔。",
"13-3":"鴻魚逆流，至人潛渚。蒿蓬代柱，大屋顛倒。",
"13-4":"三羖五牂，相隨俱行。迷入空澤，經涉六駮，為所傷賊。",
"13-5":"黃帝出遊，駕龍乘馬。東上太山，南過齊魯，邦國咸喜。",
"13-6":"履危不安，心欲東西。步走逐鹿，空無所得。",
"13-7":"望尚阿衡，太宰周公。藩屏湯武，立為侯王。",
"13-8":"白龍黑虎，起伏俱怒。戰於阪兆，蚩尤走敗，死於魯首。",
"13-9":"載石上山，步跌不前。嚬眉之憂，不得所歡。",
"13-10":"周德既成，杼軸不傾。申酉趺暮，耋老衰去，箴石不祐。",
"13-11":"乘雲帶雨，與飛鳥俱。動舉千里，見我慈母。",
"13-12":"齎貝贖狸，不聽我辭。繫我虎鬚，牽不得來。",
"13-13":"宻槖山顛，銷鋒鑄刃。示不復用，天下大勸。",
"13-14":"三翼飛來，是我逢時。俱行先至，多得大利。",
"13-15":"兩足四翼，飛入家國。寧我伯子，與母相得。",
"13-16":"按民呼池，玉杯文案。魚如白雲，一國獲願。",
"13-17":"季姬踟躕，望我城隅。終日至暮，不見齊侯，君上無憂。",
"13-18":"龍渴求飲，黑雲影從。河伯奉觴，跪進酒漿，流潦滂滂。",
"13-19":"出門逢患，與福為怨。更相擊刺，傷我手端。",
"13-20":"播天舞，地神明。所守安，樂無咎。",
"13-21":"兩金相擊，勇氣鈞敵。終日大戰，不破不缺。",
"13-22":"車雖駕，兩紖絕。馬奔出，雙輪脫。行不至，道遇害。",
"13-23":"文山紫芝，雍梁朱草。長生和氣，玉以為寶。公尸侑食，福祿來處。",
"13-24":"把珠入口，為我畜寶。得吾所有，忻然嘉喜。",
"13-25":"負牛上山，力劣行難。烈風雨雪，遮遏我前。中道復還，憂者淂歡。",
"13-26":"陶朱白珪，善賈息資。三致千金，德施上人。",
"13-27":"子鉏執麟，春秋作元。陰聖將終，尼父悲心。",
"13-28":"春日載陽，福履齊長。四時不忒，與樂為倡。",
"13-29":"孔德如玉，出於幽谷。飛上喬木，鼓其羽翼，大光照國。",
"13-30":"區脫康居，慕仁入朝。湛露之歡，三爵畢恩。復歸窮廬，以安其居。",
"13-31":"秋冬夜行，照覧星辰。道理利通，終身何患。",
"13-32":"鳴鵠抱子，見蛇何咎。室家俱在，不失其所。",
"13-33":"安和太山，福祿屢臻。雖有犲虎，不能危身。",
"13-34":"老目瞢眠，不知東西。君失理命，以直為傴，王珎其寶。",
"13-35":"植璧秉珪，請命于河。周公剋敏，沖人瘳愈。",
"13-36":"太王執政，歲熟民富。國家豐有，主者有喜。",
"13-37":"爭訟相背，和氣不處。陰陽俱否，榖風無子。",
"13-38":"齊魯爭言，戰於龍門。構怨結禍，三世不安。",
"13-39":"鹿得美草，鳴呼其友。九族和穆，不離邦域。",
"13-40":"百里南行，雖徵復明。去虞適秦，為穆國卿。",
"13-41":"梅李冬實，國多寇賊。亂擾並作，王不能制。",
"13-42":"府藏之富，王以振貸。捕魚河海，苟罔多得。巨蛇大輶，戰於國郊，君遂走逃。",
"13-43":"杜飛門啟，患憂大解。去老乘馬，不為身禍。",
"13-44":"宜昌娶婦，東家歌舞，長樂歡喜。",
"13-45":"正陽之央，甲氏以亡。禍及留吁，湮滅為墟。",
"13-46":"鳥過稻廬，甘樂𪍿鰍。雖驅不去，田畯懷憂。",
"13-47":"跛踦俱行，日暮車傷，失旅乏糧。",
"13-48":"龍門水穴，流行不害。民安其土，君臣相保。",
"13-49":"山陵四塞，遏我徑路。欲前不得，復還故處。",
"13-50":"兩虎爭鬥，血流漂杵。城郭空墟，蒿藜塞道。",
"13-51":"依叔墻隅，志下心勞。楚亭晨食，韓子低頭。",
"13-52":"龍生無常，或託空葉。憑乘風雲，為堯立功。",
"13-53":"魁行搖尾，逐雲吹火。汙泥為陸，下田為稷。",
"13-54":"跛踦相隨，日暮牛罷。陵遲後旅，失利亡雌。",
"13-55":"三人俱行，北求大牂。長孟病足，請季負囊。柳下之寶，不失𮪜黃。",
"13-56":"鳳凰在左，麒麟處右。仁聖相遇，伊呂集聚。傷害不至，時無殃咎，福為我母。",
"13-57":"乘筏渡海，雖深不殆。曾孫皇祖，累累具在。",
"13-58":"比目四翼，來安吾國。齎福上堂，與我同床。",
"13-59":"娶於姜呂，駕迎新婦。少齊在門，夫子悅喜。",
"13-60":"螟蟲為賊，害我稼穡。盡禾單麥，秋無所得。",
"13-61":"衣裳顛倒，為王來呼。成就東周，邦國大休。",
"13-62":"王孫季子，相與為友。明允篤誠，升擢慶舉。",
"13-63":"踴泉滑滑，流行不絕。汙為江海，敗毀邑里。家無所處，聞虎不懼，向我笑喜。",
"13-64":"桑戶竊脂，啄粟不宜。亂政無常，使心孔明。",
"14-1":"南山大行，困於空桑。老沙為石，牛馬無糧。",
"14-2":"蟠枝失岐，與母別離。絕不相知。",
"14-3":"譐譐所言，莫知我恆。驩樂堅固，可以長安。",
"14-4":"李梅零墜，心思憒憒。懷憂少愧，亂我魂氣。",
"14-5":"火雖熾，在吾後。寇雖多，在吾右。身安吉，不危殆。",
"14-6":"虎臥山隅，鹿過後朐。弓矢設張，猬為功曹。伏不敢起，逐至平野，得我美草。",
"14-7":"三火起明，兩滅其光。高位疾巔，驕恣誅傷。",
"14-8":"匹君楚馬，遇讒無辜。久旅離憂。",
"14-9":"一室百子，同公異母。以義防患，禍菑不起。",
"14-10":"商人行旅，資所無有。貪貝利珠，留連王市。還旋內顧，公子何咎。",
"14-11":"禹將為君，北入崑崙。稍進揚光，登入溫湯。代舜為治，功德昭明。",
"14-12":"乾行天德，覆幬無極。嘔呼烹熟，使各自得。",
"14-13":"南國盛茂，黍稷醴酒。可以享老，樂以嘉友。",
"14-14":"白虎張牙，征伐東來。朱雀前驅，讃道說辭。敵人請服，銜璧前趨。",
"14-15":"方船備水，旁河然火。終身無禍。",
"14-16":"雷行相逐，無有休息。戰于平陸，為夷所覆。",
"14-17":"躑躅踟躕，拊心搔頭。五晝四夜，睹我齊侯。",
"14-18":"大口宣唇，神使伸言。黃龍景星，出應侯門。與福上堂，天下安昌。",
"14-19":"陰衰老極，陽建其德。離陽載光，天下昭明。",
"14-20":"三塗五嶽，陽城太室。神明所伏，獨無兵革。",
"14-21":"年豐歲熟，政仁民樂。利以居止，旅人獲福。",
"14-22":"楚烏逢天，不時久放。離居無群，意昧精喪。作此哀詩，以告孔憂。",
"14-23":"出門大步，與凶惡忤。罵公詈母，為我憂耻。",
"14-24":"火至井谷，陽芒生角。犯歷天戶，闚觀太微。登上玉床，家易六公。",
"14-25":"牧羊逢狼，雖憂不傷。畏怖既息，終無禍殃。",
"14-26":"繭栗犧牲，敬奉貴神。享者飲食，受福多孫。",
"14-27":"大盖治床，南歸羖羊。長伯為我，多得牛馬，利於徙居。",
"14-28":"枯樹無枝，與子分離。飢寒莫養，獨立哀悲。",
"14-29":"天地九重，堯舜履中。正冠垂裳，宇宙平康。",
"14-30":"鳧鷖遊淫，君子以寧。履德不愆，福祿來成。",
"14-31":"臝䄠逐狐，為人觀笑。牝雞雄晨，主作亂根。",
"14-32":"典筞法書，藏在蘭臺。雖遭亂潰，獨不遇菑。",
"14-33":"三痴俱狂，欲之平鄉。迷惑失道，不知昏明。",
"14-34":"癭瘤瘍疥，為身瘡害。疾病癃痢，常不屬逮。",
"14-35":"三豕俱走，鬥於虎口。白豕不勝，死于阪下。",
"14-36":"賴先之光，受德之佑。雖遭顛沛，獨不凶咎。",
"14-37":"上義崇德，以建大福。明哲且聰，周武立功。",
"14-38":"四亂不安，東西為患。身止無功，不出國城。乃得全完，賴其生福。",
"14-39":"金牙鐵齒，西王母子。無有患殆，減害道利。",
"14-40":"賀喜從福，曰利蕃息，懽樂有得。",
"14-41":"昊天白日，照臨我國。萬民康寧，咸賴嘉福。",
"14-42":"左眇右盲，視闇不明。下民多孽，君失其常。",
"14-43":"吾家黍𥹭，積委道傍。有囊服箱，運到我鄉，藏於嘉倉。",
"14-44":"殊類異路，心不相慕。牝猭無猳，螺無室家。",
"14-45":"雀行求食，出門見鷂。顛蹷上下，幾無所處。",
"14-46":"野有種庚，穡人駕取。不逢虎狼，暮歸其宇。",
"14-47":"膚敏之德，發憤忘食。虎豹禽說，為王求福。",
"14-48":"光祀春成，陳項雞鳴。陽明失道，不能自守。",
"14-49":"左抱金玉，右得熊足。常盈不忘，獲心所欲。",
"14-50":"履泥汙足，名困身辱。兩仇相得，身為痛瘧。",
"14-51":"安居重遷，不去其亶。未來相聞，樂得常產。",
"14-52":"天災所遊，凶不可居。轉徙獲福，留止危憂。",
"14-53":"昧昧墨墨，不知白黑。景雲亂擾，光明隱伏。犬戎來攻，幽主失國。",
"14-54":"鳧鴈啞啞，以水為宅。雌雄相和，心志娛樂，得其所欲。",
"14-55":"長生無極，子孫千億。柏柱載器，堅固不傾。",
"14-56":"麒麟鳳凰，善政得祥。陰陽和調，國無災殃。",
"14-57":"天之奧隅，堯舜所居。可以存身，保我室家。",
"14-58":"配合相迎，利之四鄰。昏以為期，與福笑喜。",
"14-59":"砥德礪材，果當成周。拜受大命，封為齊侯。",
"14-60":"與福俱坐，畜水備火。思患豫防，終無殃禍。",
"14-61":"畏昏潛處，候明昭昭。卒遭白日，為世榮主。",
"14-62":"視曰載光，與天相望。長生懽悅，以福為多。",
"14-63":"大頭明目，載受嘉福。三雀飛來，與祿相單。",
"14-64":"楩生荊山，命載輸班。袍衣剝脫，夏熱冬寒。立餓枯槁，眾人莫憐。",
"15-1":"喋囁處曜，昧冥相待。多言少實，終無成事。",
"15-2":"北辰紫宮，衣冠立中。含和建德，常受大福。鈆刀攻玉，堅不可得。",
"15-3":"東壁餘光，數闇不明。主母妒嫉，亂我事業。",
"15-4":"下背其上，盜明相譲。嬰子兩頭，陳破其虛。",
"15-5":"鳳生會稽，稍巨能飛。翱翔往來，為眾鳥雄。",
"15-6":"鑿井求玉，非卞氏室。名困身辱，勞無所得。",
"15-7":"邦桀載役，道至東萊。百僚具舉，君王嘉喜焉。",
"15-8":"安息康居，異國同廬。非吾邦域，使伯憂惑。安息康居，皆外國名。",
"15-9":"江河淮海，天之都市。商人受福，國家富有。",
"15-10":"同本異葉，樂仁上德。東鄰慕義，來興吾國。",
"15-11":"白鶴銜珠，夜食為明。懷吾德音，身受光榮。",
"15-12":"踐履危難，脫厄去患。入福喜門，見吾邦君。",
"15-13":"宮商既和，聲音相隨。𮪜駒在門，主君以歡。",
"15-14":"天地配享，六位光明。陰陽順序，以成厥功。",
"15-15":"王喬無病，苟頭不痛。亡破失履，乏我送從。",
"15-16":"江河淮海，天之奧府。眾利所聚，可以饒有，樂我君子。",
"15-17":"雙鳥俱飛，欲歸稻池。經涉雚澤，為矢所射，傷我胸臆。",
"15-18":"留仲叔季，日暮寢寐。羸臥失限，虐我具囊，銜卻道傍。",
"15-19":"受終文祖，承衰復起。以義自閑，雖苦無咎。",
"15-20":"据斗運樞，順天無憂，與樂並居。",
"15-21":"周師伐紂，戰於牧野。甲子平旦，天下悅喜。",
"15-22":"十雌伯雛，常與母俱。抱雞搏虎，誰敢害諸。",
"15-23":"桀跖並處，人民愁苦。擁兵荷糧，戰於齊魯。",
"15-24":"南山昊天，刺政閔身。疾悲無辜，背憎為仇。",
"15-25":"百川朝海，流行不止。道雖遼遠，無不到者。",
"15-26":"目不可合，憂來搖足。怵惕為懼，去我邦域。",
"15-27":"烏升鵲舉，照臨東海。厖降庭堅，為陶叔後。封於英六，履福為厚。",
"15-28":"北方多棗，橘柚所聚。荷囊載黍，盈我筐筥。",
"15-29":"懸狟素餐，食非其任。失望遠民，實勞我心。",
"15-30":"羔羊皮革，君子朝服。輔政扶德，以合萬國。",
"15-31":"齊魯爭言，戰於龍門。搆怨致禍，三世不安。",
"15-32":"久陰霖雨，塗行泥潦。商人休止，市無所有。",
"15-33":"桃雀，竊脂，巢於小枝。搖動不安，為風所吹，寒心慄慄，常憂殆危。",
"15-34":"防患備災，凶惡不來。雖困無憂，未獲安休。",
"15-35":"引順絕糧，與母異門。不見所懽，孰與共言。",
"15-36":"鰍蝦去海，藏於枯里。街巷𥚹隘，不得自在。南北極遠，渴餒成疾。",
"15-37":"㳟寬信敏，功加四海。辟去不祥，喜來從母。",
"15-38":"歲飢無年，虐政害民。乾谿驪山，秦楚結怨。",
"15-39":"右目無瞳，偏視寡明。十步之外，不知何公。",
"15-40":"蜩螗歡喜，草木嘉茂。百菓蕃熾，日益多有。",
"15-41":"當得自如，安坐無尤。華入貴鄉，到老安榮。",
"15-42":"狡兔躍躍，良犬逐咋。雄雉受害，為鷹所獲。",
"15-43":"春桃生華，季女宜家。受福多年，男為封君。",
"15-44":"山石朽弊，稍崩墮落。上下離心，君受其祟。",
"15-45":"水壞我里，東流為海。龜鳧讙囂，不睹我家。",
"15-46":"七竅龍身，造易八元。法天則地，順時施恩。富貴長存。",
"15-47":"四夷慕德，來興我國。文君陟降，同受福德。",
"15-48":"華首山頭，仙道所遊。利以居止，長無咎憂。",
"15-49":"鸇鳩徙巢，西至平州。遭逢雷雹，闢我葦廬。室家飢寒，思吾故初。",
"15-50":"狗無前足，陰謀叛背，為身害賊。",
"15-51":"陽孤亢極，多所恨惑。車傾蓋亡，身常驚惶。乃得其願，雌雄相從。",
"15-52":"空槽注豬，豚彘不到。張弓祝雞，雄父飛去。",
"15-53":"長夜短日，陰為陽賊。萬物空枯，藏於北陸。",
"15-54":"𤓰牙之士，怨毒祈父。轉憂與巳，傷不及母。",
"15-55":"拜跪請兔，不得臭腐。挽眉銜指，低頭北去。",
"15-56":"有莘季女，為夏妃后。貴夫壽子，母字四海。",
"15-57":"季姬踟躕，待孟城隅。終日至暮，不見齊侯。",
"15-58":"邯鄲反言，父兄生患。涉叔援俎，一死不還。",
"15-59":"逐鹿山顛，利去我西。維邪南北，利無不得。",
"15-60":"虎豹熊羆，遊戲山谷。君子仁賢，皆淂所欲。",
"15-61":"穿鼻繫株，為虎所拘。王母祝榴，禍不成災。突然自來。",
"15-62":"梅李冬實，國多賊盜。擾亂並作，王不能制。",
"15-63":"望幸不刋，文章未就。王子逐兔，犬踦不得。",
"15-64":"千柱百梁，終不傾僵。仁智輔聖，周宗寧康。",
"16-1":"龍馬上山，絕無水泉。喉燋唇乾，口不能言。",
"16-2":"蔡侯朝楚，留連江濵。踰時歷月，思其后君。",
"16-3":"文厄羑里，湯拘夏臺。仁聖不害，數困何憂。免於縲索，為世雄侯。",
"16-4":"典冊法書，藏在蘭臺。雖遭亂潰，獨不遇災。",
"16-5":"旃裘羶國，文禮不飭。跨馬控弦，伐我都邑。",
"16-6":"星隕如雨，弓弱無輔。強陽制陰，不得安土。",
"16-7":"蝗齧我稻，驅不可去。實穗無有，但見空藁。",
"16-8":"虎飢欲食，為蝟而伏。禹導龍門，辟咎除患，元醜以安。",
"16-9":"蝙蝠夜藏，不敢晝行。酒為酸漿，魴臭飽羮。",
"16-10":"精華墮落，形體醜惡。齬齟挫頓，枯槁腐蠹。",
"16-11":"兩足不獲，難以遠行。疾步不能，後旅失時。",
"16-12":"令妻壽母，宜家無咎。君子之歡，得以長久。",
"16-13":"蚕飢作室，昏多亂纒，緒不可得。",
"16-14":"子鋤執麟，春秋作元陰。聖將終，尼父悲心。",
"16-15":"螟蟲為賊，害我稼穡。禾單麥盡，秋無所得。",
"16-16":"冰將泮散，鳴鴈噰噰。丁男長女，可以會同，生育聖人。",
"16-17":"憂在腹內，山崩為疾。禍起蕭墻，竟制其國。",
"16-18":"茹芝餌黃，飲食玉瑛。與神流通，長無憂凶。",
"16-19":"一夫兩心，䃽刺不深。所為無功，求事不成。䃽章移切。",
"16-20":"十里望烟，散渙四分。形容滅亡，終不見君。",
"16-21":"張弓廓弩，經涉山道。雖有伏虎，誰敢害諸。",
"16-22":"泉閉澤竭，王母飢渴。君子困窮，乃徐有說。",
"16-23":"野鳶山鵲，奕棊六博。三梟四散，主人勝客。",
"16-24":"羊驚馬走，上下揮擾。鼓音不絕，頃公奔敗。",
"16-25":"黃帝神明，八子聖聰。俱受大福，天下康平。",
"16-26":"住車醊酒，疾風暴起。泛亂福器，飛揚鼓舞。明神降佑，道無害災。",
"16-27":"滕蛇乘龍，宋鄭飢凶，民食草蓬。",
"16-28":"揚水潛鑿，使石潔白。裡素表朱，遨遊皋澤。得君所願，心志娛樂。",
"16-29":"西過虎廬，驚其前樞。雖憂無尤。",
"16-30":"衣成無䄂，不知所穿。客指東西，未得便安。",
"16-31":"晨風文翰，隨時就溫。雄雌相和，不憂危殆。",
"16-32":"心多恨悔，出言為怪。梟鳴于北，聲醜可惡，請謁不得。",
"16-33":"離女去夫，閔思苦憂。齊子無良，使我心愁。",
"16-34":"過時不歸，雌雄苦悲。徘徊外國，與叔分離。",
"16-35":"鵲巢柳樹，鳩集其處。任力薄德，天命不祐。",
"16-36":"鶴盜我珠，逃於東都。懷怒追求，郭氏之墟。不見蹤跡，使伯心憂。",
"16-37":"夫婦相背，和氣弗處。陰陽俱否，莊姜無子。",
"16-38":"日走月步，逃不同舍。夫妻反目，主君失位。",
"16-39":"雒陽嫁女，善逐人走。三寡失夫，婦妒無子。",
"16-40":"周德既成，抒軸不傾。太宰東西，夏國康寧。",
"16-41":"日中為市，交易資寶。各利所有，心悅以喜。",
"16-42":"童妾獨宿，長女未室，利無所得。",
"16-43":"忠言輔成，王政不傾。公劉兆基，文武綏之。",
"16-44":"牛驥同堂，郭氏以亡。國破為虛，主君奔逃。",
"16-45":"中原有菽，以待雉食。飲御諸友，所求大得。",
"16-46":"多虛少實，語不可覆。樽虛無酒，飛言如雨。",
"16-47":"青蠅集蕃，君子信讒。害賢傷忠，患生婦人。",
"16-48":"履株覆輿，馬驚傷車。步為我憂。",
"16-49":"商風召寇，呼我北盜。間諜內應，與我爭鬥。殫已寶藏，主人不勝。",
"16-50":"逸豫好遊，不安其家。惑於少姬，久迷不來。",
"16-51":"吾有驊騮，畜之以時。東家翁孺，來請我駒。價極可與，後無賤悔。",
"16-52":"阨窮上通，與堯相逢。登升大麓，國無凶人。",
"16-53":"眾兔俱走，熊羆在後。踦不能進，失信寡處。",
"16-54":"旁行不遠，三思復反。心多畏惡，中日止舍。",
"16-55":"倉唐奉使，中山以孝。文侯悅喜，擊子徵召。",
"16-56":"入天門，守地戶。居安樂，不勞苦。",
"16-57":"登堦上堂，見吾父兄。左酒右漿，與福相迎。",
"16-58":"秋蛇向穴，不失其節。夫人姜氏，自齊復入。",
"16-59":"忍醜少羞，無面有頭。滅耗寡虛，日以削銷。",
"16-60":"景星炤堂，麟鳳遊翔。仁施大行，頌聲以興。",
"16-61":"竿旄旌旗，執幟在郊。雖有寶珠，無路致之。",
"16-62":"李華再實，鴻卵降集。仁德以興，陰國受福。",
"16-63":"白馬赤烏，戰於東都。天輔有德，敗悔為憂。",
"16-64":"採薪得麟，大命隕顛。豪雄爭名，天下四分。",
"17-1":"鼻目易處，不知香臭。君迷於事，失於共居。",
"17-2":"唐虞相輔，鳥獸喜舞。安樂無事，國家富有。",
"17-3":"左輔右弼，金玉滿櫃。常盈不亡，富如敖倉。",
"17-4":"蒼龍單獨，與石相觸，摧折兩角。",
"17-5":"釣目厭部，善逐人走。來嫁無夫，不安其廬。",
"17-6":"逐虎驅狼，避者不祥。凶惡北行，與喜相逢。",
"17-7":"齎貝贖狸，不聽我辭。繫於虎鬚，牽不得來。",
"17-8":"岡載共輿，中道別去。喪我元夫，獨與孤居。",
"17-9":"奮翅鼓翼，將之嘉國。愆期失時，反得所欲。",
"17-10":"目傾心惑，夏姬在側。申公顛倒，巫臣亂國。",
"17-11":"摶鳩彈鵲，逐兔山北。丸盡日暮，失獲無得。",
"17-12":"鹿求其子，虎廬之里。唐伯季耳，貪不我許。",
"17-13":"敗魚鮑室，臭不可息。上山履塗，歸傷我足。",
"17-14":"華燈百枝，消衰暗微。精光訖盡，奄有灰靡。",
"17-15":"顏叔子夏，遨遊仁宇。溫良受福，不失其所。",
"17-16":"梁柱堅固，子孫蕃盛。福喜盈積，終無禍悔。",
"17-17":"烏鳴東西，迎其群侶。不得自專，空返獨還。",
"17-18":"邊鄙不聳，民狎其野。穡人成功，年歲大有。",
"17-19":"蛇牛鳴呴，呼求水潦。雲雨大會，流成河海。",
"17-20":"志合意同，姬姜相從。嘉耦在門，夫子悅喜。",
"17-21":"白馬駮騮，更生不休。富有商人，利得如丘。",
"17-22":"大姒夏禹，經啟九道。各有攸家，民得安所。",
"17-23":"甲戊巳庚，隨時轉行。不失其心，得且安寧。",
"17-24":"穆違百里，使孟厲武。將師襲戰，敗於殽口。",
"17-25":"茅茹本居，與類相扶。顧慕群旅，不離其巢。",
"17-26":"伯仲叔季，日暮𥨊𥧌。坐臥失明，喪其貝囊。",
"17-27":"亡羊𥙷牢，張氏失牛。騂駟奔走，鵠盜我魚。",
"17-28":"雀目燕顙，畏昏無光。思我狡童，不見子充。",
"17-29":"入暗出明，動作有光。運轉休息，常樂允康。",
"17-30":"不勝𥝠情，以利自嬰。北室出孤，毀其良家。",
"17-31":"稱幸上靈，媚悅於神。受福重重，子孫蕃功。",
"17-32":"齊姜叔子，天文在位。實沈參墟，封為康侯。",
"17-33":"遨遊無患，出入安全。長受其歡，君子萬年。",
"17-34":"被服文德，升入大麓。四門雍肅，登受大福。",
"17-35":"負金懷玉，南歸嘉國。蜂蠆不螫，利入我室。",
"17-36":"日在阜顛，鄉昧為昏。小人成群，君子傷倫。",
"17-37":"水父海母，先來鳴呴。澤皋之土，從高而處。",
"17-38":"東鄰少女，為王長婦。柔順利貞，宜夫壽子。",
"17-39":"戴缶望天，不見星辰。顧小失大，福逃於外。",
"17-40":"王喬不病，狗頭不痛。三尸失履，乏我逆從。",
"17-41":"使鷰築室，身無庇宿。家不容車，微我衣服。",
"17-42":"威權分離，鳥夜徘徊。爭蔽月光，大人誅傷。",
"17-43":"辯變白黑，巧言亂國。大人失福，君子迷惑。",
"17-44":"依踞甲鎧，敝筐受貝。大人不顧，少婦不取，棄捐於道。",
"17-45":"鷰雀銜𦭘，以生孚乳。兄弟六人，妓好悌孝，得心懽忻，和悅相樂。",
"17-46":"登几上輿，駕駟南遊。合從散衡，燕秦以僵。",
"17-47":"黷黷許許，仇偶相得。冰入炭室，消亡不息。",
"17-48":"鴟鴞破斧，邦人危殆。賴其忠德，轉禍為福，傾亡復立。",
"17-49":"載金販狗，利棄我走。藏匿淵渠，悔折為咎。",
"17-50":"泉坑復平，宇室安寧。憂患解除，賴福長生。",
"17-51":"驪姬讒嬉，與二孽謀。譛啄恭子，賊害忠孝。駕出嘉門，商伯有喜。",
"17-52":"刺羊不當，血少無羮。女執空筐，不得採桑。",
"17-53":"牧羊稻園，聞虎喧嚾。畏懼悚息，終無禍患。",
"17-54":"明德隱伏，麟鳳遠匿。周室傾側，不知所息。",
"17-55":"鄰不我顧，而求玉女。身多禿癩，誰肯媚者。",
"17-56":"初雖無輿，後得戰車。賴幸逢福，不罹兵革。",
"17-57":"水壞我里，東流為海。龜鳧讙囂，不睹王母。",
"17-58":"兩心不同，或欲西東。明論終始，莫適所從。",
"17-59":"天帝懸車，廢禮不朝。禳福不制，失其寵家。",
"17-60":"交川合浦，遠濕難處。水土不同，思吾皇祖。",
"17-61":"句踐之危，棲於會稽。太宰機言，越國復存。",
"17-62":"慈烏鳴鳩，執一無尤。寢門內治，君子悅喜。",
"17-63":"當年早寡，獨立孤居。雞鳴犬吠，無敢問諸。我生不遇，獨離寒苦。",
"17-64":"江河變服，淫湎無側。高位顛崩，寵祿反覆。",
"18-1":"首澤與目，載受福慶。我有好爵，與汝相迎。",
"18-2":"䡘䡘轠轠，歲莫偏蔽。寵名捐棄，君衰在位。",
"18-3":"折若蔽日，蘭屏王目。司馬無良，平子沒傷。",
"18-4":"家在海隅，撓繞深流。王孫單行，無妄以趨。",
"18-5":"執義秉德，不危不殆。延頸盤桓，安其室檀。屯耗未得，終無大恤。",
"18-6":"長舌亂家，大斧破車。陰陽不得，偃姜衰憂。",
"18-7":"二人異路，東趨西步。千里之外，不相知處。",
"18-8":"視闇不見，雲蔽日光。不見子都，鄭人心傷。",
"18-9":"初憂後喜，與福為市。八佾列陳，飲御嘉友。",
"18-10":"童妾獨宿，長女未室。利無所得。",
"18-11":"玄黃四塞，陰雌伏謀。呼我墻屋，為巫所識。",
"18-12":"中復摧頹，常恐衰微。老復賴慶，五羖為相。",
"18-13":"伯氏殺羊，行悖天時。毫社夷燒，朝歌丘墟。",
"18-14":"日短夜長，祿命分張。早離父兄，免見憂傷。",
"18-15":"采唐沬鄉，期於桑中。失期不會，憂思約帶。",
"18-16":"昧視無光，夜不見明。冥抵空床，季葉逃亡。",
"18-17":"舉趾振翼，南至嘉國。見我伯姊，與惠相得。",
"18-18":"魴生江淮，一轉為百。周流天下，無有難惡。",
"18-19":"則天順時，周流其𭏟。與樂並居，無有咎憂。",
"18-20":"蠆室蜂戶，螫我手足。不可進取，為吾害咎。",
"18-21":"公孫駕驪，載遊東齊。延陵悅產，遺季紵衣。",
"18-22":"轉作驪山，大失人心。劉季發怒，禽滅子嬰。",
"18-23":"羊腸九縈，相推稍前。止須王孫，乃能上天。",
"18-24":"螮蝀充側，佞人傾惑。女謁橫行，正道壅塞。",
"18-25":"福祿不遂，家多怪祟。麋鹿悲啼，思其大雄。",
"18-26":"雲雷因積，大雨重疊。久不見日，使心悒悒。",
"18-27":"三河俱合，水怒踴躍。壞我王室，民困無食。",
"18-28":"旦雨夜行，早遍辟城。更相覆傾，終無所成。",
"18-29":"褒后生蛇，垂老盲微。倒跌哀公，酉滅黃離。",
"18-30":"鴻鴈南飛，隨時休息。轉逐天和，千歲不衰。",
"18-31":"後時失利，不得所欲。莫亨偕結，自逐自逐。",
"18-32":"心多恨悔，出言為怪。梟鳴室北，醜聲可惡。請謁不得。",
"18-33":"駟馬過隙，時難𠕂得。尼父孔聖，繫而不食。",
"18-34":"陰變為陽，女化為男。治道得通，君臣相承。",
"18-35":"崑崙源口，流行不止。龍門砥柱，民不安處。母歸孩子，黃麑悅喜。",
"18-36":"葛藟蒙棘，華不得實。讒佞亂政，使恩壅塞。",
"18-37":"公無長驅，大王駿馬。非其當所，傷折為害。",
"18-38":"大倉充盈，庶民蕃盛。年歲熟榮。",
"18-39":"執蕡炤犧，為風所吹。火滅無光，不見玄黃。",
"18-40":"鳥反故巢，歸其室家。心平意正，與叔相和。登高隕墜，失其寵貴。",
"18-41":"弩㢮弓藏。良犬不行。內無怨女，征夫在堂。",
"18-42":"特犧孔博，日新其德。文公燎獵，姜氏受福。",
"18-43":"季秋孟冬，寒露霜降。大陰在庭，品物不生。雞矢夜鳴，家擾數驚。",
"18-44":"心多恨悔，出門見怪。有蛇三足，醜聲可惡。嫫母為媒，請求不得。",
"18-45":"虎豹爭強，道閉不通。小人讙訟，貪夫受空。",
"18-46":"雞方啄粟，為狐所逐。走不得食，惶懼愓息。",
"18-47":"陳媯敬仲，兆興齊姜。乃適營丘，八世大昌。",
"18-48":"昊天白日，照臨我國。萬民康寧，咸賴嘉福。",
"18-49":"雲夢大藪，嘉有所在。虞人共職，驪駒樂喜。",
"18-50":"獐鹿雉兔，群聚東國。俱往逐追，九齚十得。主君有喜。",
"18-51":"德惠孔明，雖衰復章，保其室堂。",
"18-52":"天之所壞，不可強支。眾口嘈嘈，雖貴必危。",
"18-53":"天之奧隅，堯舜所居。可以全身，保我邦家。",
"18-54":"下泉苞恨，十年無王。荀伯遇時，憂念周京。",
"18-55":"江河海隅，眾利聚居。可以遨遊，卒歲無憂。",
"18-56":"南山黃竹，三身六目。出入制命，東皇宣政。主尊君安，鄭國無患。",
"18-57":"重驛置之，來除我憂。與喜俱居，同其福休。",
"18-58":"南山高岡，麟鳳室堂。含和履中，國無災殃。",
"18-59":"紫芝朱草，與仙為侶。公尸侑食，福祿來下。",
"18-60":"宮成室就，進樂相舞。英俊在堂，福祿光明。",
"18-61":"商人子孫，資無所有。貪狼逐狐，留連都市。還轅內鄉，嘉喜何咎。",
"18-62":"執贄入朝，獻其狐裘。元戎變安，沙漠以懽。",
"18-63":"湧泉滑滑，南流不絕。壞敗邑里，家無所處。",
"18-64":"固陰冱寒，常冰不溫。凌人情怠，大雹為災。",
"19-1":"黃獹生馬，白戌為母。晉師在郊，虞公出走。",
"19-2":"倉唐奉使，中山以孝。文侯悅喜，擊子徵召。",
"19-3":"機關不便，不能出言。精誠不通，為人所冤。",
"19-4":"白茅醴酒，靈巫拜禱，神嗜飲食，使君壽考。",
"19-5":"重瞳四乳，耳聰目明。普為仁表，聖作元輔。",
"19-6":"水長無船，破城壞堤。大夫從役，困于泥塗。一朝喪殞，不見少妻。",
"19-7":"二人俱行，各遺其囊。鴻鵠失珠，無以為明。",
"19-8":"隨時轉行，不失其常。咸樂厥類，身無咎殃。",
"19-9":"蔡女蕩舟，為國患憂。襃后在側，屏蔽王目，搔擾六國。",
"19-10":"駕龍騎虎，周遍天下。為人所使，西見王母。不憂不殆。",
"19-11":"員怨之吳，畫冊闔廬。鞭平服荊，除大咎殃。威震敵國，還受上卿。",
"19-12":"唐邑之墟，晉人之居。虞叔受福，實沈是國，世載其樂。",
"19-13":"管鮑相知，至德不離。三言相桓，齊國以安。",
"19-14":"三十無室，長女獨宿。心勞未得，憂在𮌎臆。",
"19-15":"散渙水長，風吹我鄉，火滅無光，墮敗桓公。",
"19-16":"飛蜎蠕動，各有配偶。小大相保，咸得其所。",
"19-17":"安樂几筵，未出王門。",
"19-18":"火生月窟，上下恩塞，觝亂我國。",
"19-19":"弱水之上，有西王母。生不知老，與天相保。行者危殆，利居善喜。",
"19-20":"長生無極，子孫千億。柏柱載青，堅固不傾。",
"19-21":"欽敬昊天，曆象星辰。宣授民時，陰陽和調。",
"19-22":"三河俱合，水怒踴躍。壞我王屋，民困於食。",
"19-23":"壽如松喬，與日月俱。常安康樂，不見禍憂。",
"19-24":"天之所予，福祿常在，不憂危殆。",
"19-25":"受䜟六符，招搖空虛。雖跌無憂，保我全財。",
"19-26":"齎金買車，失道後時。勞罷為憂，我心則休。",
"19-27":"華首山頭，仙道所遊，利以居止，長無憂咎。",
"19-28":"采唐沬鄉，要期桑中。失信不會，憂思約帶。",
"19-29":"八面九口，長舌為斧。斫破瑚璉，殷商絕後。武王伐紂，遂滅殷焉。",
"19-30":"臨溪蟠枝，雖恐不危，樂以笑歌。",
"19-31":"泱泱沸溢，水泉為害，使我無賴。",
"19-32":"蝗螟為賊，傷害稼穡。愁饑於年，農夫鮮食。",
"19-33":"八百諸侯，不期同時。慕西文德，興我宗族。家門雍雍。",
"19-34":"長男少女，相向笑語。來歡致福，和悅樂喜。",
"19-35":"平國不君，夏氏作亂。烏號竊發，靈公殞命。",
"19-36":"春多膏澤，夏潤優渥。稼穡熟成，畝獲百斛。",
"19-37":"客宿臥寒，席蓐不安。行危為害，留止得歡。",
"19-38":"乘桴於海，雖懼不殆。母載其子，終焉何咎。",
"19-39":"手拙不便，不能伐檀。車無軸轅，行者苦難。",
"19-40":"唐虞相輔，鳥獸喜舞。民安無事，國家富有。",
"19-41":"秋蛇向穴，不失其節。夫人姜氏，自齊復入。",
"19-42":"病篤難醫，和不能治。命終斯訖，下即蒿蘆。",
"19-43":"青蛉如雲，城邑閉門。國君衛守，民困於患。",
"19-44":"牙孽生齒，室堂啟戶。幽人利貞，鼓翼起舞。",
"19-45":"鳧遊江海，沒行千里。以為死亡，復見空桑。長生樂鄉。",
"19-46":"黃帝出遊，駕龍乘馬。東上太山，南遊齊魯。邦國咸喜。",
"19-47":"履危不止，與鬼相視。驚恐失氣，如騎虎尾。",
"19-48":"秋南春北，不失消息。涉和履中，時無隱慝。",
"19-49":"龍門砥柱，通利水道。百川順流，民安其居。",
"19-50":"千歲廟堂，棟撓傾僵。天厭周德，失其寵光。",
"19-51":"折若蔽目，不見稚叔。三足孤烏，遠離室家。",
"19-52":"望叔山北，陵隔我目。不見所得，使我憂惑。",
"19-53":"匏瓠之恩，一畝千室。萬國都邑，北門有福。",
"19-54":"域域牧牧，憂禍相半。隔以巖山，室家分散。",
"19-55":"騏驎騄耳，遊食萍草。逍遙石門，循山上下，不失其所。",
"19-56":"天所祚昌，文以為良。篤生武王，姬受其福。",
"19-57":"羊腸九縈，相推稍前。止須王孫，乃能上天。",
"19-58":"貧鬼守門，日破我盆。孤牝不駒，雞不成鶵。",
"19-59":"飽食從容，出門上堂。不失其常，家無凶殃。",
"19-60":"陰淫不止，白馬為洶，皋澤之子，就高而處。",
"19-61":"執戈俱立，以備暴急。千人守門，因以益卑。終安何畏。",
"19-62":"夾河為婚，水長無船，遙心失望，不見歡君。",
"19-63":"陰陽變化，各得其宜，上下順通，奏為膚功。",
"19-64":"任劣德薄，失其臣妾，田不見禽，犬無所齚。",
"20-1":"蜎飛蠕動，各有所配。歡悅相逢，咸得其處。",
"20-2":"繼祀宗邑，追明成康。光照萬國，享世久長。疾病不醫，下即蒿蘆。",
"20-3":"秋冬探巢，不得鵲雛。銜指北去，媿我少姬。",
"20-4":"童妾獨宿，長女未室，利無所得。",
"20-5":"鴻波逆流，主人潛去。蒿蓬代柱，大屋顛仆。",
"20-6":"目闇不明，讒夫在堂。左辟疾瘁，君失其光。",
"20-7":"王孫季子，相與孝友。明允篤誠，昇擢薦舉，為國幹輔。",
"20-8":"麟趾龍身，曰取三千。南上蒼梧，與福為昏。道里夷易，安全無患。",
"20-9":"三子成駒，破其堅車。輪載空輿，後時失期。",
"20-10":"逐禍除患，道德神仙。遏惡萬里，常歡以安。",
"20-11":"黃池之盟，吳晉爭強。勾踐為患，夷國不安。",
"20-12":"青牛白咽，呼我俱田。歷山之下，可以多耕。歲露時節，人民安寧。",
"20-13":"有頭無目，不見菽粟。消耗為疾，三年不復。",
"20-14":"山沒丘浮，陸為水魚。燕雀無巢，民無室廬。",
"20-15":"高岡鳳凰，朝陽梧桐。噰噰喈喈，菶菶萋萋。陳辭不多，以告孔嘉。",
"20-16":"鰥寡獨宿，憂動胸臆。莫與宿食。",
"20-17":"馬躓破車，惡婦破家。青蠅汙白，共子離居。",
"20-18":"長女三嫁，進退不羞。逐狐作妖，行者離憂。",
"20-19":"人無定，法緩除。才出地，雄走歸。陽不制陰，男失其家。",
"20-20":"歷山之下，虞舜所處。躬耕致孝，名聞四海。為堯所薦，纉位天子。",
"20-21":"茹芝餌黃，飲食玉英。與神流通，長無憂凶。",
"20-22":"東行無門，西出華山。道塞畏難，遊子為患。華山為西，嶽見爾雅。",
"20-23":"壽如松喬，與日月俱。常安康樂，不罹禍憂。",
"20-24":"探鷇得螽，所願不喜。道宜小人，君子咎蹇。",
"20-25":"蝸螺生子，深目黑醜。雖飾相就，眾人莫取。",
"20-26":"喜怒不時，雪霜為災。稼穡無功，后稷飢憂。",
"20-27":"烏升鵲舉，炤流東海。厖降庭堅，為陶叔後。封圻蓼六，履祿綏𢈲。",
"20-28":"黃離白日，招我四國。元首昭明，民賴其福。",
"20-29":"黍稷醇釀，敬奉山宗。神嗜飲食，甘雨嘉降。獨蒙福力，時災不至。",
"20-30":"福過我里，入門笑喜，與吾利市。",
"20-31":"晝臥里門，悚惕不安。目不得閡，鬼搔我足。",
"20-32":"春草榮華，長女宜夫。受福多年，世有封祿。",
"20-33":"雍門內崩，賊賢傷人。暴亂狂悖，簡公失位。",
"20-34":"心志無良，昌披妄行。觸抵墻壁，不見戶房。",
"20-35":"膠車木馬，不利遠賈。出門為患，安止得全。",
"20-36":"家在海隅，橈短流深。企立望宋，無木以趨。",
"20-37":"冬葉枯槁，當風於道。蒙被塵埃，左右勞苦。",
"20-38":"過時不行，妄逐王公。老女失度，不安其居。",
"20-39":"履泥汙足，名困身辱。兩仇相當，身為疾病。",
"20-40":"精華墮落，形體醜惡。齬齟挫頓，枯槁腐蠹。",
"20-41":"長生無極，子孫千億。柏柱載青，堅固不傾。",
"20-42":"去辛就蓼，毒愈酷毒。不思我家，避阱入坑。憂患日生。",
"20-43":"行堯欽德，養賢致福。眾英積聚，國無寇賊。",
"20-44":"狗逐兔走，俱入谷口。與虎逢晤，迫不得去。",
"20-45":"望尚阿衡，太宰周公。蕃屏湯武，立為侯王。",
"20-46":"清人高子，久屯野外。逍遙不歸，思我慈母。",
"20-47":"三䖝作蠱，削跡無與。勝母盜泉，君不安處。",
"20-48":"驢牝龍身，進所無前。三日五夜，得其所欽。",
"20-49":"黃裡綠衣，君服不宜。淫湎毀常，失其寵光。",
"20-50":"天所顧祐，禍災不至，安吉不懼。",
"20-51":"盤紆九逥，行道留難。止須子丘，乃睹所歡。",
"20-52":"暴虐失國，為下所逐。北奔陰月，王居旄頭。",
"20-53":"御騂從龍，至于華東。與離相逢，送致于邦。",
"20-54":"銅人鐵距，雨露勞苦。終日卒歲，無有休息。",
"20-55":"大人失宜，盈滿復𧇊。長冬之禾，盛者滅衰。",
"20-56":"梅李冬實，國多盜賊。亂擾並作，王不能制。",
"20-57":"澤枯無魚，山童無株。長女嫉妒，使身空虛。",
"20-58":"天門東虛，既盡為菑。膉𦝢黯蒼，秦伯受殃。",
"20-59":"褰衣涉河，水深漬衣。賴幸舟子，濟脫無他。",
"20-60":"推車上山，高仰重難。終日至暮，唯見阜顛。",
"20-61":"鼎易其耳，熱不可舉。大路壅塞，旅人心苦。",
"20-62":"四亂不安，東西為患。退身止足，無出邦域。乃得完全，賴其生福。",
"20-63":"班馬還師，以息勞罷。役夫嘉喜，入戶見妻。",
"20-64":"積德不怠，遇主逢時。載喜渭陽，身受榮光。",
"21-1":"北風相牽，提笑語言。伯歌叔舞，讌樂以喜。",
"21-2":"甲戊已庚，隨時轉行。不失常節，達性任情，各樂其類。",
"21-3":"破亡之虛，神祇哀憂。進往無光，留止有慶。",
"21-4":"注斯膏澤，扞衛百毒。防以江南，虺不能螫。",
"21-5":"日月相望，光輝盛昌。三聖茂功，仁德大隆。",
"21-6":"大蛇巨魚，戰於國郊。上下隔塞，衛侯廬曹。",
"21-7":"龍入天關，經歷九山。登高上下，道里險難。日晏不食，絕無甘酸。",
"21-8":"沙漠北塞，絕無水泉。君子征凶，役夫苦艱。",
"21-9":"關折門啟，衿帶解墮。福與善坐，憂不為禍。",
"21-10":"狼虎所嘷，患害必遭。不利有為，宜以遁逃。",
"21-11":"金精耀怒，帶劍過午。兩虎相距，弓弩滿野，雖憂無苦。",
"21-12":"朽根枯樹，葉落花去。卒逢火焱，相隨偃仆。",
"21-13":"入和出明，動作有光。轉運休息，常樂永康。",
"21-14":"國多忌諱，大人恆畏。結口無患，可以長存。",
"21-15":"天地淳厚，六合光明。陰陽順序，以成厥功。",
"21-16":"臝裎逐狐，為人觀笑。牝雞雄晨，主作亂妖。",
"21-17":"陰升陽伏，桀失其室。相餧不食，桀夏桀無。道成湯放，之于南巢。",
"21-18":"蜎飛蠢動，各有配偶。小大相保，咸得其所。",
"21-19":"鬼守我廬，欲呼伯去。曾孫壽考，司命不許。與生相保。",
"21-20":"禍走患伏，喜為我福。凶惡消亡，菑害不作。",
"21-21":"麒麟鳳凰，善政德祥。陰陽和調，國無災殃。",
"21-22":"智不別揚，張狂妄行。蹈淵仆顛，傷殺伯身。",
"21-23":"凶憂災殃，日益章明。禍不可休，三郤夷傷。",
"21-24":"長尾蜲蛇，畫地為河。深不可涉，阻絕以無，惆然憤息。",
"21-25":"愛我嬰女，牽引不與，冀幸高貴，反得賤下。",
"21-26":"鳧遊江海，甘樂其餌。既不近人，雖驚不駭。",
"21-27":"明滅光息，不能復食。精魄既喪，以夜為室。",
"21-28":"奇適無耦，習靖獨處。所願不從，心思勞苦。",
"21-29":"葛藟蒙棘，華不得實。讒佞亂政，使忠壅塞。",
"21-30":"鵲笑鳩舞，來遺我酒。大喜在後，授吾龜紐。龍喜張口，起拜福祉。",
"21-31":"搖尾逐災，雲沉孽除。洿泥生𥹭，下為田主。",
"21-32":"白鶴銜珠，夜食為明。膏潤優渥，國歲年豐。",
"21-33":"內執柔德，止訟以嘿。宗邑賴德，禍災不作。",
"21-34":"犬吠驚駭，公拔戈起。玄冥厭火，消散瓦解。",
"21-35":"公悅嫗喜，孫子俱在。榮譽日登，福祿來處。",
"21-36":"鳥鳴哺鷇，長欲飛去。循枝上下，適與風遇。顛隕樹根，命不可救。",
"21-37":"析薪熾酒，使媒求婦。和合齊宋，姜子悅喜。",
"21-38":"鄰不可顧，而求玉女。身多疾癩，誰當媚者。",
"21-39":"遠視無明，不知青黃。黈纊塞耳，使君闇聾。",
"21-40":"剋身巳整，逢禹巡狩。賜我玄珪，蒙受福祉。",
"21-41":"遠望千里，不見黑子。離婁之明，無益於光。",
"21-42":"斧斤所斫，瘡痏不息。針石不施，下即空室。",
"21-43":"齊侯少子，材略美好。求我長女，賤薄不與。反得醜陋，後乃大悔。",
"21-44":"失儷後旅，天門地戶。不知所在，安止無咎。",
"21-45":"烏孫氏女，深目黑醜。嗜欲不同，過時無偶。",
"21-46":"叔駕純騮，南至東萊。求索駒馬，道悅中止。",
"21-47":"二女寶珠，誤鄭大夫。君父無禮，自為作笑。",
"21-48":"陽城太室，神明所息。仁智之居，獨無兵革。",
"21-49":"大蛇為殃，使道不通。歲露鮮少，年榖敗傷。",
"21-50":"三足孤烏，靈明為御。司過罰惡，自殘其家。毀敗為憂。",
"21-51":"車雖駕，兩靷絕。馬欲步，雙輪脫。行不至，道遇害。",
"21-52":"鬱怏不明，為陰所傷。眾霧集聚，共奪日光。",
"21-53":"鸋鴂鴟鴞，治成禦災。周公勤勞，綏德安家。",
"21-54":"名成德就，項領不試。景公耄老，尼父逝去。",
"21-55":"一夫兩心，𡵨刺不深。所為無功，求事不成。",
"21-56":"羿張烏號，彀射天狼。趙國雄勇，敗於榮陽。",
"21-57":"東家殺牛，汙臭腥臊。神背西顧，命絕衰周。",
"21-58":"火起吾後，喜炙我鹿。蒼龍銜水，泉噀柱屋，雖憂無咎。",
"21-59":"桃雀竊脂，巢於小枝。搖動不安，為風所吹。寒心慄慄，常憂不殆。",
"21-60":"徙足去域，飛入東國。有所畏避，深藏隱匿。",
"21-61":"瓊英朱草，仁政得道。鳧鷖在渚，福祿來下。",
"21-62":"陳蔡之危，從者飢罷。明德上通，憂不為凶。",
"21-63":"春桃生花，季女宜家。受福多年，男為封君。",
"21-64":"徑邪賊田，政惡傷民。夫婦呪詛，太上覆顛。",
"22-1":"八口九頭，長舌破家。帝辛沉湎，商滅其墟。",
"22-2":"鬼守我門，呼伯入山。去其室家，舍其兆墓。",
"22-3":"日出阜東，山蔽其明。章甫薦屨，箕子佯狂。",
"22-4":"戴盆望天，不見星辰。顧小失大，福逃墻外。",
"22-5":"兩輪並轉，南上大阪。四馬共轅，無有重難，與語笑言。",
"22-6":"羊驚狼虎，悚耳群聚。行旅稽難，留連愁苦。",
"22-7":"楩生荊山，命制輸班。袍衣剝脫，夏熱冬寒。立餓枯槁，眾人莫憐。",
"22-8":"鳥飛無翼，兔走折足。不常其德，自為羞辱。",
"22-9":"條風制氣，萬物生出。明庶長養，花葉茂榮。",
"22-10":"坤厚地德，庶物蕃息。平康正直，以綏大福。",
"22-11":"𭥦畢附耳，將軍求怒。徑路隔塞，燕雀驚駭。",
"22-12":"東風啟戶，黔啄翻舞。各樂其類，咸得生處。",
"22-13":"兩足四翼，飛入家國。寧我伯姊，與母相得。",
"22-14":"歲暮花落，陽入陰室。萬物伏匿，藏不可得。",
"22-15":"釋然遠咎，避患害早。田獲三狐，以貝為寶。",
"22-16":"鵲延卻縮，不見頭目。日以困急，不能自復。",
"22-17":"秋隼冬翔，數被嚴霜。雞犬夜鳴，家擾不寧。",
"22-18":"班馬還師，以息勞罷。役夫嘉喜，入戶見妻。",
"22-19":"老陽日衰，條多枯枝。爵級不進，逐下摧隤。",
"22-20":"順風吹火，牽騎驥尾。易為功力，因懼受福。",
"22-21":"六人俱行，各遺其囊。黃鶴失珠，無以為明。",
"22-22":"政不暴虐，鳳凰來舍。四時順節，民安其居。",
"22-23":"依叔墻隅，志下勞苦。楚相辰食，韓子低頭。",
"22-24":"三牛生狗，以戌為母。荊夷上侵，避伯出走。",
"22-25":"鶴盜我珠，逃於東都。鵠怒追求，郭氏之墟。不見蹤跡，反為患災。",
"22-26":"升輿中退，舉事不遂。哺麋毀齒，失其道理。",
"22-27":"鴻鵠高飛，鳴求其雌。雌來在戶，雄哺嘻嘻。甚獨勞苦，缹鱉膾鯉。",
"22-28":"褰衣涉河，水深漬罷。賴幸舟子，濟脫無他。",
"22-29":"虎齧龍指，太山之崖。天命不祐，不見其雌。",
"22-30":"明不處暗，智不履危。終日卒歲，樂以笑歌。",
"22-31":"三足俱行，傾危善僵。六指不使，慁累弟兄。樹柱閡車，失其正當。",
"22-32":"舍車而徒，亡其駮牛。雖喪白頭，酒以療憂。",
"22-33":"析薪熾酒，使媒求婦。和合齊宋，姜子悅喜。",
"22-34":"夜視無明，不利賈商。子反笑歡，與市為仇。",
"22-35":"徒行離車，不冒泥塗，利以休居。",
"22-36":"作室山根，人以為安。一昔崩顛，破我壷餐。",
"22-37":"山東山西，各自言安。雖相登望，竟未同堂。",
"22-38":"君子在朝，凶言去消。驚駭逐狼，不見英雄。",
"22-39":"𨏈𨏈墳墳，火燒山根。不潤我鄰，獨不蒙恩。",
"22-40":"南山之蹊，真人所在。德配唐虞，天命為子。保祐歆享，身受大慶。",
"22-41":"龍蛇所聚，大水來處。泱泱濡濡，濙濙礚礚，使我無賴。",
"22-42":"旃裘苫蓋，慕德獻服。邊鄙不聳，以安王國。",
"22-43":"光體春成，陳倉雞鳴。陽明失道，不能自守，消亡為咎。",
"22-44":"下泉苞稂，十年無王。荀伯遇時，憂念周京。",
"22-45":"仁德不暴，五精就舍。四牧𠃔屋，民安其居。",
"22-46":"隨和重寶，眾多貪有。相如睨柱，趙王危殆。",
"22-47":"鳳生五雛，長於南郭。君子康寧，悅樂身榮。",
"22-48":"二人為侶，俱歸北海。入門上堂，拜謁王母。勞賜我酒，女功悅喜。",
"22-49":"逐憂去殃，洿泥生𥹭，下田為王。",
"22-50":"東門之壇，茹藘在坂。禮義不行，與我心反。",
"22-51":"鳧遇稻廬，甘樂趨鰍，雖驅不去。",
"22-52":"清人高子，久屯外野。逍遙不歸，思我君母。公子奉請，王孫嘉許。",
"22-53":"讒人所言，語不成全。虎狼之患，不為我殘。",
"22-54":"張羅捕鳩，鳥麗其災。雌雄俱得，為罔所賊。",
"22-55":"安仁尚德，東鄰慕義，來安吾國。",
"22-56":"猾醜如誠，前後相違。言如鱉咳，語不可知。",
"22-57":"懷璧越鄉，不可遠行。蔡侯兩裘，久苦流離。",
"22-58":"伯氏歸國，多所恨惑。車傾蓋亡，身常驚惶。乃得其願，雄雌相從。",
"22-59":"火石相得，乾無潤澤。利少囊縮，秖益促迫。",
"22-60":"君知聖哲，鳴呼其友。鎮德之徒，可以禮仕。",
"22-61":"騎豚逐羊，不見所望。經涉虎廬，亡羝失羊。",
"22-62":"玄黃瘣隤，行者勞罷。役夫憔悴，處子畏哀。",
"22-63":"右手揜目，不見長叔。失其所得，悔吝相仍。",
"22-64":"免冠進賢，步出朝門。儀體不正，賊孽為患。",
"23-1":"穿胸狗邦，僵離旁舂。天地易紀，日月更始。",
"23-2":"從風縱火，荻芝俱死。三害集房，十子中傷。",
"23-3":"北山有棗，橘柚於聚。荷囊載香，盈我筐筥。",
"23-4":"齎貝贖狸，不聽我辭。繫於虎鬚，牽不得來。",
"23-5":"上下唯邪，戾其元夫。歡心隔塞，君子離居。",
"23-6":"二人輦車，徙去其家。井沸釜鳴，不可安居。",
"23-7":"蹇驢不才，俊驥失時。罷於沙丘，筋力勞盡。",
"23-8":"明傷之初，為穆出交。以讒復歸，名曰豎牛。剝亂叔孫，餧於空丘。",
"23-9":"天火大起，飛鳥驚駭。作事不時，自為身咎。",
"23-10":"土與山連，共保歲寒。終無災患，萬世長安。",
"23-11":"日出阜東，山蔽其明。章甫薦屦，箕子佯狂。",
"23-12":"龍馬上山，絕無水泉。喉燋唇乾，口不能言。",
"23-13":"雄處弱水，雌在海濵。別將持食，悲哀於心。",
"23-14":"庭燎夜明，追嗣日光。陽軟不制，陰雄坐戾。",
"23-15":"三婦同夫。忽不相思。志恆悲愁，顏色不怡。",
"23-16":"鶴盜我珠，逃於東都。鵠怒追求，郭氏之墟。不見武跡，反為患災。",
"23-17":"獮猴冠帶，盜載非位。眾犬共吠，麏走蹶足。",
"23-18":"黍稷禾稻，垂畝方好。中旱不兩，傷風病燺。",
"23-19":"雄聖伏名，人匿麟遠。走鳳飛北，亂禍未息。",
"23-20":"王母多福，天祿所伏。居之寵光，君子有福。東華至真，之氣化生。",
"23-21":"班馬還師，以息勞罷。役夫忻喜，入戶見妻。",
"23-22":"褰裳涉河，流深漬衣。賴幸舟子，濟脫無他。",
"23-23":"行觸大忌，與司命牾。執囚束縛，拘制於吏，幽人有喜。",
"23-24":"被服文德，升入大麓。四門雍肅，登受大福。",
"23-25":"東鄰嫁女，為王妃后。莊公築館，以尊王母。歸于京師，季姜悅喜。",
"23-26":"百足俱行，相輔為彊。三聖翼事，王室寵光。",
"23-27":"危坐至暮，請求不得。膏澤不降，政戾民忒。",
"23-28":"百川朝海，流行不止。路難遼遠，無不到者。",
"23-29":"乘騮駕驪，東至于齊。遭遇仁友，送我以資，厚得利歸。",
"23-30":"禮壞樂崩，成子傲慢。欲求致理，力疲心爛。陰請不當，為簡生殃。",
"23-31":"三人輦車，乘入虎家。王母貪叨，盜我犂牛。",
"23-32":"羊頭兔足，少肉不飽。漏囊敗粟，利無所得。",
"23-33":"新田宜粟，上農得榖。君子唯好，以紆百福。",
"23-34":"夷羿所射，發輒有獲。雙鳧俱得，利以伐國。",
"23-35":"鳧舞鼓翼，嘉樂堯德。虞夏美功，要荒賓服。",
"23-36":"登丘上山，對酒道觀。終年卒歲，優福無患。",
"23-37":"歲暮花落，陽入陰室。萬物伏匿，藏不可得。",
"23-38":"螟虫為賊，害我禾榖。簞缾空虛，飢無所食。",
"23-39":"陽虎脅主，使得不通。火離為殃，年榖病傷。",
"23-40":"四馬共轅，東上太山。騂驤同力，無有重難，與君笑言。",
"23-41":"牧羊稻園，聞虎喧嚾。懼畏悚息，終無禍患。",
"23-42":"揚華不時，冬實生危。憂多橫賊，生不能服。崑崙之玉，所求不得。",
"23-43":"高阜所在，陰氣不臨。洪水不處，為家利寶。",
"23-44":"釋然遠咎，辟患害早。田獲三狐，以具為寶。君子所在，安寧不殆。",
"23-45":"兩目失明，日奪無光。脛足跛曳，不可以行。頓於丘旁，亡妾莫逐，嵬然獨宿。",
"23-46":"鴻飛循陸，公出不復，伯氏客宿。",
"23-47":"葉芳將落，隕其黃葉。失勢傾側，如無所得。",
"23-48":"載船渡海，雖深難咎。孫子俱在，不失其所。",
"23-49":"鵠求魚食，道過射矢。繒加我頸，繳縳羽翼。欲飛不能，為羿所得。",
"23-50":"泥面亂頭，忍耻少羞。日以削消，凶其自搯。",
"23-51":"佩玉累蕊，無以繫之。孤悲獨處，愁哀相憂。",
"23-52":"巨蛇大鰍，戰於國郊。上下隔塞，逐君走逃。",
"23-53":"已動死連，商子揚沙。石流狐狢，擾軍鼓振。吏士恐落。",
"23-54":"二人俱行，別離特食。一身五心，亂無所得。",
"23-55":"三聖相輔，鳥獸喜舞。安樂富有。",
"23-56":"三奇六耦，相隨俱市。王孫善賈，先得利寶。居止不安，洪水為咎。",
"23-57":"三人俱行，二人言北。伯仲欲南，少叔不得。中路分爭，道鬥相賊。",
"23-58":"播天舞光，地乳神所守。樂無咎，言不信。",
"23-59":"坐爭立訟，紛紛匆匆。卒成禍亂，災及家公。",
"23-60":"蛇行蜿蜒，不能上阪。履節安居，可以無憂。",
"23-61":"郤大墻壞，蠹眾木折。狼虎為政，天降罪伐。",
"23-62":"陽不違德，高山多澤。顏子逐兔，未有所得。",
"23-63":"心多畏惡，時愁自懼。雖有小咎，終無大悔。",
"23-64":"眾神集聚，相與議語。南國虐亂，百姓愁苦。興師征伐，更立賢主。",
"24-1":"任重負力，東征不伏。蹈泥履塗，雄師敗覆。",
"24-2":"義不勝情，以欲自營。觀利危寵，折角摧頸。",
"24-3":"懸狟素餐，食非其任。失輿剝廬，休坐徙居。室家何憂。",
"24-4":"鷂鴟娶婦，深目窈身。折腰不媚，與伯相背。",
"24-5":"東風解凍，河川流通。西門子產，升擢有功。",
"24-6":"三足俱行，傾危善僵。六指不便，恩累弟兄。樹柱關中，失其正當。",
"24-7":"京𢈔積倉，𥞫稷以興。巳極行疾，至以饜飽。",
"24-8":"南山之跡，真人所遊。德配唐虞，天命為子，保祐歆享，身受大慶。",
"24-9":"車馳人趨，卷甲相仇。齊魯寇戰，敗於犬丘。",
"24-10":"十五許室，柔順有德。霜降既嫁，文以為合。先王日至，不利出域。",
"24-11":"任力劣薄，遠託邦國。轉車不彊，為癰所傷。",
"24-12":"千歲舊室，將有困急。荷糧負囊，出門直北。",
"24-13":"惡災殆盈，日益彰明。禍不可救，三郤夷傷。",
"24-14":"冠危戴患，身驚不安。與禍馳逐，凶來入門。",
"24-15":"虎狼並處，不可以仕。忠謀輔政，禍必及巳。退隱深山，身乃不殆。",
"24-16":"卵與石鬥，麋碎無處。挈缶之使，不為憂懼。",
"24-17":"五心六意，歧道多怪。非君本志，生我恨悔。",
"24-18":"雨雪載塗，東行破車。旅人無家，利益咨嗟。",
"24-19":"尚刑懷義，月出平地。國亂天常，咎徵滅亡。",
"24-20":"東行破車，步入危家。衡門穿射，無以為主。賣袍續食，糟糠不飽。",
"24-21":"逐禽出門，并失玉丸。往來井上，破甕缺盆。",
"24-22":"孟春醴酒，使君壽考。南山多福，宜行賈市。稻𥹭雌雉，所至利喜。",
"24-23":"持刄操肉，對酒不食。夫亡從軍，少子入獄，抱膝獨宿。",
"24-24":"周師伐紂，剋於牧野。甲子平旦，天下悅喜。",
"24-25":"踦牛傷暑，不能成畝。草萊不墾，年歲無有。",
"24-26":"南邦大國，鬼魅滿室。讓聲相逐，為我行賊。",
"24-27":"噂噂所言，莫如我恆。歡樂堅固，可以長安。",
"24-28":"堯舜禹湯，四聖敦仁。允施德音，民安無窮。旅人相望，未同朝鄉。",
"24-29":"桎梏拘獲，身入牢獄。髠刑受法，終不得釋。耳閉道塞，求事不得。",
"24-30":"桀蹠並處，民困愁苦。行旅遲遲，留連齊魯。",
"24-31":"求雞獲雛，買鱉失魚。出入鈞敵，利得無饒。齊姜宋子，婚姻孔嘉。",
"24-32":"雨師駕駟，風伯吹雲。秦楚爭強，施不得行。",
"24-33":"仲冬無秋，鳥鵲飢憂。困於米食，數驚鸇鵰。",
"24-34":"三羝上山，俱至陰安。遂到南陽，見其芝香。兩崖相望，未同枕床。",
"24-35":"飛至日南，還歸遼東。雌雄相從，和鳴雍雍。解我逈春。",
"24-36":"堯飲舜舞，禹拜上酒。禮樂所豐，可以安處，保我淑女。",
"24-37":"太一置酒，樂正起舞。萬福攸同，可以安處，綏我齯齒。",
"24-38":"白馬騧騮，生乳不休。富我商人，得利饒憂。",
"24-39":"宛馬疾步，盲師坐御。目不見路，中止不到。",
"24-40":"春桃萌生，萬物華榮。邦君所居，國樂無憂。",
"24-41":"把珠入口，蓄為玉寶。得吾所有，忻然嘉喜。",
"24-42":"𥜗燒褲燔，臝剝飢寒。病虐凍攣。",
"24-43":"水沫沉浮，沮濕不居，為心疾憂。",
"24-44":"行如桀紂，雖禱不祥。命衰絕周，文王乏祀。",
"24-45":"蜱蜉戴盆，不能上山。脚推跛蹶，頓傷其顏。",
"24-46":"長子入獄，婦饋母哭。霜降愈甚，鄉晦伏法。",
"24-47":"求犬得兔，請新遇故。雖不當路，踰吾舊舍。",
"24-48":"鳥鳴葭端，一呼三顛。搖動東西，危而不安。靈祝禱祉，疾病無患。",
"24-49":"天厭禹德，命興湯國。祅社舋鼓，以除民疾。",
"24-50":"陰霧作惡，不見白日。邪徑迷道，使君亂惑。",
"24-51":"猿墮高木，不踒手足。握珠懷玉，還歸我室。",
"24-52":"三驪負衡，南取芝香。秋蘭芬馥，盛滿匣匱。利我少姜。",
"24-53":"春生夏乳，羽毛成就。舉不失宜，君臣相好。盜走奔北，終無有悔。",
"24-54":"東行破車，遠反失家。天命訖終，無所禱凶。",
"24-55":"九鴈列陳，雌獨不群。為𦌘所舉，死於庖人。",
"24-56":"二人輦車，徙去其家。井沸釜鳴，不可以居。",
"24-57":"閉塞復通，與善相逢。甘棠之人，解我憂凶。",
"24-58":"賊歛重數，政為民賊。杼軸空虛，去其家室。",
"24-59":"怒非其怨，含垢腐鼠。而呼鵲鴟，自分失餌，致被殃患。",
"24-60":"簮跌帶長，幽思窮苦。瘠貌小瘦，以病疾降。",
"24-61":"三人俱行，各別採桑。藴其筐筥，留我嘉旅。得歸無咎，四月來處。",
"24-62":"逐鳩南飛，與喜相隨。并獲鹿子，多得利歸。雖憂不危。",
"24-63":"驅羊南行，與禍相逢。狼驚吾馬，虎盜我子。悲恨自咎。",
"24-64":"東鄰西國，福喜同樂。出得隨珠，留獲和玉。俱利有喜。",
"25-1":"儋耳穿胸，僵離旁舂。天地易紀，日月更始。蝮螫我手，痛為吾毒。",
"25-2":"慈母之恩，長大無孫。消息襁褓，害不入門。",
"25-3":"偽言妄語，傳相詿誤。道左失跡，不知鄉處。",
"25-4":"鬱怏不明，陰積無光。曰在北陸，萬物彫藏。",
"25-5":"王母多福，天祿所伏。君之寵光，君子有昌。",
"25-6":"不耕而獲，家食不給。中女無良，長子徒足。疏齒善市，商人有息。",
"25-7":"火起上門，不為我殘。跳脫東西，獨得生完。不利出鄰，病疾憂患。",
"25-8":"持刄操肉，對酒不食。夫亡從軍，長子入獄。抱膝獨宿。",
"25-9":"鰍蝦去海，游於枯里。街巷迫狹，不得自在。南北四極，渴餒成疾。",
"25-10":"啞啞笑喜，與歡飲酒。長樂行觴，千秋起舞。拜受大福。",
"25-11":"登高上山，賓於四門。吾士得歡，福為我根。",
"25-12":"天猒周德，命我南國。以禮靜民，兵革休息。",
"25-13":"壅遏隄防，水不得行。火光盛陽，陰蜺伏匿，走歸其鄉。",
"25-14":"海河都市，國之奧府。商人受福，少子玉食。",
"25-15":"東行避兵，南去不祥。西逐凶惡，北迎福生，與喜相迎。",
"25-16":"東家中女，嫫母㝡醜。三十無室，媒伯勞苦。",
"25-17":"破亡之國，天所不福，難以止息。",
"25-18":"驂駕蹇驢，日暮失時。居者無憂，保我樂娛。",
"25-19":"蝃蝀充側，佞幸傾惑。女謁橫行，正道壅塞。",
"25-20":"三羖五牂，相隨俱行。迷入空澤，循谷直北。經涉六駮，為所傷賊。",
"25-21":"載喜抱子，與利為友。天之所命，不憂危殆。荀伯勞苦，未來王母。",
"25-22":"織縷未就，勝折無後。女工多能，亂我政事。",
"25-23":"行露之訟，貞女不行。君子無食，使道壅塞。",
"25-24":"羿張烏號，彀射天狼。鍾鼓不鳴，將軍振旅。趙國雄勇，鬥死榮陽。",
"25-25":"夏臺牖里，湯文厄處。皋陶聽理，歧人悅喜。西望華夏，東歸無咎。",
"25-26":"延頸望酒，不入我口。商人勞苦，利得無有。夏臺牖里，雖危復喜。",
"25-27":"冠帶南遊，與喜相期。儌於家國，拜為逢時。",
"25-28":"東西觸垣，不利出門。魚藏深水，無以樂賓。爵級摧頹，光威減衰。",
"25-29":"兩母十子，轉息無巳。五乳百雛，騂駮驪駒。",
"25-30":"重𥠖祖後，司馬太史。陸氏之災，雕害悲苦。",
"25-31":"內執柔德，止訟以嘿。一邑賴福，禍災不作。",
"25-32":"采唐沬鄉，要期桑中。失信不會，憂思約帶。",
"25-33":"宮成立政，衣就缺袂。恭謙為衛，終無禍尤。",
"25-34":"麒麟鳳凰，子孫盛昌。少齊在門，利以合婚。招衣彈冠，貴人所歡。",
"25-35":"亂危之國，不可涉域。機發身蝢，遂至僵覆。",
"25-36":"千雀萬鳩，與鷂為仇。威挈不敵，雖眾無益，為鷹所擊。",
"25-37":"眾神集聚，相與議語。南國虐亂，百姓愁苦。興師征討，更立聖主。",
"25-38":"顏淵閔騫，以禮自閑。君子所居，禍菑不存。",
"25-39":"三桓子孫，世秉國權。爵世上卿，富於周公。",
"25-40":"鶴鳴九皋，處子失時。載土販鹽，難為功巧。",
"25-41":"方軸圓輪，東行不前。組囊以錐，失其事便。還師振旅，兵革休止。",
"25-42":"魚擾水濁，桀亂我國。駕龍出遊，東之樂邑。天賜我祿，與生為福。",
"25-43":"白虎黑狼，伏司亦長。遮遏牛羊，病我商人。",
"25-44":"履危不安，跌頓我顏，傷踵為癩。",
"25-45":"三人輦車，乘入旁家。王毋貪叨，盜我資財，亡失犂牛。",
"25-46":"三鴈南飛，俱就井地。蝦鰍饒有，利得過倍。",
"25-47":"鷹棲茂樹，猴雀往來。一擊獲兩，伏不枝梧。",
"25-48":"堯舜欽明，禹稷股肱。伊尹往來，進禮登堂。顯德之徒，可以輔王。",
"25-49":"枯旱三年，草葉不生。粢盛空之，無以供靈。",
"25-50":"方口緩唇，為和樞門。解釋鉤帶，商旅以懽。",
"25-51":"鳧溢池水，高陸為海。江河橫流，魚鱉成市。千里無牆，鴛鳳遊行。",
"25-52":"烹魚失刀，駕馬車亡。鈆刀不及，魴鯉腥臊。",
"25-53":"戎狄蹲居，無禮貪叨。非吾族類，君子攸去。",
"25-54":"渡河踰水，濡洿其尾不，為禍憂。捕魚遇蟹，利得無幾。",
"25-55":"河水小魚，不宜勞煩。苛政苦民，君受其患。",
"25-56":"偃武脩文，兵革休安。清人逍遙，未歸空閑。",
"25-57":"九疑鬱林，沮濕不中。鸞鳥所去，君子不安。",
"25-58":"持猬逢虎，患厭不起。遂至懽國，與福笑語。君王樂喜。",
"25-59":"狗生龍馬，公勞嫗苦。家無善駒，折悔為咎。",
"25-60":"嬰孩求乳，慈母歸子。黃麑悅喜，得其甘餌。",
"25-61":"有兩赤鷂，從五隼噪。操矢無括，趣釋爾財。扶伏聽命，不敢動搖。",
"25-62":"伊尹智士，去桀耕野。執順以強，文和無咎。",
"25-63":"逐鹿西山，利入我門。陰陽和調，國無災殃。長子東遊，須其三仇。",
"25-64":"龍興之德，周武受福。長女宜家，與君相保。長股遠行，狸且善藏。",
"26-1":"金柱鐵關，堅固衛災。君子居之，安無憂危。",
"26-2":"轉禍為福，喜來入屋。春成夏囤，可以飲食，保全家室。",
"26-3":"水暴橫行，縁屋壞墻。泱泱溢溢，市師驚惶。居止不殆，與毋相保。",
"26-4":"虎豹熊罷，遊戲山隅。得其所欲，君子無憂。旅人失利，市空無人。",
"26-5":"躬體履仁，尚德止訟。宗邑以安，三百無患。",
"26-6":"江淮易服，玄黃朱飾。靈公夏徵，哀相無極。高位崩顛，失其寵室。",
"26-7":"不虞之患，禍至無門。奄忽暴卒，痛傷我心。",
"26-8":"三塗五嶽，去危入室。凶禍不作，桀盜堯服。失其寵福，貴人有疾。",
"26-9":"配合相迎，利心四鄉。昏以為期，明星熠熠。欣喜君奭，所言得當。",
"26-10":"三手六身，莫適所閑。更相搖動，失事便安。箕子佯狂，國乃不昌。",
"26-11":"虎臥山偶，鹿過後眗。弓矢設張，會為功曹。伏不敢起，遂全其驅，得我美草。",
"26-12":"麟鳳執獲，陰雄失職。自衛返魯，猥昧不起，祿福訖巳。",
"26-13":"欒子作殃，伯氏誅傷。州黎奔楚，失其寵光。",
"26-14":"黃帝出遊，駕龍騎馬。東至太山，南過齊魯。王良御左，文武何咎？不利市賈。",
"26-15":"齊魯爭言，戰於龍門。遘怨致禍，三世不安。",
"26-16":"道理和德，仁不相賊。君子往之，樂有其利。",
"26-17":"嫗妒公妮，毀益亂賴。使我家憒，利得不遂。",
"26-18":"一巢九子，同公共毋。柔順利貞，出入不殆，福祿所在。",
"26-19":"崔嵬北岳，天神貴客。溫仁正直，主布恩德。閔哀不巳，蒙受大福。",
"26-20":"三睢逐蠅，陷墮釜中。灌沸弇殪，與母長決。",
"26-21":"東山西陵，高峻難升。滅夷握纍，使道不通。商旅無功，復反其邦。",
"26-22":"常得自如，不逢禍災。樂只君子，福祿自來。",
"26-23":"范子妙材，戮辱傷膚。然後相國，封為應侯。",
"26-24":"狼虎結集，相聚為保。伺嚙牛羊，道絕不通，病我商人。",
"26-25":"不直杜公，與我爭訟。媒伯無禮，自令塞壅。",
"26-26":"朝鮮之地，箕伯所保。宜人宜家，業處子孫，求事大吉。",
"26-27":"上天樓臺，登降受福，喜慶自來。",
"26-28":"三羊上山，東至平原。黃龍服箱，南至魯陽。貌其佩囊，執綬車中，行人無功。",
"26-29":"天地閉塞，仁智隱伏。商旅不行，利深難得。",
"26-30":"延陵適魯，觀樂太史。車轔白顛，知秦興起。卒兼其國，一統為主。",
"26-31":"槖戢甲兵，歸放馬牛。徑路開通，國無凶憂。朽墻不鑿，病疾難治。",
"26-32":"牛驥同堂，郭氏以亡。國破為墟，君奔走逃。",
"26-33":"大尾小腰，重不可搖。棟撓榱壞，臣為君憂。陽大之言，消不為患，使我復安。",
"26-34":"太一置酒，樂正起舞。萬福攸同，可以安處。綏我鯢齒，指空無餌，不利為旅。",
"26-35":"飲酒醉酗，跳起爭鬥。伯傷叔僵，東家治喪。",
"26-36":"山險難登，渭中多石。車馳𨎥擊，重載傷軸。載擔善躓，跌踒右足。",
"26-37":"爭訟不巳，更相咨詢。張事弱口，被𩬊北走。耳順從心，躬行至仁。不須以兵，天下太平。",
"26-38":"心志無良，傷破妄行。觸廧觝壁，不見戶房。先王閉關，商旅委棄。",
"26-39":"寧夬鴟鴞，治成禦災。綏德安家，周公勤勞。",
"26-40":"清人高子，久在外野。逍遙不歸，思我慈母。",
"26-41":"兩虎爭鬥，服創無處。不成仇讎，行解郤去。",
"26-42":"天女推床，不成文章。南箕無舌，飯多沙糖。虛象盜名，雄雞折頸。",
"26-43":"太子扶蘇，走出遠郊，佞幸成邪，改命生憂。慈母之恩，無路致之。",
"26-44":"寒暑相推，一明一微。赫赫宗周，光榮滅衰。",
"26-45":"雞狗相望，仁道篤行。不吠昏明，各安其鄉。周鼎和餌，國富民有，八極蒙祐。",
"26-46":"牎牖戶旁，道利明光。賢智輔聖，仁施大行。家給人足，海內殷昌。",
"26-47":"雨雪三日，鳥獸飢乏。旅人失宜，利不可得。幾言解患，以療紛難，危者復安。",
"26-48":"白鵠銜珠，夜食為明。膏潤渥優，國歲年豐。中子來同，見惡不凶。",
"26-49":"從豕牽羊，與虎相逢。雖驚不凶。",
"26-50":"鳧鴈啞啞，以水為宅。雌雄相和，心志娛樂。得其所欲，絕其患惡。",
"26-51":"逐狐平原，水遏我前。深不可涉，暮無所得。",
"26-52":"窟室蓬戶，寒賤所處。十里望煙，散渙四方。形體滅亡，下入深淵，終不見君。",
"26-53":"桀紂之主，悖不可輔。貪榮為人，必定其咎。聚斂積實，野在鄙邑，未得入室。",
"26-54":"倉庫盈億，年歲有息。商人留連，雖久有得。陰多陽少，因地就力。",
"26-55":"火山不然，釣鯉失綸。魚不可得，利去我北。三仁同福，以興周國，君子安息。",
"26-56":"童女無媒，不宜動搖。安其居廬，傅毋何憂。",
"26-57":"載風雲毋，遊觀東海。鼓翼千里，見吾愛子。",
"26-58":"鴻盜我𥜗，逃於山隅。不見武跡，使伯心憂。",
"26-59":"視夜無明，不利遠鄉。閉門塞牖，福為我母。",
"26-60":"三狗逐兔，於東北路。利以進取，商人有得。",
"26-61":"武王不豫，周公禱謝，載璧秉珪，安寧如故。",
"26-62":"同載共車，中道別去。爵級不進，君子不興。",
"26-63":"六鴈俱飛，遊戲稻池。大飲多食，食飽無患。舉事不遂，商旅作憒。",
"26-64":"符左契右，相與虐亂。乾坤利貞，𦍒生六子。長大成就，颯然如毋，不利為咎。",
"27-1":"思初悼古，哀吟無輔。陽明不制，上失其所。",
"27-2":"江河淮海，天之奧府。眾利所聚，賓服饒有，樂我君子。",
"27-3":"三鴈俱行，避暑就涼。適與繒遇，為繳所傷。",
"27-4":"秋南春北，隨時休息。處和履中，安無憂凶。",
"27-5":"履危無患，跳脫獨全。不利出門，傷我左踝。疾病不食，鬼哭其室。",
"27-6":"東家凶婦，怒其公姑。毀柈破盆，棄其飯餐，使吾困貧。",
"27-7":"泥滓洿辱，棄捐溝瀆。眾所笑哭，終不顯祿。",
"27-8":"旦往暮還，各與相存，身無凶患。",
"27-9":"六翮長翼，夜過射國。高飛冥冥，羿氏無得。",
"27-10":"蜂蠆之門，難以止息。嘉媚之士，為王所食。從去其室。",
"27-11":"放狐乘龍，為王道東。過時不及，使我憂聾。",
"27-12":"雹梅零墮，心思情憤，亂我魂氣。",
"27-13":"長女三嫁，進退多態。牝狐作妖，夜行離憂。",
"27-14":"轟轟䡘䡘，驅車東西。盛盈必毀，高位崩顛。",
"27-15":"乘船道濟，載水逢火。賴得無患，蒙我生全。",
"27-16":"至德之君，政仁且溫。伊呂股肱，國富民安。",
"27-17":"生不逢時，困且多憂。無有冬夏，心常悲愁。",
"27-18":"南歷玉山，東入生門。登福上堂，飲萬歲漿。",
"27-19":"大斧破木，讒人敗國。東關二五，禍及三子。",
"27-20":"一室百孫，公悅婦懽。相與笑言，家樂以安。",
"27-21":"隨陽轉行，不失其常。君安於鄉，國無咎殃。",
"27-22":"群虎入邑，求索肉食。大人禦守，君不失國。",
"27-23":"弱足刖跟，不利出門。市賈無贏，折明為患。湯火之憂，轉解喜來。",
"27-24":"夏臺幽戶，文君厄處。鬼侯飲食，歧人悅喜。",
"27-25":"棟撓榱壞，廊屋大敗。宮闕空廊，如冬枯樹。",
"27-26":"說以內安，不離其國。室家相懽，幽囚重閉。疾病多求，罪亂憒憒。",
"27-27":"家給人足，頌聲並作。四夷賓服，干戈卷閣。載櫜弓矢。",
"27-28":"六龍俱怒，戰於坂下。倉黃不勝，旅人難苦。",
"27-29":"天下雷行，塵起不明。市空無羊，疾人憂凶。三木不辜，脫歸家邦。",
"27-30":"一指食肉，口無所得。染其鼎鼐，舌饞於腹。",
"27-31":"喜笑不常，失其福慶。口辟言疥，行者畏忌。",
"27-32":"毛生豪背，國樂民富，侯王有德。",
"27-33":"豶豕童牛，童傷不來。三女同堂，生我福人。",
"27-34":"江河淮海，盈溢為害。邑被其瀬，年困無歲。",
"27-35":"兩虎爭鬥，股瘡無處。不成仇讎，行解欲去。",
"27-36":"五岳四瀆，𣶯洽為德。行不失理，民賴恩福。",
"27-37":"載車乘馬，南逢君子。與我嘉福，雖憂無咎。",
"27-38":"缺囊破筐，空無黍稷。不媚如公，棄於糞墻。",
"27-39":"殺行桃園，見虎東西。螳蜋之敵，使我無患。",
"27-40":"飢人入室，政衰弊極。抱其彛噐，奔於他國，因禍受福。",
"27-41":"庭燎夜明，追古傷今。陽弱不制，陰雄坐戾。",
"27-42":"懸狟素餐，食非其任。失輿剝廬，休坐從居。",
"27-43":"喜門福善，繪帛盛熾。日就為得，財寶敵國。",
"27-44":"執綏登車，驂乘東遊。說齊解燕，霸國以安。",
"27-45":"水深無桴，蹇難何遊。商伯失利，庶人愁憂。",
"27-46":"三鳥鴛鴦，相隨俱行。南到饒澤，食魚與𥹭。君子樂長，見惡不傷。",
"27-47":"遠視目盻，臨深苦眩。不離越都，旅人留連。",
"27-48":"終風東西，散渙四方。終日至暮，不見子懽。",
"27-49":"言無要約，不成劵契。",
"27-50":"牛馬聾瞶，不知聲味。遠賢賤仁，自合亂憒。疾病無患，生福在門。",
"27-51":"從商近遊，飽食無憂。囹圄之困，中子見囚。",
"27-52":"據斗運樞，順天無憂。與樂並居。",
"27-53":"姬奭姜望，為武守邦。蕃屏燕齊，周室以彊，子孫億昌。",
"27-54":"亡羊東澤，循隄直北。子思其毋，復返其所。",
"27-55":"張鳥關口，舌直距齒。然諾不行，政亂無緒。",
"27-56":"載船逢火，憂不為禍。家在山東，入門見公。",
"27-57":"絕言異路，心不相慕。蛇子兩角，使我心惡。",
"27-58":"鼻頂移徙，君不安坐。枯竹復生，失其寵榮。",
"27-59":"殷商以亡，火息無光。年歲不長，殷湯光明。",
"27-60":"文王四乳，仁愛篤厚。子畜十男，無有折叐。",
"27-61":"熊罷犲狼，在山陰陽。伺鹿取獐，道候畏難。",
"27-62":"凋葉被霜，獨蔽不傷。駕入喜門，與福為婚。",
"27-63":"黃離白日，照我四國。元首昭明，民賴恩福。漢有遊女，人不可得。",
"27-64":"順風直北，與歡相得。歲熟年樂，邑無宼賊。長女行嫁，子孫不昌，係疾為殃。",
"28-1":"日在北陸，陰蔽陽目。萬物空虛，不見長育。",
"28-2":"鬼泣哭社，悲商無後。甲子昧爽，殷人絕祀。",
"28-3":"涉塗履危，不利有為。安坐垂裳，乃無災殃。門戶自開，君憂不昌。",
"28-4":"陽失其紀，枯木復起。秋華冬實，君不得息。",
"28-5":"大樹之子，百條共毋。當夏六月，枝葉盛茂。鸞鳥以庇，召伯避暑。偏偏偃仰，甚得其所。",
"28-6":"秉龯執殳，挑戰先驅。不從元帥，敗破為憂。",
"28-7":"啟室開關，逃得釋冤。夏臺牖里，湯文悅喜。",
"28-8":"衰滅無成，淵溺在傾。狗吠夜驚，家乃不寧。枯者復華，幽人無憂。",
"28-9":"西鄰少女，未有所許。志如委衣，不出房戶。心無所處，傅毋何咎。",
"28-10":"狗吠夜驚，履鬼頭頸。危者弗傾，患滅不成。",
"28-11":"當年少寡，獨與孤處。雞鳴狗吠，無敢誰者。我生不辰，獨嬰寒苦。",
"28-12":"無道之君，鬼哭其門。命與下國，絕得不食。",
"28-13":"乘龍南遊，夜過糟丘。脫厄無憂，矰絕弩傷。羿不得羹。",
"28-14":"馬躓車傷，長舌破家。東關二五，晉君出走。",
"28-15":"瓜葩匏實，百女同室。苦醯不熟，未有妃合。",
"28-16":"晨風文翰，大舉就溫。昧過我邑，羿無所得。",
"28-17":"瀺瀺浞浞，塗泥至轂。馬濘不進，虎齧我足。",
"28-18":"膠車駕東，與雨相逢。故革懈惰，頹輪獨坐，憂不為禍。",
"28-19":"六家作權，公室剖分。陰制其陽，唐叔失明。",
"28-20":"去室離家，來奔大都。火息復明，姬伯以昌，商人失功。",
"28-21":"牧羊稻園，聞虎喧嚾。危懼惴息，終無禍患。",
"28-22":"嬰孩求乳，母歸其子，黃麑懽喜。",
"28-23":"廓落失業，跨禍度福，利無所得。",
"28-24":"出入不時，憂禍為災。行人失牛，利去不來。老馬少駒，勿與久居。",
"28-25":"風怒漂水，女惑生疾。陽失其服，陰孽為賊。",
"28-26":"車馬病傷，不利越鄉。幽人元亨，去晦就明。",
"28-27":"三奇六偶，各有所主。周南召南，聖人所在。德義流行，民悅以喜。",
"28-28":"典冊法書，藏閣蘭臺，雖遭亂潰，獨不遇災。",
"28-29":"坐爭立訟，紛紛怱怱。卒成禍亂，災及家公。",
"28-30":"憂凶為殘，使我不安。從之南國，以除心疾。",
"28-31":"愛我嬰女，牽引不與。冀幸高貴，反得不興。",
"28-32":"宜行賈市，所聚必倍。載喜抱子，與利為市。",
"28-33":"坐席未溫，憂來扣門。踰墻北走，兵交我後。脫於虎口。",
"28-34":"赤帝懸車，廢職不朝。叔帶之災，居于汜廬。",
"28-35":"子畏於匡，厄困陳蔡。明德不危，竟自克害。",
"28-36":"逐鴈南飛，馬疾牛罷。不見魚池，失利憂危。牢戶之冤，脫免無患。",
"28-37":"推輦上山，高仰重難。終日至暮，不見阜巔。",
"28-38":"憂不為患，福在堂門。使吾偃安。",
"28-39":"春桃始華，季女宜家。受福多年，男為邦君。",
"28-40":"高山之巔，去谷億千。雖有兵寇，足以自守。",
"28-41":"過時歷月，役夫憔頰。處子歎室，思我伯叔。",
"28-42":"太微復明，說升傅巖。乃稱高室，疾在頭頸。和不能生，滅其令名。",
"28-43":"旁多水星，三五在東。早夜晨行，勞苦無功。",
"28-44":"東鄉煩煩，相與笑言。子般鞭犖，圉人作患。",
"28-45":"鼻移在頭，枯葦復生。下朽上榮，家乃不寧，其金不成。",
"28-46":"蝦蟆群聚，從天請雨。雲雷疾聚，應時輒下，得其願所。",
"28-47":"大步上車，南到喜家。送我貂裘，與福載來。",
"28-48":"賊仁傷德，天怒不福。斬刈宗社，失其宇守。",
"28-49":"從猬見虎，雖危不殆，終巳無咎。",
"28-50":"履素行德，卒蒙祐福。與堯侑食，君子有息。",
"28-51":"利在北陸，寒苦難得。憂危之患，福為道門，商叔生存。",
"28-52":"四蹇六盲，足痛難行。終日至暮，不離其鄉。",
"28-53":"臺駘昧子，明知地理。障澤宣流，封君河水。",
"28-54":"畜水得時，以備火災。柱車絆馬，郊行出旅，可以無咎。",
"28-55":"歲暮華落，君衰於德。勞寵損墮，陰奪其室。",
"28-56":"夏販蔡悲，千里為市。黃䈎殪鬱，利得無有。",
"28-57":"仲春巡狩，東見群后。昭德允明，不失其所。",
"28-58":"栵潔縲縲，結締難解。嫫毋衒嫁，媒不得坐。自為身禍。",
"28-59":"烏鳴庭中，以戒災凶。重門擊柝，備憂暴客。",
"28-60":"朝霽暮霞，瀐我衣𥜗。退無得牛。",
"28-61":"抱璞懷玉，與桀相觸。詘坐不中，道無良人。",
"28-62":"兩心相悅，共其柔筋。夙夜在公，不離房中，得君子意。",
"28-63":"載餽如田，破鉏失食。苗穢不辟，獨飢於年。",
"28-64":"甘露醴泉，太平機關。仁德感應，歲樂民安。",
"29-1":"太王為父，季歷孝友。文武聖明，仁德興起。弘張四國，載福綏厚。",
"29-2":"猿墮高木，不踒手足。保我金玉，還歸其室。",
"29-3":"重耳㳟敏，遇讒出處。北奔狄戎，經涉齊楚。以秦代懷，誅殺子圉，身為霸主。",
"29-4":"𠋣鋒據㦸，傷我胸臆，拜折不息。",
"29-5":"狗冠雛步，君失其居。出門抵山，行者憂難。水灌我園，高陸為泉。",
"29-6":"眾鳥所翔，中有大壯。爪牙長頭，為我驚憂。",
"29-7":"雷行相逐，無有休息。戰於平陸，為夷所覆。",
"29-8":"禹鑿龍門，通利水泉。同注滄海，民得安土。",
"29-9":"堯舜仁德，養賢致福。眾英積聚，國無寇賊。商人失利，來爭寶貨。",
"29-10":"陸居少泉，山高無雲。車行千里，塗不汙輪。渴為我怨，佳思廣得。",
"29-11":"朝視不明，夜不見光。皆抵空床，季女奔亡，愴焉心傷。",
"29-12":"齊魯求國，仁聖輔德。進禮雅言，定公以安。",
"29-13":"束帛玄珪，君以布德，伊呂百里，應聘輔國。",
"29-14":"棘鉤我𥜗，為絆所拘。靈巫拜禱，禍不成災。東山之邑，中有土服，可以饒飽。",
"29-15":"門燒屋燔，為下所殘。西行出戶，順其道里，虎臥不起，牛羊歡喜。",
"29-16":"牆高蔽日，崑崙翳月。遠行無明，不見歡叔。",
"29-17":"天地際會，不見內外。祖辭遣送，與世長決。",
"29-18":"深水難涉，塗難至轂。牛罷不進，濘陷我疾。",
"29-19":"羊驚狼虎，獼猴群走。無益於僵，為齒所傷。",
"29-20":"履蛇躡虺，與鬼相視。驚哭失氣，如騎虎尾。",
"29-21":"車驚人墮，兩輪脫去。行者不至，主人憂懼。結締復解，夜明為喜。",
"29-22":"南販北賈，與怨為市，利得自治。",
"29-23":"延陵適魯，觀樂太史。車轔白巔，知秦興起。卒兼其國，一統為主。",
"29-24":"出門逢患，與禍為怨。更相擊刺，傷我手端。",
"29-25":"獐鹿同走，自燕嘉喜。公子好遊，他人多有。",
"29-26":"㳟寬相信，履福不殆。從其邦域，與喜相得。",
"29-27":"欲飛無翼，鼎重折足。失其喜利，苞羞為賊。上妻之家，喜除我憂，解吾思愁。",
"29-28":"府藏之富，王以振貸。捕魚河海，𦊙網多得。",
"29-29":"有黃鳥足，歸呼季玉。從我睢陽，可辟刀兵。與福俱行，有命久長。",
"29-30":"陰生麏鹿，鼠舞鬼哭。靈龜陸蒙，釜甑草土。仁智盤桓，國亂無緒。",
"29-31":"風塵暝迷，不見南北。行人失路，復反其室。",
"29-32":"金革白黃，宜利戒市。嫁娶有息，商人悅喜。",
"29-33":"匏𤓰之德，宜繫不食。君子失與，官政懷憂。",
"29-34":"乘船渡濟，載冰逢火。賴得免患，蒙我所恃。",
"29-35":"道塗多石，傷車折軸。與市為仇，不利客宿。",
"29-36":"託寄之徒，不利請求。結衿無言，乃有悔患。",
"29-37":"三羊爭妻，相逐奔馳。終日不食，精氣竭罷。",
"29-38":"退惡防患，見在心苗。日中之恩，解釋倒懸。",
"29-39":"兩足四翼，飛入嘉國。寧我伯姊，與母相得。",
"29-40":"寒露所降，凌制堅冰。草木瘡傷，華落葉亡。",
"29-41":"后稷農功，富利我國。南畝治理，一室百子。",
"29-42":"設網張羅，捕魚園池。網𦊙自決，雖得復失。危訴之患，受其低歡。",
"29-43":"路與縣休，侯伯恣驕。上失其盛，周室衰微。",
"29-44":"逐走追亡，相及扶桑。復見其鄉，使我悔喪。",
"29-45":"履福綏厚，載福受祉。衰微復起，継世長久。疾病獻凌，晉人赴告。",
"29-46":"鰥寡孤獨，祿命苦薄。入宮無妻，武子哀悲。",
"29-47":"山沒丘浮，陸為水魚。燕雀無巢，民無室廬。",
"29-48":"冠帶南遊，與福喜期。徼於嘉國，拜為逢時。",
"29-49":"東行亡羊，失其羝牂。少婦無夫，獨坐空廬。",
"29-50":"探巢捕魚，耕田捕鰍。費日無功，右手空虛。",
"29-51":"東行飲酒，與喜相抱。福吾家利，來從父母。水澤之徒，望邑而處。",
"29-52":"妄怒失精，自令畏悔。忪忪之懼，君子無咎。",
"29-53":"白雲如帶，往往旗處。飛風送迎，大雹將下。擊我禾稼，僵死不起。",
"29-54":"南至之日，陽消不息。北風烈寒，萬物藏伏。",
"29-55":"火中仲夏，鴻鴈來舍。體重難移，未能高舞。君子顯名，不失其譽。",
"29-56":"北行出門，履陷躓顛。踒足據塗，汙我襦褲。",
"29-57":"輕車醊祖，焱風暴起。促亂祭器，飛揚錯華。明神降祐，道無害寇。",
"29-58":"酒為歡伯，除憂來樂。福喜入門，與君相索。使我有德。",
"29-59":"三足孤烏，靈明督郵。司過罰惡，自賊其家，毀敗為憂。",
"29-60":"三河俱合，水怒湧躍。壞我王屋，民飢於食。",
"29-61":"南行棗園，惡虎畏班。執火消金，使我無患。",
"29-62":"求鹿過山，與利為怨。闇聾不言，誰知其歡。",
"29-63":"行旅困蹵，失明守宿。囹圄之憂，啟執出遊。",
"29-64":"據棘履危，跌刺為憂。夫婦不和，亂我良家。",
"30-1":"執轡四驪，王以為師。陰陽之明，載受東齊。",
"30-2":"春秋禱祝，解過除憂，君子無咎。",
"30-3":"坐車乘軒，據國子民。虞叔受命，六合和親。",
"30-4":"開戶下堂，與福相迎。祿于公室，曾孫以昌。",
"30-5":"高木腐巢，漏濕難居。不去甘棠，使我無憂。",
"30-6":"三女為姦，俱遊高園。倍室夜行，與伯笑言。不忍主母，為設歡酒，冤尤誰禱。",
"30-7":"漏卮盛酒，無以養老。春貸黍稷，年歲實有。履道坦坦，平安何咎。",
"30-8":"松柏枝葉，常茂不落。君子惟體，日富安樂。",
"30-9":"夫婦不諧，為燕攻齊。良弓不張，騎駟憂凶。",
"30-10":"出令不勝，反為大災。強不克弱，君受其憂。",
"30-11":"奔牛相錯，敗亂緒業，民不得作。",
"30-12":"載璧秉珪，請命於河。周公剋敏，沖人瘳愈。",
"30-13":"素車偽馬，不任重負。王侯出征，憂危為咎。",
"30-14":"大樹之子，同條共母。比至火中，枝葉盛茂。",
"30-15":"壅遏隄防，水不得行。火盛陽光，陰蜺伏藏，走婦其歸。",
"30-16":"五嶽四瀆，合潤為德。行不失理，民賴恩福。",
"30-17":"駕駿南遊，虎驚我羊。陰不奉陽，其光顯揚。言之謙謙，奉義解患。",
"30-18":"早霜晩雪，傷害禾麥。損功棄力，飢無所食。",
"30-19":"歧周海隅，有樂無憂。可以辟難，全身保財。",
"30-20":"陰蔽其陽，日闇不明。君憂其國，求騂得黃，駒犢從行。",
"30-21":"金城鐵郭，上下同力。政平民歡，寇不敢賊。",
"30-22":"平公有疾，迎醫秦國。和不能知，晉人赴國。",
"30-23":"戴堯扶禹，從喬彭祖。西過王母，道里夷易。無敢難者。",
"30-24":"羔羊皮革，君子朝服。輔政天德，以合萬國。",
"30-25":"據鍾鼓翼，將軍受福。安帖之家，虎狼與憂。履危不強，師行何咎。",
"30-26":"嫡庶不明，孽亂生殃，陳失其邦。",
"30-27":"鳥驚狐鳴，國亂不寧，上弱下強，為陰所刑。",
"30-28":"六月採𦬊，征伐無道。張仲方叔，剋勝飲酒。",
"30-29":"被繡夜行，不見文章。安坐玉堂，乃無咎殃。長子帥師，得其正常。",
"30-30":"時乘六龍，為帝使東。達命宣旨，無所不通。",
"30-31":"昧暮乘車，東至伯家。踰梁越河，濟脫無他。",
"30-32":"東風解凍，和氣兆升，年歲豐登。",
"30-33":"三狸搏鼠，遮遏前後，無於還域，不得脫走。",
"30-34":"綏德孔明，履祿久長。貴且有光，疾病憂傷。",
"30-35":"三虎搏狼，力不相當。如摧壅祐，一擊破亡。",
"30-36":"使伯東乘，恨不肯行。與叔爭訟，更相毀傷。",
"30-37":"把空握虛，鴞驚我雛。利去不來。",
"30-38":"李華再實，鴻升降集。仁哲以興，𨺚國無賊。",
"30-39":"東山皋洛，一朝殞落。勇悍不服，金玦玩好。衣為身賊。",
"30-40":"飛文汙身，為邪所牽。青蠅分白，貞孝放逐。",
"30-41":"南山大木，文身其目。制命出令，東里田畝。尊主安居，鄭國無患。",
"30-42":"泉起崑崙，東出玉門。流為九河，無有憂患。",
"30-43":"命短不長，中年夭傷。鬼泣哭堂，哀其子亡。",
"30-44":"君臣不和，上下失宜，宋子哭歌。",
"30-45":"苛政日作，螟食華葉。割下啖上，民被其賊。秋無所得。",
"30-46":"南行戴鎧，登場九魁。車傷牛罷，日暮咨嗟。",
"30-47":"春東夏南，隨陽有功，與利相逢。",
"30-48":"頭尾顛倒，不知緒處。君失其國。",
"30-49":"言無要約，不成劵契。殷叔季姬，公孫爭之。強入委禽，不悅子南。",
"30-50":"缺破不成，胎卵不生，不見其形。",
"30-51":"見蛇交悟，惜蚖畏惡，心乃無悔。",
"30-52":"河水孔穴，壞敗我室。水深無涯，魚鱉傾側。",
"30-53":"五嶽四瀆，地得以安。高而不危，敬慎避患。",
"30-54":"南至之日，陽消不息。北風烈寒，萬物伏藏。",
"30-55":"五利四福，俱佃居邑。黍稷盛茂，多獲高積。",
"30-56":"公孫駕車，載遊東齊。延陵子產，遺季紵衣。疾病哀悲。",
"30-57":"交亂當道，民困愁苦。望羊置群，長子在門。",
"30-58":"金玉滿室，忠直乘危。三老凍餓，鬼奪其室。求魚河海，網舉必得。",
"30-59":"日入幽慝，陽明隱伏。小人勞心，求事不得。",
"30-60":"頻逢社飲，失利後福。不如子息，舊居故處。申請必與，乃無大悔。",
"30-61":"南有嘉魚，駕黃取遊。魴鱮詡詡，利來無憂。",
"30-62":"黃裳建元，文德在身。祿祐洋溢，封為齊君。賈市無門，股肱多根。",
"30-63":"口不從心，欲東反西。與意乖戾，動步失使。",
"30-64":"虎狼之鄉，日爭凶訟。叨𠇍為長，不能定從。",
"31-1":"十䆫多明，道里通利。仁智君子，國安不僵。",
"31-2":"心惡來怪，衝衝何懼。顏伯子騫，尼父聖母。",
"31-3":"鳥鳴呼子，哺以酒脯。高樓水處，來歸其母。",
"31-4":"國馬生角，陰孽萌作。變易常服，君失于宅。",
"31-5":"入宇多悔，耕石不富。衡門屢空，使士失意。",
"31-6":"情懦行賈，遠涉山阻。與旅為市，不危不殆，利得十倍。",
"31-7":"梁破橋壞，水深多畏。陳鄭之間，絕不得前。",
"31-8":"雙鳧俱飛，欲歸稻池。經涉萑澤，為矢所射，傷我胸臆。",
"31-9":"謾誕不誠，倍梁滅文。許人賣牛，三失爭之。失利後時，公孫懷憂。",
"31-10":"南國凶飢，民食糟糠。少子困捕，利無所得。",
"31-11":"狗吠非主，狼虎夜擾。驚我東西，不為家咎。",
"31-12":"望龍無目，不見手足。入水求玉，失其所欲。",
"31-13":"以鹿為馬，欺誤其主。聞言不信，三口為咎。黃龍三子，中樂不殆。",
"31-14":"養幼新婚，未能出門。登宋望齊，不見太師。",
"31-15":"王孫季子，相與為友。明𠃔篤誠，升擢薦舉。",
"31-16":"山水暴怒，壞梁折柱。稽難行旅，留連愁苦。",
"31-17":"鸇鳩徙巢，西至平州。遭逢雷電，破我葦廬。室家飢寒，思吾故初。",
"31-18":"登高傷軸，上阪棄粟。販鹽不利，買牛折角。",
"31-19":"祝施王孫，能事鬼神。節用綏民，衛國以存。饗我旨酒，眉壽多年。",
"31-20":"九里十山，道郤峻難。牛馬不前，復反來還。",
"31-21":"枯樹不華，空淵無魚。蕉鳥飛翔，利棄我去。",
"31-22":"雄狐唯唯，登上山嵬。昭告顯功，大福允興。",
"31-23":"啞啞笑喜，相與飲酒。長樂行觴，千秋起舞。拜受大福。",
"31-24":"大推破轂，長舌亂國。床第之言，三世不安。",
"31-25":"男女合室，二姓同食。婚姻孔云，宜我孝孫。",
"31-26":"千仞之墻，禍不入門。金籠鐵疏，利以辟兵。欲南上阪，轉萬不轉，還車復返。",
"31-27":"華言風語，自相詿誤。終無凶事，安寧如故。",
"31-28":"汎汎柏舟，流行不休。耿耿寤寐，公懷大憂。仁不遇時，退隱窮居。",
"31-29":"大尾小頭，重不可搖。上弱下強，陰制其雄。",
"31-30":"一身三口，語無所主。東西南北，迷惑失道。",
"31-31":"雌單獨居，歸其本巢。毛羽憔顇，志如死灰。",
"31-32":"南行求福，與喜相得。封受上賞，鼎足輔國。",
"31-33":"過時不歸，苦悲雄雌。徘徊外國，與母分離。",
"31-34":"堯舜在國，陰陽和得。𣵠聚衣常，晉人無殃。",
"31-35":"周城之降，越裳夷通，疾病多祟，鬼哭其公。鳥子野心，宿客未同。",
"31-36":"申酉脫服，牛馬休息。君子以安，勞者得歡。",
"31-37":"凱風無毋，何怙何恃。幼孤弱子，為人所咎。",
"31-38":"出門上堂，從容牖房。不失其常，天牢北戶，勞者憂苦。",
"31-39":"天厭周德，命與南國。以禮静民，兵革休息。",
"31-40":"常葉折衝，佐鬥者傷。暴君失國，良臣破殃。",
"31-41":"合歡之國，嘉喜我福。東嶽西山，朝齊成恩。",
"31-42":"耕石不生，棄禮無名。縫衣失針，𥜗褲不成。",
"31-43":"聾瞢闇瞢，跛踦不行。坐尸爭骸，身被火災，因其多憂。",
"31-44":"長生太平，仁政流行。四方歸德，社稷康榮。",
"31-45":"桀跖並處，民之愁苦。擁兵荷糧，戰於齊魯。合卺同牢，姬姜並居。",
"31-46":"南與凶俱，破車失𥜗。西行無褲，亡其寶賂。",
"31-47":"空慒注器，豚彘不至。張弓祝雞，雄父飛去。",
"31-48":"望尚阿衡，太宰周公。蕃屏湯武，立為王侯。",
"31-49":"朝鮮之地，箕子所保。宜家宜人，業處子孫。",
"31-50":"昔憂解笑，故貪今富。載筞履善，與福俱遇。",
"31-51":"叔迎伯兄，遇卷在陽。君子季姬，並坐鼓簧。",
"31-52":"順風縱火，芝艾俱死。三官集房，十子中傷。",
"31-53":"駕車入里，求鮮魴鯉。非其肆居，自令失市。君子所在，安無危咎。",
"31-54":"拔劍傷手，見敵不起，良臣無佐，困辱為咎。",
"31-55":"亂君之門，佐鬥傷跟。營私貪祿，身為悔殘。東下太山，見我所歡。",
"31-56":"慈母望子，遙思不已。久客外野，使我心苦。",
"31-57":"魴生淮郤，一轉為百。周流四海，無有患惡。",
"31-58":"甘露醴泉，太平機關。仁德感應，歲樂民安。",
"31-59":"桴薇出車，魚麗思初。上下從急，君子免憂。",
"31-60":"豕生魚魴，鼠舞庭堂。雄佞施毒，上下昏荒，君失其邦。",
"31-61":"三頭六目，道畏難宿。寒苦之國，利不可得。",
"31-62":"驚雀銜𦭘，以生孚乳。昆弟六人，姣好弟孝。各同心願，和悅相樂。",
"31-63":"文君之德，仁義致福。年無胎天，國富民實。君子在堂，曾累益恩。",
"31-64":"秋梁未成，無以至陳。水深難涉，使我不前。",
"32-1":"登墀踒足，南行折角。長夜之室，不逢忠直。",
"32-2":"燕雀衰老，悲鴻入海。憂不在鄉，𦍑池其羽。頡頏上下，在位獨處。",
"32-3":"開門除憂，伯自外來。切切無患，我之得歡。",
"32-4":"効耕釋秬，有所疑止，空虛無子。",
"32-5":"張牙切齒，断怒相及。咎起蕭墻，牽引吾子。患不可解，憂驚吾母。",
"32-6":"履不容足，南山多棘。母出房闥，乃無疾病。",
"32-7":"牛騂亡子，鳴於大野。申後陰徵，罡歸其母。",
"32-8":"龍生于淵，因風身天。章虎炳文，為凶敗軒。發輗溫谷，暮宿崑崙。終身無患，充精炤燿，不被禍難。",
"32-9":"既嫁宜吉，出入無憂。三聖並居，國安無災。",
"32-10":"北陸陽伏，不知白黑。君子傷讒，正害善人。",
"32-11":"一身兩頭，近適二家，亂不可治。",
"32-12":"牝馬牝駒，歲字不休。君子衣服，利得有餘。",
"32-13":"南行懷憂，破其金輿。安坐故廬，乃無災患。",
"32-14":"憂人之患，履傷浮願。為身禍殘，篤心自守。與喜相抱。",
"32-15":"咸陽辰巳，長安戌亥。丘陵生上，非魚鰍市。可以避不，終無凶咎。",
"32-16":"不知何孫，夜來扣門。我慎外寢，兵戎且來。",
"32-17":"昧旦不明，暗我無光。喪滅失常，使我心傷。",
"32-18":"江陰水側，舟楫破乏。孤不得南，豹無以比。雖欲會盟，河水絕梁。",
"32-19":"神之在丑，逆破為咎。不利西南，人休止後。",
"32-20":"然諾不行，欺天誤人。使我靈宿，夜歸溫室。神怒不直，鬼擊無目。欲求福利，適反自賊。",
"32-21":"攘臂極肘，怒不可止。狼戾復佷，無與為市。",
"32-22":"販馬賣牛，會值虛空。利得鮮少，留連為憂。",
"32-23":"高樓陸處，以避風雨。深堂邃宇，君安其所。牝雞之息，為我利弗。求得弗得。",
"32-24":"阿衡服箱，太一載行。逃時歷舍，所之吉昌。",
"32-25":"飛來之福，入我嘉室，以安吾國。",
"32-26":"不孝之患，子為毋殘。老耄莫養，獨坐空垣。",
"32-27":"南過棘門，鉤裂我冠。鬥之傷𥜗，使君恨憂。",
"32-28":"重或射卒，不知所定。質疑蓍龜，孰可辟大。明神報荅，告以肌如。",
"32-29":"驎麑鳳稚，安樂無憂。捕魚河海，利踰從居。",
"32-30":"新田宜粟，上農得榖。君子推德，千百以福。",
"32-31":"簪短帶長，幽思苦窮。瘠蟸小瘦，以病之隆。",
"32-32":"黃帝所生，伏羲之宗。兵刀不至，利以居止。",
"32-33":"爭訟之門，不可與鄰。出入為憂，生我心患。",
"32-34":"朽根枯株，不生肌膚。病在心腹，日以焦勞。",
"32-35":"雨師娶婦，黃巖季子。成禮就婚，相呼南上。膏我下土，歲年大茂。",
"32-36":"冬採微蘭，地凍堅難。利走室北，暮無所得。",
"32-37":"昧之東域，誤過虎邑。失我熊胔，飢無所食。",
"32-38":"日暮閉目，隨陽休息。箕子以之，乃受其福。舉首多言，必為悔殘。",
"32-39":"蓼蕭瀼瀼，君子龍光。鳴鸞雍雍，福祿來同。",
"32-40":"鳥飛無翼，兔走折足。雖不會同，未得醫工。",
"32-41":"五勝相賊，火得水息。精光消滅，絕不長續。",
"32-42":"東資齊魯，得騂犬馬。便辟能言，巧賈善市。八鄰併戶，請火不與。人道閉塞，鬼守其宇。",
"32-43":"爭雞失羊，亡其金囊，利不得長。陳蔡之患，賴楚以安。",
"32-44":"九登十涉，馬跌不前。管子佐之，乃能上山。",
"32-45":"東鄰愁苦，君亂天紀。甘貪祿寵，必受其咎。意合志同，自外相從，見吾伯公。",
"32-46":"三狸捕鼠，遮遏前後。死於壞城，不得脫走。",
"32-47":"狼虎爭彊，禮義不行。兼吞其國，齊晉無主。",
"32-48":"五嶽四瀆，合潤為德。行不失理，民賴息福。",
"32-49":"六月種黍，歲晚無雨。秋不宿酒，神失其所。先困後通，與福相逢。",
"32-50":"騋牝龍身，日取三千。南上蒼梧，與福為婚。道里夷易，身安無患。",
"32-51":"出入休居，安止相憂。上室之權，虎為季殘。",
"32-52":"南山昊天，刺政關身。疾病毋辜，背憎為仇。",
"32-53":"蒼耳東從，道頓跂踦。日辰不良，病為祟禍。",
"32-54":"兄征東燕，弟伐遼西。大剋勝還，封君河間。",
"32-55":"播輸折輻，馬不得行。豎牛之讒，賊其父兄。布裘不傷，終身無殘。",
"32-56":"駕之南海，晨夜不止。君子勞疲，僕使燋苦。",
"32-57":"怨虱燒被，忿怒生禍。偏心作難，意如為亂。",
"32-58":"張狂妄行，竊食盜糧。狗吠非主，嚙傷我足。",
"32-59":"警蹕戒道，先驅除害。王后親桑，以率群功，安我祖宗。",
"32-60":"門戶乏食，困無誰告。對門不通，莫所歸急。種藏五榖，一花百葉。",
"32-61":"被蔽復貌，危者得安。鄉善無患，商人有息，利來入門。",
"32-62":"壘壘壘壘，如其之室。一身十子，古公治邑。",
"32-63":"三嫗治民，不勝其任。兩馬爭車，壞敗室家。",
"32-64":"蔽鏡無光，不見文章。少女不市，棄其郤王。",
"33-1":"軟弱無輔，不能自理。意在外野，心懷勞苦，雖憂無殆。",
"33-2":"周成之隆，刑措無凶。太宰讃右，君子作仁。",
"33-3":"穴有孤烏，坎生蝦蟆。象出萬里，不可得捕。",
"33-4":"俱為天民，雲過吾西。伯氏嫉妒，與我無恩。",
"33-5":"三首六目，政多煩惑。皋陶瘖聾，亂不可從。",
"33-6":"德積不輕，辭王釣耕。三媒不巳，大福來成。",
"33-7":"堅固相親，六體不易，執以安全。雨師駕西，濡我轂輪。張伯李季，各坐關門。",
"33-8":"方內不行，輻摧輪傷。馬楚踶甚，受子閔時。",
"33-9":"畜牝無駒，養雞不雛。群羊三歲，不生兩頭。",
"33-10":"老耄罷極，無取中直。懸輿致仕，得歸鄉里。",
"33-11":"縮緒亂絲，手與為哭。越畝逐兔，斷其禪𥜗。",
"33-12":"海老水乾，魚鱉盡索。藁落無潤，獨有沙石。",
"33-13":"入市求鹿，不見頭足。終日至夜，竟無所得。",
"33-14":"築門壅戶，虎臥當道。驚我驊騮，不利出處。",
"33-15":"陶朱白圭，善賈息資。公子王孫，富貴不貧。",
"33-16":"王良善御，伯樂知馬。周旋步驟，行中規矩。止息有節，延命壽考。",
"33-17":"堯問伊舜，聖德增益。使民不懼，安無悚愓。",
"33-18":"昭公失常，季氏悖狂。遜齊處鄆，喪其寵身。",
"33-19":"昏暮不行，候待旦明。從住止後，未得相從。",
"33-20":"安上宜官，一日九遷。升擢超等，牧養常山。",
"33-21":"去惡就凶，東西多訟。行者無功。",
"33-22":"老馬垂耳，不見百里。君子弗恃，商人莫取，無與為市。",
"33-23":"蝸螺生子，深目黑醜。似類其毋，雖或相就，眾人莫取。",
"33-24":"百足俱行，相輔為強。三聖翼事，不見寵光。",
"33-25":"容民畜眾，履德有信。大人受福，童蒙憂惑，利無所得。",
"33-26":"左跌右僵，前躓觸桑。其指據石，傷其弟兄。老蠺不作，家無織帛。貴貨賤身，久留連客。",
"33-27":"昏人宜明，賣食老昌。國祚東表，號稱太公。",
"33-28":"弊笱在梁，魴逸不禁。漁父勞苦，藏空乾口。",
"33-29":"盛中後跌，衰老復掇。盈滿減毀，疾羸肥腯。鄭昭失國，重耳與立。",
"33-30":"折亡破甕，使我困貧。與母生分，別離異門。",
"33-31":"野有積𢈔，穡人駕取。不逢虎狼，暮歸其宇。",
"33-32":"襁褓孩呱，冠帶成家。出門如賓，父母何憂。",
"33-33":"三塗五岳，陽城太室。神明所保，獨無兵革。",
"33-34":"陳力就列，官職並廢。手不勝盆，失其寵門。",
"33-35":"積雪大寒，萬物不生。陰制庶士，時本冬貧。",
"33-36":"龍鬥時門，失理傷賢。內畔生賊，自為心疾。",
"33-37":"狗畏狼虎，依人為輔。三夫執㦸，伏不敢趨。身安無咎。",
"33-38":"南山高罡，回隤難登。道里遼遠，行者無功。憂不成凶，惡亦消去。",
"33-39":"逢時陽遂，富且尊貴。",
"33-40":"求我所欲，得其利福，終身不辱。盈盛之門，高屋先覆，君失邦國。",
"33-41":"安坐至暮，禍災不到。利詰姦妖，罪人弗赦。",
"33-42":"膠車駕東，與雨相逢。五楘解墮，頓輈獨宿。憂為身禍。",
"33-43":"擇日高飛，遂至東齊。見孔聖師，使我和諧。",
"33-44":"陳媯敬仲，兆興齊姜。乃適營丘，八世大昌。",
"33-45":"缺埒無墠，難從東西。毀破我盆，泛棄酒食。",
"33-46":"中夜狗吠，盜在廬外。神光祐助，消散解去。",
"33-47":"雷車不藏，隱隱西行。霖雨三旬，流為河江，使國憂凶。",
"33-48":"老河虛空，舊井無魚。利得不饒，避患東鄰。禍入我門，使我悔存。",
"33-49":"福德之士，懽悅日喜。夷吾相國，三歸為臣，賞流子孫。",
"33-50":"清人高子，久屯外野，逍遙不歸，思我慈母。",
"33-51":"騘騁黑髦，東歸高鄉。白虎推輪，倉龍把衡。朱雀道引，虛烏載遊。逐扣天門，入見眞君，馬安人全。",
"33-52":"路多枳棘，步刺我足。不利旅客，為心作毒。",
"33-53":"端坐生患，憂來入門，使我不安。",
"33-54":"小陬之市，利不足喜。二世積仁，蒙其祖先。匪躬之言，狂悖為患。",
"33-55":"登高望時，見樂無憂。求利南國，與寶相得。",
"33-56":"疏足息肩，有所忌難。金城鐵郭，以銅為關。蕃屏自衛，安上無患。",
"33-57":"江有沲泥，思附君子。伯仲受歸，不我肯顧，姪娣悔恨。",
"33-58":"牙孽生達，陽倡於外。左手執籥，公言錫爵。",
"33-59":"雲夢𫟍囿，萬物蕃熾。犀象瑇瑁，荊人以富。",
"33-60":"渠戎萬里，晝夜愁苦。橐甲戎服，雖荷不賊。鷹鸇之殘，害不能傷。",
"33-61":"鎡基逢時，稷契皋陶。貞良願得，微子解囚。市空無虎，謾誕妄語。",
"33-62":"騎騅與蒼，南賈太行。逢駮猛虎，為所吞殤。葬於渭陽。",
"33-63":"出門東行，日利時良。步騎與駟，經歷宗邦。暮宿北燕，與樂相逢。",
"33-64":"酒為懽伯，除憂未樂。福善入門，與君相索。使我有得。",
"34-1":"金齒鐵牙，壽考宜家。年歲有儲，貪利者得，離其咎憂。",
"34-2":"家給人足，頌聲並作。四夷賓服，干戈囊閣。",
"34-3":"獼猴冠帶，盜載非位。眾犬嘈吠，狂走厥足。",
"34-4":"心患其身，不念安存。忠臣孝子，為國除患。",
"34-5":"君不明德，臣亂為惑。丞相命馬，胡亥失所。",
"34-6":"東行西窮，南北無功。張伯賣鹿，從者失羊。",
"34-7":"鹿下西山，欲歸其群。逢羿鋒箭，無於矢端。",
"34-8":"明夷兆初，三日為災。以讒後歸，名曰豎牛。剝亂叔孫，餧卒虛丘。",
"34-9":"秦失嘉居，河伯為怪。還其御璧，神怒不佑。織組無文，燒香不芬。",
"34-10":"德至之君，禍不過鄰。使我世存，身無患災。",
"34-11":"眾惡之堂，相聚為殃。出毒良人，使道不通。",
"34-12":"三痴六狂，欲之平鄉。迷惑失道，不知昏明。",
"34-13":"老弱無子，不能自理。郭氏雖憂，終不離咎。管子治國，侯伯之服。乘輿八百，尊祀祖德。",
"34-14":"褒后生蛇，經老皆微。追跌衰光，酒滅黃離。",
"34-15":"騘驪黑髦，東歸高鄉。白虎推輪，蒼龍把衡。逐至夷傷，不離咎殃。",
"34-16":"信譎龍且，塞水上流。半涉決囊，楚師覆凶。",
"34-17":"有莘季女，為王妃后。貴夫壽子，毋字四海。",
"34-18":"德被八表，蠻夷率服。蝥賊不作，道無苛慝。",
"34-19":"載日精光，驂駕六龍。祿命徹天，封為燕王。",
"34-20":"纓急縮頸，行不得前。五石示象，襄霸弗成。",
"34-21":"蛇失其公，載麻當喪。哀悲哭泣，送死離鄉。",
"34-22":"回隤不安，兵革為患。掠我妻子，客屬飢寒。",
"34-23":"乘風雨橋，與鳥飛俱。一舉千里，見吾愛母。",
"34-24":"雷霆所擊，誅者五逆。磨滅無跡，有懼方息。",
"34-25":"張氏揖酒，請謁左右。王叔枯槁，獨不蒙所。",
"34-26":"坐爭立訟，紛紛匈匈。卒成禍亂，災及家公。",
"34-27":"霜降閉戶，蟄蟲隱處。不見日月，與死為伍。",
"34-28":"鼠聚生怪，為我患悔。道絕不通，商旅失意。",
"34-29":"寒暑不當，軌度失常。一前一後，年歲鮮有。",
"34-30":"築室水上，危於一齒。丑寅不徙，辰卯有咎。",
"34-31":"畜雞養狗，長息有儲。耕田得黍，王毋喜舞。",
"34-32":"東壁餘光，數闇不明。主毋嫉妒，亂我業事。東壁星名。",
"34-33":"剛柔相傷，火爛銷金。鵰鷹制兔，伐楚有功。",
"34-34":"左有噬羆，右有嚙虎。前觸鐵矛，後躓強弩，無可抵者。",
"34-35":"鄭國讒多，數被楚憂。商人愁苦，民困無聊。",
"34-36":"弓矢其張，把彈弦折。丸發不至，道過害患。",
"34-37":"舉觴飲酒，未得至口。側弁醉酗，拔劍相怒，武侯作悔。",
"34-38":"蒼鷹群行，相得旅前。王孫申公，驚奪我雄。北天門開，神火飛災。如不敬信，事入塵埃。",
"34-39":"穿空相宜，利倍我北。循邪詭道，逃不可得。南北望邑，遂歸入室。",
"34-40":"壽如松喬，與日月俱。常安康樂，不離禍憂。",
"34-41":"出門望東，伯仲不來。疾病為患，使母憂歎。",
"34-42":"大姒之孫，周文九子。咸遂受成，寵貴富有。",
"34-43":"桃李華實，累累日息。長大成熟，甘美可食。為我利福。",
"34-44":"昏禮不明，男女失常。行露反言，出爭我訟。",
"34-45":"空穿漏弊，破桴殘缺。陰弗能完，瓦碎不全。",
"34-46":"數窮廓落，困於歷室。往登玉堂，與堯侑食。",
"34-47":"道濕為坑，輪陷躓僵。南國作諱，使我多畏。",
"34-48":"鰥寡孤獨，福祿苦薄。入室無妻，武子哀悲。",
"34-49":"舉被覆目，不見日月。衣衾杖机，就其夜室。",
"34-50":"長尾踒蛇，畫地為河，深不可涉。絕無以北，惆然憤息。",
"34-51":"日風文翰，大舉就溫。昧過我邑，羿無所得。",
"34-52":"出入節時，南北無憂。行者亟至，在外歸來。",
"34-53":"陽氏狂惑，季孫亂憒。陪臣執政，平子拘折，我心不快。",
"34-54":"五烏六鴟，相對蹲跂。禮譲不興，虞芮爭訟。",
"34-55":"顧念所生，隔在東平。遭離滿沸，河川決潰。幸得無恙，復歸相室。",
"34-56":"追獵東走，兔逃我後。吾銳不利，獨空無有。",
"34-57":"犬吠非主，上下膠擾。敵人襲戰，閔王逃走。",
"34-58":"嵩高岱宗，峻直且神。觸石膚寸，千里蒙恩。",
"34-59":"陳魚觀社，佷荒踰矩。為民開緒，亡其祖考。",
"34-60":"四壁無戶，三步一止。東西南北，利不可得。",
"34-61":"求君衣裳，情不可當。觸諱西行，為伯生殃。君之上歡，得其安存。",
"34-62":"春鴻飛東，以馬𧵍金，利可得深。",
"34-63":"禾生蟲蠹，還自克賊，使我無得。",
"34-64":"桀亂無道，民散不聚。倍室棄家，逃遁出走。",
"35-1":"一衣三冠，無所加元。衣服不來，為我災患。",
"35-2":"百足俱行，相輔為強。三聖翼事，王室寵光。",
"35-3":"魚蛇之怪，大人憂懼。梁君好城，失其安居。",
"35-4":"少無強輔，長不見毋。勞心遠思，自傷憂苦。",
"35-5":"前涉溽暑，解不可取。離河三里，敗我利市。老牛病馬，去之何悔。",
"35-6":"君明有德，登天大祿。布政施惠，以感恩福。中子南遊，翱翔未復。",
"35-7":"嘵然唯諾，敬上尊客。執恭除患，禦侮致福。",
"35-8":"黍稷禾稻，垂秀方造。中旱不雨，傷風病藳。",
"35-9":"三羸六罷，不能越跪。東賈失馬，往反勞苦。",
"35-10":"𠋣立相望，引衣欲莊。陰雲蔽日，暴雨所集。降我歡惠，使道不通。",
"35-11":"高脚疾步，受肩善趨。日走千里，賈市有得。",
"35-12":"北風寒涼，雨雪益冰。憂思不樂，哀悲傷心。",
"35-13":"貞鳥鳴鳩，執一無尤。寢門治理，君子悅喜。",
"35-14":"蓼蕭露瀼，君子龍光。鳴鸞雍和，福祿來同。",
"35-15":"南行求福，與喜相得。封受上賞，鼎足輔國。",
"35-16":"桑華腐蠹，衣弊如絡。女功不成，絲布為玉。",
"35-17":"左服易右，王良心懽。嘉利從已。",
"35-18":"壽考不忘，駕騂東行。之適陳宋，南賈楚荊。得利息長，旅自多罷。畏晝喜夜。",
"35-19":"羔羊皮弁，君子朝服。輔政扶德，以合萬福。",
"35-20":"鸇鳩徙巢，西至平州。遭逢雷電，破我葦廬。室家飢寒，思吾故初。",
"35-21":"大尾小頭，重不可搖。上弱下強，陰制其雄。",
"35-22":"疏足息肩，有所忌難。金城銅郭，以鐵為關。蕃屏自衛，安止無患。",
"35-23":"天命玄鳥，下生大商。造定四表，享國久長。",
"35-24":"賊斂重數，政為民賊。杼軸空虛，家去其室。",
"35-25":"陰陽隔塞，許嫁不荅。宛丘新臺，悔往歎息。",
"35-26":"顧望登虛，意常欲逃。賈辛醜惡，妻不安夫。",
"35-27":"踧行竊視，有所畏避。蔽目伏藏，以夜為利。",
"35-28":"信敏恭謙，敬鬼尊神。五岳四瀆，克猒帝心，受福宜年。",
"35-29":"懸懸南海，去家萬里。飛兔騕𮕹，一日見母，除我憂悔。",
"35-30":"雖汙不辱，因何洗足。童子褰衣，五年平復。",
"35-31":"宮城立見，衣就袂裙。恭謙自衛，終無禍尤。",
"35-32":"弊笱在梁，不能得魚。望貧千里，所至空虛。",
"35-33":"千里騂駒，為王服車。嘉其驪榮，君子有成。",
"35-34":"鼎足承德，嘉謀生福。為王開庭，得心所欲。",
"35-35":"銷鋒鑄耜，休牛放馬。甲兵解散，夫婦相保。",
"35-36":"右手無合，獨折左指。禹湯失佐，事功弗立。",
"35-37":"憂凶憎累，患近不解。心意西東，事無成功。",
"35-38":"東行食榆，困於枯株。失妻無家，志窮為憂。",
"35-39":"五經六紀，仁道所在。正月繁霜，獨不離咎。",
"35-40":"懈緩不前，慆怠失便。二至之戎，家無禍凶。刻木象形，聞言不信。",
"35-41":"仁愛篤厚，不以所忿。害其所子，從我舊都，日益富有。",
"35-42":"缺破不成，胎卵未生，弗見兆形。",
"35-43":"摧角不傷，雖折復長。秉德無騫，老賴榮光。",
"35-44":"乘桴渡海，免脫厄中，雖困無咎。",
"35-45":"孔鸞鴛鶵，鵁鵝鵜鶘。翱翔紫淵，嘉木之圃，君子以娛。",
"35-46":"眾來得願，甘露溫潤。樂易君子，不逢禍亂。",
"35-47":"東騎墮落，千里獨宿。高岸為谷，陽失其室。",
"35-48":"八才既登，以成善功。厖降庭堅，國無憂凶。",
"35-49":"邯鄲反言，父兄生患。竟涉憂恨，卒死不還。",
"35-50":"五銳鐵頤，倉庫空虛。賈市無盈，與利為仇。",
"35-51":"白鳥銜餌，鳴呼其子。施报張翅，來從其母。",
"35-52":"學靈三年，聖且明神。先見善祥，嘉吉福慶。餌吉知來，告我無咎。",
"35-53":"雲孽烝起，失其道理。傷害年榖，神君之精。",
"35-54":"春耕有息，秋入利福，獻𧲨大𤡆，以樂成功。",
"35-55":"羸豕躑躅，虎入都邑。",
"35-56":"東行西維，南北善迷。逐旅失群，亡我𥜗衣。",
"35-57":"居室之倫，夫婦和親。小人乘車，石果失豢。",
"35-58":"東方孟春，乘冰戴盆。懼危不安，終身所歡。",
"35-59":"風吹塵起，十里無所。南國年傷，不可安處。",
"35-60":"重載傷車，婦失無夫。三十不室，獨坐空廬。",
"35-61":"販牛羸馬，與利為市，不我嘉喜。",
"35-62":"日出阜東，山蔽其明。章父薦屨，箕子佯狂。",
"35-63":"出入門所，與道開通。杞梁之信，不失日中。少季渡江，來歸其邦，疾病危亡。",
"35-64":"邑兵衛師，如轉蓬時，居之危凶。",
"36-1":"踐履寒冰，十步九尋。雖有苦痛，不為憂病。",
"36-2":"太公辟紂，七十隱處。卒遭聖文，為王室輔。",
"36-3":"日月之塗，所行必到，無有患悔。",
"36-4":"諷德頌功，美周盛隆。旦輔成周，光濟沖人。",
"36-5":"童女無室，未有配合，空坐獨宿。",
"36-6":"穿鼻繫株，為虎所拘。王母祝祠，禍不成災。遂然脫來。",
"36-7":"黃帝神明，八子聖聰。佚受大福，天下平康。",
"36-8":"深谷為陵，衰者復興。亂傾之國，民得安息。中婦病困，遂人冥室。",
"36-9":"道遠遼絕，路宿多悔。頑囂相聚，生我畏惡。",
"36-10":"旦樹菽豆，暮成藿羹。心之所樂，志快心懽。",
"36-11":"切切之患，凶憂不存。虎不敢齚，利當我身。",
"36-12":"王伯遠宿，長婦在室。棄危恃食，所求不得。",
"36-13":"寒燠失時，陽旱為災，雖耗無憂。",
"36-14":"雖窮復通，履危不凶，保其明功。",
"36-15":"狼虎所宅，不可以居，為我患憂。",
"36-16":"喋囁處曜，昧冥相傳。多言少實，語無成事。",
"36-17":"履冰蹈凌，雖困不窮。播雀登巖，卒無憂凶。",
"36-18":"文文墨墨，憂禍相雜。南北失志，東西不得。",
"36-19":"爭訟不巳，更相談訽。張季弱日，被𩬊北走。",
"36-20":"德積逢時，宜其美才。相明輔聖，拜受福休。長女不嫁，後為大悔。",
"36-21":"江水沲汜，思附君子。伯仲爰歸，不我肯顧，姪娣恨悔。",
"36-22":"光禮春成，陳寶雞鳴。陽明失道，不能自守，消亡為咎。",
"36-23":"驚虎無患，虞為我言，賴得以安。",
"36-24":"偽言妄語，轉相詿誤。不知狼處。",
"36-25":"履悖自敵，凶憂來到，痛不能笑。",
"36-26":"牽尾不前，逆理失臣，惠朔以奔。",
"36-27":"三狸搏鼠，遮遏前後。死於環城，不得脫走。",
"36-28":"言笑未卒，憂來暴卒。身墨丹索，檻囚裝束。",
"36-29":"陰積不已，雲作淫雨。傷害平陸，民無室屋。",
"36-30":"山林麓藪，非人所處。鳥獸無禮，使我心苦。",
"36-31":"新作初陵，踰蹈難登。三駒推車，跌頓傷頤。",
"36-32":"魂微惙惙，行纊聽絕。曠然大通，復更生活。",
"36-33":"欒子作殃，伯氏誅傷。州犂奔荊，去其邑鄉。",
"36-34":"高明大彤，造惡作凶。無所能成，還自滅身。",
"36-35":"陳辭達城，使安不傾。增榮益譽，以成功名。",
"36-36":"他山之儲，與璆為仇。來攻吾城，傷我肌膚，邦家騷憂。",
"36-37":"三杞無棗，家無積莠。使鳩求婦，頑不我許。",
"36-38":"慎禍重病，顏子為友。乃能安存，牢戶繫羊，乃能受慶。",
"36-39":"鹿得美草，鳴呼其友。九族和穆，不憂飢乏。",
"36-40":"亡玉失鹿，不知所伏。利以避危，全我生福。甘雨時降，年歲有得。",
"36-41":"逢時得當，身受福慶。",
"36-42":"鵠思其雄，欲隨鳳東。順理羽翼，出次須日。中留北邑，復反其室。",
"36-43":"環堵𠋣鋤，升升屬口。貧賤所處，心寒昨苦。",
"36-44":"孤獨特處，莫依為輔，心勞志苦。",
"36-45":"稷為堯使，西見王母。拜請百福，賜我喜子，長樂富有。",
"36-46":"鳴條之郊，北奔犬胡。左祍為長，國號匈奴。王君旄頭，立尊單于。",
"36-47":"絕而復通，雖達不窮。終得其願，姬姜相從。",
"36-48":"陽并悖狂，拔劍自傷，為身坐殃。",
"36-49":"方圓不同，剛柔異鄉。掘井得石，勞而無功。",
"36-50":"乘風雨會，與飛鳥俱。動舉千里，見我愛母。",
"36-51":"三塗五岳，陽城太室。神明所扶，獨無兵革。",
"36-52":"鴞鴟取婦，深目𥥆身。折腰不媚，與伯相背。",
"36-53":"轉行軌軌，行近不遠。旦夕入門，與君笑言。",
"36-54":"求利難國，逃去我北。復歸其城，不為吾賊。",
"36-55":"日月之途，所行必到。無凶無咎，安寧不殆。",
"36-56":"管仲遇桓，得其願歡。膠目啟牢，振冠無憂。笑戲不止，空言妄行。",
"36-57":"出入蹈踐，動順天時。俯仰有節，禍災不來。",
"36-58":"內崩傷中，上亂無恒。雖有美粟，我不得食。",
"36-59":"逐禍除患，道德神仙。遏惡萬里，福常在前，身樂以安。",
"36-60":"牛驚馬走，上下渾擾。鼔音不絕，頃公奔敗。",
"36-61":"西上九阪，往來留連。止須時日，虛與有得。",
"36-62":"虎怒捕羊，猬不能攘。",
"36-63":"踴泉滈滈，南流不絕。卒為江海，壞敗邑里。家無所處，將帥襲戰，獲其醜虜。",
"36-64":"桃弓葦㦸，除殘去惡，敵人執服。",
"37-1":"千歲槐根，身多斧瘢。傷癕𢷬理，枝葉不出。",
"37-2":"喭喭諤諤，虎豹相齚。懼畏悚息，終無難惡。",
"37-3":"娶於姜呂，駕迎新婦。少齊在門，夫子懽喜。",
"37-4":"膏壤肥澤，民人孔樂。宜利居止，長安富有。",
"37-5":"生有聖德，上配大極。皇靈建中，授我以福。",
"37-6":"耄老蒙鈍，不見東西。少者弗慕，君不與謀。懸輿致仕，退歸里居。",
"37-7":"三狂北行，道逢大狼。暮宿患澤，為禍堪傷。",
"37-8":"更且初歲，振除禍敗。新衣元服，拜受利福。",
"37-9":"杲杲白日，為月所食。損上毀下，鄭昭出走。",
"37-10":"君子失意，小人得志。亂擾並作，姦邪充塞。雖有百堯，顛不可救。",
"37-11":"仁德履洽，恩及異域。澤被殊方，福慶隱伏。作蠶不織，寒無所得。",
"37-12":"東求金玉，反得弊石。名曰無宜，字曰醜惡，眾所賤薄。",
"37-13":"擊鼓合戰，士怯叛亡。威令不行，敗我成功。",
"37-14":"仲春孟夏，和氣所舍。生我嘉福，國無殘賊。",
"37-15":"尹氏伯奇，父子生離。無罪被辜，長舌為災。",
"37-16":"三榖不熟，民苦困急。駕之新邑，嘉樂有德。",
"37-17":"登虛望貧，暮食無餐。長子南戌，與我生分。",
"37-18":"東市齊魯，南賈荊楚。羽毛齒革，為吾利寶。",
"37-19":"節情省欲，賊斂有度。家給人足，公劉以富。",
"37-20":"恭寬信敏，功加四海。辟去不祥，喜來從母。",
"37-21":"張狂妄作，與惡相逢。不得所欲，生我獨凶。",
"37-22":"畫龍頭頸，文章不成。甘言美語，詭辭無名。",
"37-23":"騎龍乘風，上見神公。彭祖受刺，王喬讃通。巫咸就位，拜壽無窮。",
"37-24":"溫仁君子，忠孝所在。八國為鄰，禍災不處。",
"37-25":"威權分離，烏夜徘徊。群蔽目光，大人誅傷。",
"37-26":"學靈三年，聖且明神。先知善祥，吉喜福慶。神烏來見，告我無憂。",
"37-27":"東山家辭，處婦思夫。伊威盈室，長股羸戶。歎我君子，役日未已。",
"37-28":"張頷開口，舌直距齒。然諾不行，政亂無緒。",
"37-29":"吹角高邦，有夫失羊，眾民驚惶。警慎避咎，勑不行殃。",
"37-30":"南行出城，世得福祉。王姬歸齊，賴其所欲。",
"37-31":"心狂老悖，視聽聳類。政令無常，下民多孽。",
"37-32":"安上宜官，一日九遷。踰群超等，牧養恆山。",
"37-33":"東鄰嫁女，為王妃后。莊公築館，以尊王母。歸于京師，季姜悅喜。",
"37-34":"六甲無子，已喪其戊。五丁不親，庚失曾孫，癸走出門。",
"37-35":"陰霧不清，濁政亂民。孟秋季夏，水壞我居。",
"37-36":"騎豚逐羊，不見所望。經涉虎廬，亡身失羔。",
"37-37":"天命赤烏，與兵徼期。征伐無道，誅其君傲，居止何憂。",
"37-38":"安床厚褥，不歸久宿。棄我喜讌，困於南國。投杼之憂，弗成禍災。",
"37-39":"五方四維，平安不危。利以居止，保有玉女。",
"37-40":"西賈巴蜀，寒雪至轂。欲前不得，復反其室。",
"37-41":"剛柔相呼，二姓為家。霜降既同，惠我以仁。",
"37-42":"天馬五道，炎火分處。往來上下。住又駒亡，衣柔巾麻，相隨哭歌，凶惡如何。",
"37-43":"出門懷憂，東上禍丘。與凶相遇，自為災患。",
"37-44":"西行求玉，冀得隨璞。反見凶惡，使我驚惑。",
"37-45":"出入無妄，動作失利。銜憂懷禍，使我多悴。",
"37-46":"高樓無柱，顛僵不久。紂失三仁，身死牧野。",
"37-47":"避禍逃殃，身外不傷。高貴疾顛，華落墮凶。",
"37-48":"張牙反目，怒齚作怒。狂馬燒犬，道驚傷軫。",
"37-49":"泉涸龍憂，箕子為奴。干叔隕命，殷破其家。",
"37-50":"向食飲酒，嘉賓聚會。牂羊大豬，君子饒有。",
"37-51":"黃牛騂犢，東行折角。冀得百牂，反亡我囊。",
"37-52":"路多枳棘，步刺我足。不利旅客，為心作毒。",
"37-53":"執斧破薪，使媒求婦。和合二姓，親御斯酒。居比鄰里，姑公悅喜。",
"37-54":"駕車出門，順時宜西。福祐我身，安寧無患。",
"37-55":"日新東從，魁杓為禍。僕臺為秦，使我久坐。",
"37-56":"山陵丘暮，魂魄室屋。精光竭盡，長臥無覺。",
"37-57":"孩子貪餌，為利所說。探把釜甑，爛其臂手。",
"37-58":"何材待時，閉戶獨愁。丘蚓冬行，解我無憂。桑蚕不得，女功弗成。",
"37-59":"解商驚惶，散我衣裝，君不安邦。",
"37-60":"害政養賊，背主入愆。跋行不安，國危為患。",
"37-61":"禍走患伏，喜為我福。凶惡消去，災害不作。",
"37-62":"老馬無駒，病雞不鶵。三雌獨宿，利在山北。",
"37-63":"播天舞，地嘵亂。神所居，樂無咎。",
"37-64":"異國殊俗，情不相得。金木為仇，酉賊檀榖。",
"38-1":"被服文衣，遊觀酒池。上堂見觴，喜為吾兄，使我憂亡。",
"38-2":"邑姜叔子，天文在手。實沈參虛，封為晉侯。",
"38-3":"改柯易葉，飯溫不食。豪雄爭強，先者受福。",
"38-4":"馨香陟降，明德上登。社神祐顧，命予大鄰。",
"38-5":"老狼白驢，長尾大狐。前顛郤躓，進退遇祟。",
"38-6":"山沒丘浮，陸為水魚，鷰雀無廬。",
"38-7":"懿公淺愚，不深受謀。無援失國，為狄所賊。",
"38-8":"鼎煬其耳，熱不可舉。大塗塞壅，旅人心苦。",
"38-9":"凶聲醜言，惡不可聞。君子舍之，往恨我心。",
"38-10":"昧暮乘車，履危陷溝。亡失群物，摧折兩軸。",
"38-11":"南有嘉魚，駕黃取鮮。魴鱮詡詡，利來無憂。",
"38-12":"隔在九山，往來勞難。心結不通，失其所懽。",
"38-13":"下流難居，狂夫多罷。貞良溫柔，年歲不富。",
"38-14":"狐狸雉兔，畏人逃去。分走竄匿，不知所處。",
"38-15":"異體殊俗，各有所屬。西鄰孤嫗，欲寄我室。主母罵晉，終不可得。",
"38-16":"怒非怨妒，貪得腐鼠。而呼鵲鸇，自令失餌，致被困患。",
"38-17":"五心六意，岐道多怪。非君本志，生我恨悔。",
"38-18":"三班六黑，同室共食。日長月息，我家有德。",
"38-19":"方船備水，旁河燃火，終身無禍。",
"38-20":"翳屏獨語，不聞朝市。以利居服，兔跛後聞。",
"38-21":"以處不安，從反觸患。",
"38-22":"剠刖髠劓，人所殘棄。批捍之言，我心不快。",
"38-23":"皋田禾黍，搥壤麻阜。衣食我躬，室家饒有。",
"38-24":"兩目失明，日奪無光。脛足跛踦，不可以行，頓於丘傍。",
"38-25":"金城朔方，外國多羊。履霜不時，去復為憂。",
"38-26":"匿病不醫，亂政傷災。紂作淫虐，商破其墟。",
"38-27":"鬼泣哭枉，悲傷無後。甲子昧爽，殷人絕祀。",
"38-28":"焱風卒起，車馳袍褐，棄古追亡，失其和節，心憂惙惙。",
"38-29":"耋老不明，聞善不從。自令顛沛，敗為咎殃。",
"38-30":"隨風騎龍，與利相逢。田獲三狐，商伯有功。衝衝之邑，長安無他。",
"38-31":"三牛五牂，重明作福。使我有得，疾人官獄。憂在心腹。",
"38-32":"孟巳乙丑，哀呼尼父。明德訖終，亂害滋起。",
"38-33":"華燈百枝，消闇衰微。精光訖盡，奄如灰縻。",
"38-34":"鷹飛雉退，兔伏不起。弧張狼鳴，野雞飛驚。",
"38-35":"鬥戰天門，身有何患。室家具在，不失其歡。",
"38-36":"東家殺牛，行逆腥臊，神背西顧，命衰絕周。毫社災燒，宋人夷誅。",
"38-37":"陰陽辨舒，二姓相合。婚姻孔云，生我利福。",
"38-38":"倉盈𢈔億，宜稼𥞫稷。年歲有息。",
"38-39":"東入海口，循流北走。一高一下，五邑無主。十日六夜，死於水涘。",
"38-40":"孤竹之墟，失婦無夫。傷於蒺藜，不見其妻。東郭棠姜，武氏以亡。",
"38-41":"天戶東墟，盡既為災。跰棘黯聾，秦伯受殃。",
"38-42":"賴先休光，受福之祉。雖遭亂潰，獨不危殆。",
"38-43":"折箬蔽目，不見稚叔。三足孤烏，遠去家室。",
"38-44":"二人同室，兄弟合食。和樂相好，各得所敬。",
"38-45":"繼體守蕃，縱欲廢賢。君臣淫遊，夏氏失身。側室之門，福祿來存。",
"38-46":"老狐屈尾，東西為鬼。病我長女，坐涕詘指。或西或東，大華易誘。",
"38-47":"大樹之子，百條共母。當夏六月，枝葉盛茂。鸞鳳以庇，邵伯避暑。稚稚印甚，各得其所。",
"38-48":"井堙木刋，國多暴殘。秦王失戍，壞其太壇。",
"38-49":"駕黃買蒼，與利相迎，心獲所守，不累弟兄。",
"38-50":"𢈔億倉盈，年歲安寧。稼穡熟成。",
"38-51":"人生馬淵，壽老且神。飛騰上天，舍宿軒轅，居常樂安。",
"38-52":"思顧所之，乃令逢時。洗我故憂，拜我歡來。",
"38-53":"魁罡所當，初為敗殃。君子留連，困於水漿。求金東山，利在代鄉。賈市有息，子載母行。",
"38-54":"鉛刀攻玉，無不鑽鑿。龍體其舉，魯班為輔。三仁翼事，所求必喜。",
"38-55":"喜來如雲，舉家蒙歡。眾才君子，駕福盈門。",
"38-56":"響像無形，骨體不成。微行衰索，消滅無名。",
"38-57":"積水不溫，北陸苦寒。露宿多風，君子傷心。",
"38-58":"黃馬綠車，駕之大都。讃達才能，使我無憂。",
"38-59":"從風放火，艾芝俱死。三害集聚，十子患傷。",
"38-60":"一身三手，無益於輔。兩足共節，不能克敏。",
"38-61":"南向一室，風雨並入。塵埃積濕，主母盲痺。徧枯心疾，亂我家資。",
"38-62":"採薇出車，魚麗思初。上下促急，君子懷憂。",
"38-63":"先易後否，告我利市。騷蘇自苦，思吾故止。",
"38-64":"生宜地乳，上皇大喜。降我祉福，貴壽無極。",
"39-1":"叔盻拘冤，祁子自邑。乘遽解患，羊舌免脫，賴得全生。",
"39-2":"兔聚東郭，眾犬俱獵。圍缺不成，無所能獲。",
"39-3":"作室山根，人以為安。一旦崩頹，敗我盤餐。",
"39-4":"疾風塵起，亂擾崩始。強大并小，先否後喜。",
"39-5":"潔齊浴沐，思明君德。哀公怯弱，風氏復比。",
"39-6":"土瘠瘦薄，培塿無柏，使我不樂。",
"39-7":"褰衣涉河，水深漬罷。賴幸舟子，濟脫無他。",
"39-8":"送我季女，至于蕩道。齊子旦夕，久留連處。",
"39-9":"三孫六子，安無所苦。中歲發殆，亡我所使。",
"39-10":"揚風偃草，塵埃俱起。清濁溷散，忠直隱處。",
"39-11":"歷險登危，道遠勞罷。玄豕自歸，困涉大波。",
"39-12":"六藝之門，仁義俱存。鎡基逢時，堯舜為君。傷寒熱溫，下室黃泉。",
"39-13":"被服文衣，遊觀酒池。上堂見觴，喜為吾兄，使我憂亡。",
"39-14":"生時不利夭，命災至制。於斧瘢，晝夜苦勤。",
"39-15":"天門開闢，牢戶寥廓。桎梏解脫，拘囚縱釋。",
"39-16":"川淵難遊，水為我憂。多言少實，命鹿為駒。建德開基，君子逢時，利以仲疑。",
"39-17":"鄉歲逢時，與生為期。枝葉盛茂，君子無憂。",
"39-18":"六鶂退飛，為衰敗祥。陳師合戰，左股夷傷。遂崩不起，霸功不成。",
"39-19":"雷君出裝，隱隱西行。霖雨不止，流為巨江。南國以傷。",
"39-20":"牙孽生齒，室蟠啟戶。幽人利貞，鼓翼起舞。",
"39-21":"火起上門，不為我殘。跳脫東西，獨得生完。不利出鄰，病疾憂患。",
"39-22":"舉事無成，不利出征。言不可用，眾莫能平。",
"39-23":"老狼白驢，長尾大狐。前顛郤躓，進退遇祟。",
"39-24":"日入道極，勞者休息。班馬還師，復我燕室。",
"39-25":"林麓山藪，非人所處。鳥獸無禮，使我心苦。",
"39-26":"蓄利積福，日新其德。高氏飲食，憂不為患。",
"39-27":"張羅百目，鳥不得北。縮頸挂翼，困於窘國。君子治德，獲譽受福。",
"39-28":"伯虎仲熊，德義淵弘。使布五教，陰陽順序。",
"39-29":"跛踦相隨，日暮牛罷。凌遲後旅，失利亡雌。",
"39-30":"嬴氏違良，使孟尋兵。師老不已，敗於齊鄉。",
"39-31":"日月並居，常闇且微。高山崩巔，丘陵為谿。",
"39-32":"鳥鵲食榖，張口受哺。蒙被恩德，長大成就。柔順利貞，君臣合好。",
"39-33":"雖躓復起，不毀牙齒。克免平復，憂除無疾。",
"39-34":"草木黃落，歲暮無室。虐政為賊，大人失福。",
"39-35":"避凶東走，反入禍口。制於牙爪，骨為灰土。",
"39-36":"欲飛不能，志苦心勞，福不我求。",
"39-37":"羔裘豹祛，東與福遇。駕迎吾兄，送我驪黃。",
"39-38":"東耕破犁，西失良妻。菑害不避，家貧無資。",
"39-39":"同載共輿，中道別去。喪我元夫，獨與孤居。",
"39-40":"魚陸失所，鳧鼃困苦。澤無雚蒲，晉國以虛。",
"39-41":"脫兔無蹄，三步五疲。南行不進，後市勞苦。",
"39-42":"脫足無蹄，三步五罷。南行不進，後市身苦。",
"39-43":"白日揚光，火為正王。消金厭兵，雷車避藏。陰雨不行，民安其鄉。",
"39-44":"放銜垂轡，奔馬不制。棄法作姦，君失其位。",
"39-45":"司命下遊，喜解我憂。皇母緩帶，嬰子笑喜。",
"39-46":"黃帝出遊，駕龍乘馬。東上大山，南過齊魯，邦國咸喜。",
"39-47":"既往不說，憂來禍結。北戶為患，無所申雪。",
"39-48":"荷蕢隱名，以避亂傾。終身不仕，遂其潔清。",
"39-49":"折挺舂稷，君不得食。頭痒搔跟，無益於疾。",
"39-50":"植根不固，華葉落去，便為枯樹。",
"39-51":"凶門生患，牢戶多冤。沙池禿齒，使叔困貧。",
"39-52":"登山履谷，與虎相觸。猬為功曹，班叔奔北，脫之喜國。",
"39-53":"麟鳳所翔，國無咎殃。賈市十倍，復歸惠里。",
"39-54":"路險道難，水遏我前。進往不利，回車復還。",
"39-55":"延頸望邑，恩歸其室。臺樹不成，未得安息。",
"39-56":"蒙生株瞿，棘挂我須。小人妒嫉，使恩不遂。",
"39-57":"南至隱域，深潛處匿。聰明閉塞，與死為伍。",
"39-58":"機餌設張，司暴子良。范叔不廉，凶害及身。",
"39-59":"從騎出門，遊戲空城。阪高不進，利無所得。",
"39-60":"西國強梁，為虎作狼。東吞楚齊，并有其王。",
"39-61":"登山伐輻，虎在我側。王孫無懼，仁見不賊。",
"39-62":"六月暌暌，各欲有望。後來未壯，俟時旦明。",
"39-63":"道涉多阪，牛馬蜿蟺。車不麗載，請求不得。",
"39-64":"一口三舌，相妨無益。群羊百牂，不為威強。亡馬失駒，家耗於財。",
"40-1":"大都之居，無物不具。抱布貿絲，所求必得。",
"40-2":"膠著木連，不出牢関，家室相安。",
"40-3":"孟伯食長，懼其畏王。賴四蒙五，抱福歸房。",
"40-4":"防輿疲駟，不任銜轡。君子服之，談何容易。",
"40-5":"許嫁既婚，利福在身。適惠生桓，為我魯君。",
"40-6":"入門大喜，上堂見母。妻子俱在，兄弟饒友。",
"40-7":"推車上山，力不能任。顛蹶蹉跌，傷我中心。",
"40-8":"鴈飛退去，不食其雛。禽尚如此，何況人與。",
"40-9":"福棄我走，利不可得。幽人利貞，終無怨慝。",
"40-10":"夫妻反目，不能正室。翁云于南，嫗言還北。並后匹嫡，二政亂國。",
"40-11":"陽衰伏匿，陰淫為賊。賴幸王孫，遂至喜國。",
"40-12":"入山求玉，不見和璞。終日至暮，勞無所得。",
"40-13":"鳴鸞四牡，駕出行狩。合格有獲，獻公飲酒。",
"40-14":"覆手舉牘，易為功力。月正元日，平飲致福。",
"40-15":"三火高明，雨減其光。高位疾顛，驕恣誅傷。",
"40-16":"褁糗荷糧，與利相逢。高飛有德，君大獲福。",
"40-17":"道理和得，人不相賊。君子往之，樂有利福。",
"40-18":"水土相得，萬物蕃殖。膏澤優渥，君子有德。",
"40-19":"天孫帝子，與日月處。光榮於世，福祿繁祉。",
"40-20":"陪依在位，乘非其器。折足覆餗，毀傷寶玉。",
"40-21":"鶂飛中退，舉事不遂。且守仁德，猶免失墜。",
"40-22":"經棘正冠，意盈不廉。桀紂速讒，惑佞傷賢，使國亂煩。",
"40-23":"申酉退跌，陰慝前作。柯條華枝，復泥不白。",
"40-24":"平正賤使，主服苦事。",
"40-25":"釣魴河湄，水長無涯。振手徒歸，上下昏迷，屬公孫齊。",
"40-26":"胎養萌生，始見兆形。遭逢雷電，摧角折頸，採蛇山頭，終安不傾。",
"40-27":"陽春枯槁，夏多水潦。霜雹俱擊，傷我禾黍。年歲困苦。",
"40-28":"三身六齒，痛疾不巳。齲病蠹缺，墮落其宅。",
"40-29":"失恃無友，嘉禍出走。傫如喪狗。",
"40-30":"寅重微民，歲樂年息。有國無咎，君子安喜。",
"40-31":"登几上車，駕駟南遊。合從散衡，燕秦以強。",
"40-32":"鳥集茂林，順柔利貞。心樂願得，感戴慈母。",
"40-33":"啟蟄始生，萬物美榮。祉祿未成，市賈無盈。",
"40-34":"驕胡犬形，造惡作凶。無所能成，還自滅身。",
"40-35":"異國他土，出良駿馬。去如奔蛇，害不能傷。",
"40-36":"恪敬竟職，心不作慝。君明臣忠，民賴其福。",
"40-37":"三女求夫，伺候山隅。不見復關，長思憂歎。",
"40-38":"駕福乘喜，東至嘉國。載慶南行，離我室居。",
"40-39":"四姦為殘，齊魯道難。前驅執殳，戒守無患。",
"40-40":"駕行出遊，鳥鬭車前。更相捽滅。兵寇旦來，回車亟還，可以無憂。",
"40-41":"下擾上煩，蠹蠱為患。歲飢無年。",
"40-42":"雞稚失雛，常畏狐狸。黃池要盟，越國以昌。",
"40-43":"堅冰黃鳥，終日悲號。不見白粒，但觀蓬蒿。數驚鷙鳥，孰為我憂。",
"40-44":"王統鐵頤，倉庫空虛。賈市無盈，與我為仇。",
"40-45":"竊名盜位，居非其家。霜隕不實，為陰所賊。",
"40-46":"賊仁傷德，天怒不福。斬刈宗社，失其本域。",
"40-47":"萬物初生，蟄蟲振起，益壽增福，日受其喜。",
"40-48":"和氣所在，物皆不朽。聖賢居位，國無凶咎。",
"40-49":"麟遊鳳舞，歲樂民喜。鳳舞麟遊，賢聖作儔。歲既豐稔，人何以憂。",
"40-50":"行行窘步，次宿方舍。居安不懼，姬姜何憂。",
"40-51":"水深難遊，霜寒難涉。商伯失利，旅人稽留。",
"40-52":"跛踦相隨，日暮牛罷。凌遲後旅，失利亡雌。",
"40-53":"一年九鏁，更相牽攣。案明如市，不得東西。請讞得報，日中被刑。",
"40-54":"春桃生華，季女宜家。受福多年，男為邦君。",
"40-55":"雷鼓東行，稼穡凋傷。大夫執政，君替其明。",
"40-56":"季世多憂，亂國淫遊。殃禍立至，民無以休。",
"40-57":"發輗溫湯，過角宿房。宜時布和，無所不通。布春令德，明物轉芳。",
"40-58":"水中大賈，求利食子。商人至市，空無所有。",
"40-59":"春草萌生，萬物敷榮。陰陽和調，國樂無憂。樂一和暢，何事不亭。",
"40-60":"左眇右盲，目視不明。下民多孽，君失其常。",
"40-61":"悅以內安，不利出門，憂除禍消，公孫何尤。",
"40-62":"丹書之信，言不負語。易我驎驥，君子有德。",
"40-63":"上政搔擾，螟蟲並起。害我嘉榖，年歲無稷。",
"40-64":"竿旄旌旗，執職在郊。雖有寶珠，無路致之。",
"41-1":"鯉鮒鮪蝦，𠢳福多魚。資所有無，富我邦家。",
"41-2":"景星照堂，麟游鳳翔。仁施大行，頌聲作興。征者無明，失其寵光。",
"41-3":"羊腸九縈，相推稍前。止須王孫，乃能上天。",
"41-4":"四手共身，莫適所閑。更相放接，動失事便。",
"41-5":"水流趍下，逮至東來。求我所有，買魴與鯉。",
"41-6":"春栗夏棗，少鮮希有。斗千石萬，貴不可販。",
"41-7":"旦往暮還，相祐與聚，無有凶患。",
"41-8":"大蛇當路，使季畏懼。湯火之災，切直我膚。賴其天幸，歸于生廬。",
"41-9":"從足去域，飛入陳國。有所畏避，深藏䆳匿。",
"41-10":"海為水宗，聰聖且明。百流歸德，無有叛逆。常饒優足。",
"41-11":"夏麥扶䵃，霜擊其芒。病君敗國，使年大傷。",
"41-12":"秋隼冬翔，數被嚴霜。雄父夜鳴，家憂不寧。",
"41-13":"樂仁上德，東鄰慕義，來安吾國。",
"41-14":"逐憂除殃，汙泥生梁，下田為汪。",
"41-15":"闇昧冥語，轉相迷誤。鬼魅所居，誰知臥處。",
"41-16":"南歷玉山，東入玉關，登上福堂，飲萬歲漿。",
"41-17":"比目四翼，來安我國。福善上堂，與我同床。",
"41-18":"乘牛逐驥，日暮不至。路宿多畏，亡其騂騅。",
"41-19":"元吉無咎，安寧不殆。",
"41-20":"奮翅鼓翼，翱翔外國。逍遙徙𠋣，來歸溫室。",
"41-21":"河伯娶婦，東山氏女。新婚三日，浮雲洒雨。雨我菅茅，萬家之祐。",
"41-22":"嬰兒求乳，慈母歸子。黃麑悅喜，得見甘飽。",
"41-23":"貧鬼守門，日破我盆。毀罌傷缸，空虛無子。",
"41-24":"多載重負，捐棄於野。予無稚子，但自勞苦。",
"41-25":"雄狐綏綏，登山崔嵬。昭告顯功，大福允興。",
"41-26":"嬰兒孩笑，未有所識。狄童而爭，亂我政事。",
"41-27":"十丸同投，為雉所維。獨得跳脫，完全不虧。",
"41-28":"狐濟濡尾，求橘得枳。季妣懷悔，鮑舍魚臭。",
"41-29":"跌足息肩，所忌不難。金城銅郭，以鐵為關。蕃屏周衛，安止無患。",
"41-30":"戴堯扶禹，松喬彭祖。西過王母，道里夷易，無敢難者。",
"41-31":"京𢈔積聚，黍稷以極。行者疾至，可以厭飽。",
"41-32":"良夫孔姬，脅悝登臺。樂季不扶，叔輒走逃。",
"41-33":"天之所予，福祿常在，不憂危殆。",
"41-34":"行觸天剛，馬死車傷。身無憀賴，困窮乏糧。",
"41-35":"鉛刀攻玉，堅不可得。盡我筋力，胝繭為疾。",
"41-36":"穆違百里，使孟奮武。將軍師戰，敗於殽口。",
"41-37":"有人追亡，鳥言所匿。不旅日得。",
"41-38":"府藏之富，王以賑貸。捕魚河海，苟罔多得。",
"41-39":"鴻飛遵陸，公歸不復，伯氏客宿。",
"41-40":"鳧過稻廬，甘樂廣鰍。雖驚不去，田畯懷憂。",
"41-41":"路多枳棘，步刺我足。不利孤客，為心作毒。",
"41-42":"雨師娶婦，黃巖季子。成禮既婚，相呼面南。膏潤應時，年豐大喜。",
"41-43":"畜積有餘，冀土不居。美哉輪奐，出有高車。",
"41-44":"重門擊柝，陵昧武守。雖驚不懼。重門擊柝，介士守護。終有他道，雖驚不懼。",
"41-45":"大都王市，稠人多寶。公孫宜賈，其貸萬倍。",
"41-46":"秋隼冬翔，數被嚴霜。甲兵當庭，萬物不生。雄父夜鳴，民擾以驚。",
"41-47":"招禍致凶，來螫我邦。痛在手足，不得安息。",
"41-48":"秦失其鹿，疾走先得。勇夫慕義，君子變服。",
"41-49":"山陵四塞，遏我徑路。欲前不得，復還故處。",
"41-50":"一指食肉，口無所得，舌饞於腹。",
"41-51":"晨夜驚駭，不知所止。皇母相祐，卒得安處。",
"41-52":"犲狼所言，語無成全。誤我白馬，使乾口來。",
"41-53":"呼精靈來，魄生無憂。疾病瘉瘳，解我患愁。",
"41-54":"牧羊逐兔，使魚相捕。任非其人，廢日無功。卒歲無功，不免辛苦。",
"41-55":"堂祥上樓，與福俱居。席地妃治，國安無憂。",
"41-56":"禹召諸臣，會稽南山。執玉萬國，天下康安。",
"41-57":"太姒文母，乃生聖子。昌發受命，為天下主。",
"41-58":"兩置同室，兔無誰告。與狂相觸，蒙我以惡。",
"41-59":"桃雀竊脂，巢於小枝。動搖不安，為風所吹。寒恐悚慄，常憂殆危。",
"41-60":"陽春長日，萬物華實。樂有利福。春陽成長，萬物華實。福利所鍾，忻忻過日。",
"41-61":"鄰不我顧，而望玉女。身疾瘡癩，誰肯媚者。",
"41-62":"涸旱不雨，澤竭無流。魚鱉乾口，皇天不憂。",
"41-63":"狼虎之鄉，日爭凶訟。受性貪饕，不能容縱。",
"41-64":"陰注寒疾，水離其室。舟楫大作，傷害黍稷。民飢於食，亦病心腹。",
"42-1":"下堂出門，東至九山。逢福值喜，得其安閑。",
"42-2":"城上有烏，自名破家。招呼鴆毒，為國患災。",
"42-3":"伯虎仲熊，德義淵聞。使敷五教，陰陽順序。行溢多悔，利無所得。",
"42-4":"飲酒醉酣，跳起爭鬥。手足紛拏，伯傷仲僵。東家治喪，伯仲俱損。",
"42-5":"四目相視，稍近同机。日昳之後，見吾伯姊。",
"42-6":"隨時逐便，不失利門。多獲得福，富於封君。",
"42-7":"隴西冀北，多見駿馬。去如焱颺，害不能傷。",
"42-8":"白龍黑虎，起伏俱怒。蚩尤敗走，死於魚首。",
"42-9":"鴻飛戾天，避害紫淵。雖有鋒門，不能危身。",
"42-10":"平國不君，夏氏作亂。烏號竊發，靈公隕命。",
"42-11":"江漢上游，政逆民憂。陰伐其陽，雄受其殃。",
"42-12":"東家殺牛，聞𦤀腥臊。神怒不顧，命衰絕周。亳社災燒，妄夷誅愁。",
"42-13":"西誅不服，恃彊負力。倍道趨敵，師走敗覆。",
"42-14":"一婦六夫，亂擾不治。張王季疾，莫適為公。政道壅塞，周君失邦。",
"42-15":"配合相迎，利之四鄉，昏以為期，明星煌煌。欣喜爽澤，所言得當。",
"42-16":"猿墮高木，不踒手足。握金懷王，還歸其室。",
"42-17":"卷領遁世，仁德不害。三聖欣同，周國茂興。",
"42-18":"去患脫厄，安無怵愓。上福喜堂，見我懽兄。",
"42-19":"帶季兒良，明知權兵。將師合戰，敵不能當，趙魏以強。",
"42-20":"鵠思其雄，欲隨鳳東。順理羽翼，出次須日。中留北邑，復反其室。",
"42-21":"耳如驚鹿，不能定足。室家分散，各走匿竄。",
"42-22":"甲乙丙丁，俱位我庭。三丑六子，入門見母。",
"42-23":"躡華巔觀，浮雲風雨。不博心安，匿無咎患。",
"42-24":"德施流行，利之四鄉。雨師洒道，風伯逐殃。巡狩封禪，以告成功。",
"42-25":"水流趍下，遂成東海。求我所有，買鱣與鯉。",
"42-26":"和氣相薄，膏潤津澤。生我嘉榖。",
"42-27":"憂驚以除，禍不成災，安全以來。",
"42-28":"堅冰黃鳥，常哀悲愁。不見白粒，但睹藜蒿。數驚鷙鳥，飄為我憂。",
"42-29":"翕翕䡘䡘，實墮崩巔。滅其命身。",
"42-30":"因禍致福，喜盈其室。",
"42-31":"佳居千里，不見河海，無有魚市。",
"42-32":"鹿得美草，鳴呼其友。九族和睦，不憂飢乏。",
"42-33":"出門得堂，不逢禍殃。入戶自若，不見矛㦸。",
"42-34":"罍尊重席，命我嘉客。福祐久長，不見禍殃。",
"42-35":"鳴鴻俱飛，北就魚池。鱣鮪鰋鯉，多饒所有。一笱獲兩，利之過倍。",
"42-36":"當風奮翼，與鳥飛北。入我嘉國，見吾慶室。",
"42-37":"麒麟鳳凰，善政德祥。陰陽和調，國無災殃。",
"42-38":"逐狐東山，水遏我前。深不可涉，失其後便。",
"42-39":"丑戌亥子，飢饉前生。陰陽暴客，水絕我食。",
"42-40":"狐狸雉兔，畏人逃去。分走竄匿，不知所處。",
"42-41":"桀跖惡人，使德不通。炎旱為殃，年榖大傷。",
"42-42":"文王四乳，仁愛篤厚。子畜十男，無有折夭。",
"42-43":"兔乳在室，行求雀食。虎懼我子，長號不巳。",
"42-44":"土階明堂，禮讓益興。雄二相得，使民無疾。",
"42-45":"送金出門，并失玉丸。往來井上，破甕壞盆。",
"42-46":"諷德誦功，美周盛𨺚。加其旦輔，光濟沖人。",
"42-47":"盜竊滅身，貳母不親。王后無黨，毀其寶靈。",
"42-48":"六目睽暌，各欲有至。專止未裝，候待旦明。",
"42-49":"雀行求粒，誤入𦊙罭。賴仁君子，復脫歸室。",
"42-50":"仁德孔明，患禍不傷。期誓不至，室人銜恤。",
"42-51":"龜厭江海，陸行不止。自令枯槁，失其都市。雖憂無咎。",
"42-52":"孤獨特處，莫依為輔，心勞志苦。",
"42-53":"伯仲言留，叔子云去。雖自無咎，主母大喜。",
"42-54":"初憂不安，後得笑懽，雖懼無患。",
"42-55":"好戰亡國，師不以律。稱上隕墜，齊侯狠戾，其被災祟。",
"42-56":"鹿在澤陂，豺傷其麑。泣血獨哀。",
"42-57":"天地閉塞，仁智隱伏。商旅不行，利潤難得。",
"42-58":"福德之士，懽悅日喜。夷吾相桓，三歸為臣，賞流子孫。",
"42-59":"上無飛鳥，下乏走獸。亂擾未治，民勞於事。",
"42-60":"據斗運樞，順天無憂。與樂並居。",
"42-61":"戴瓶望天，不見星辰。顧小失大，福逃廬外。",
"42-62":"月削日衰，工女下機。宇宙滅明，不見三光。",
"42-63":"操㦸刺魚，被𩬊立憂。虎脫我衣，狼取我袍，亡馬失財。",
"42-64":"兩人俱醉，相與悖戾。心乖不同，爭訟匈匈。",
"43-1":"狼戾美謀，無言不殊。允厭帝心，悅以獲祐。",
"43-2":"歲暮華落，陽入陰室。萬物伏匿，絕不可得。",
"43-3":"雞鳴失時，君騷相憂。犬吠不休，行者稽留。",
"43-4":"鳧鷖遊涇，君子以寧。履德不愆，福祿來成。",
"43-5":"薄為藩蔽，勁風吹卻。欲上不得，復歸其宅。",
"43-6":"東行破車，步入危家。衡門垂倒，無以為主。賣袍續食，糟糠不飽。",
"43-7":"青牛白咽，呼我俱田。歷山之下，可以多耕。歲稔時節，民人安寧。",
"43-8":"異國殊俗，情不相得。金木為仇，百賊擅殺。",
"43-9":"陰陽精液，高熟晚拆。胎卵成鬼，肇生頭目，日有大喜。",
"43-10":"飢蠱作害，偏多亂纒。緒不可得。",
"43-11":"清泠如雲，為兵導先。民人冤急，不知西東。",
"43-12":"班馬旋師，以息勞罷。役夫嘉喜，入戶見妻。",
"43-13":"坐爭立訟，紛紛匈匈。卒成禍亂，災及家公。",
"43-14":"鹿食美草，逍遙求飽。日暮後門，過期乃還。肥澤且厭。",
"43-15":"田鼠野雛，意常欲去。拘制籠檻，不得搖動。",
"43-16":"月趍日步，周遍次舍。歷險致遠，無有難處。",
"43-17":"天孫帝子，與日月處。光榮於世，福祿祉祉。",
"43-18":"晨風文翰，大舉就溫。昧過我邑，羿無所得。",
"43-19":"旦生夕死，名曰嬰鬼，不可得視。",
"43-20":"疾貧望仕，使伯南販，開牢擇羊，多得大牂。",
"43-21":"長城驪山，生我大殘。涉叔發難，唐叔為患。",
"43-22":"娶於姜呂，駕迎新婦。少齊在門，夫子歡喜。",
"43-23":"隨時春草，舊枝葉超。扶疏條桃，長大美盛，華沃鑠舒。",
"43-24":"姬姜既懽，二姓為婚。霜降合好，西施在前。",
"43-25":"戴笠獨宿，晝不見曰。勤苦無代，長勞悲思。",
"43-26":"始加元服，二十繫室。新婚既樂，伯季有得。",
"43-27":"二室靈臺，文所止遊。雲物備故，長樂無憂。",
"43-28":"久陰霖雨，塗行泥潦。商人依山，市空無有。",
"43-29":"城壞壓境，數為齊病。侵伐不休，君臣擾憂。上下屈竭，士民無財。",
"43-30":"南國盛茂，黍稷醴酒。可以饗養，樂我嘉友。",
"43-31":"憂在心腹，內崩為疾。禍起蕭墻，意如制國。",
"43-32":"朽根刖樹，華葉落去。卒逢火焱，隨風僵仆。",
"43-33":"樹表為壇，相與期言。午中不會，寵名棄廢。",
"43-34":"四足俱走，奴罷在後。德戰不勝，敗於東楚。",
"43-35":"執轡西朝，回還故處。麥秀傷心，叔父有憂。",
"43-36":"長夜短日，陰為陽賊。萬物空枯，藏於北陸。",
"43-37":"鳲鳩七子，均而不殆。長大成就，棄而合好。",
"43-38":"三羊上山，馳至大原。黃龍負舟，遂到夷傷，究其玉囊。",
"43-39":"手足易處，頭尾顛倒。公為雌嫗，亂其蚕織。",
"43-40":"登高望家，役事未休。王政靡盬，不得逍遙。",
"43-41":"畏昏不行，候待旦明。燎獵受福，老賴其慶。",
"43-42":"孤獨特處，莫依無輔。心勞志苦。",
"43-43":"戴堯扶禹，松喬彭祖。西過王母，道里夷易，無敢難者。",
"43-44":"山石朽破，消崩墮墜。上下離心，君受其祟。",
"43-45":"文母聖子，無疆壽考。為天下主，人受其福。",
"43-46":"倔傀加俄，前後相違。言如鱉咳，語不可知。",
"43-47":"五龍俱超，強者敢走。露我苗稼，年歲大有。",
"43-48":"虎除善猛，難為政毉。驥疲鹽車，困於銜箠。",
"43-49":"江南多蝮，螫於手足。冤煩詰屈，痛徹心腹。",
"43-50":"心無所據，射鹿不得。多言少實，語成無事。",
"43-51":"君明主賢，鳴求其友。顯德之政，可以履事。",
"43-52":"安上宜官，一日九遷。踰群越等，牧在常山。",
"43-53":"俊辭解謝，除去垢汙。驚之成患，嬰氏醳殘。",
"43-54":"翁狂嫗盲，相牽北行。欲歸高邑，迷惑不得。",
"43-55":"醉臥道傍，迷旦失明，不全我生。",
"43-56":"北登鬼丘，駕龍東遊。王叔御后，文武何憂。",
"43-57":"恬淡無患，遊戲道門。與神往來，長樂以安。",
"43-58":"以婚易系，抱布自媒。棄禮急情，卒離憂悔。",
"43-59":"被服大冠，游戲道門。以禮相終，身無殃患。",
"43-60":"大麓魚池，陸為海涯。君子失行，小人相攜。",
"43-61":"淵泉溢出，為我邑祟。道路不通，孩子心慣。",
"43-62":"十里望煙，散渙四分。形體滅亡，可入深淵，終不見君。",
"43-63":"𫝊言相誤，非姦徑路。鳴鼓逐狼，不知跡處。",
"43-64":"東失大珠，西行棄𥜗。時多不利，使我後起。",
"44-1":"蒙被恩德，長大成就。柔順貞利，君臣合好。",
"44-2":"東山西山，各自止安。心雖相望，意不同堂。",
"44-3":"登山上谷，與虎相觸。猬為功曹，班叔奔北，脫之嘉國。",
"44-4":"躓跛未起，失利後市。",
"44-5":"結珠懷履，卑斯以鬼，為君奴婢。",
"44-6":"雞鳴失時，民僑勞苦。厖吠有威，行者留止。",
"44-7":"陳媯敬仲，示兆興姜。乃寓營丘，八世大昌。",
"44-8":"鹿畏人匿，俱入深谷。短命不長，為虎所得，死於牙腹。",
"44-9":"言無約結，不成契劵。殷叔季女，公孫爭之。強入委禽，不悅於心。乃適子南。",
"44-10":"鼓瑟歌舞，懽遺於酒。龍喜張口，大喜在後。",
"44-11":"凶憂災殃，日益章明，禍不可救，三郤夷傷。",
"44-12":"水流趨下，遂成東海。求我所有，買鱣與鯉。",
"44-13":"陰為陽賊，君不能克。舉動失常，利無所得。",
"44-14":"離床失案，龜喪其願。都市無會，叔季懷恨。",
"44-15":"雍遏堤防，水不得行。火慎陽光，陰霓伏藏，走歸其鄉。",
"44-16":"躄屈復申，本乘浮雲，貴寵母前。",
"44-17":"實沈參罸，以義斷割。次陸服薪，成我霸功。",
"44-18":"金泉黃寶，宜與我市。娶嫁有息，利得過母。",
"44-19":"禹召諸侯，會稽南山。執玉萬國，天下康寧。",
"44-20":"三蟲作蠱，踐跡無與。勝母盜泉，君子不處。",
"44-21":"華葉墮落，公歸嫗宅。夷子失民，潔白不食。",
"44-22":"履機懼毀，身王子廢。終得所欲，無有凶害。",
"44-23":"道理和德，仁不相賊。君子攸往，樂有利福。",
"44-24":"合匏同牢，姬姜並居。",
"44-25":"關雎淑女，賢賢妃偶。宜家壽母，福祿長久。",
"44-26":"騏驥晚乳，不知子處。旋動悲鳴，痛傷我心。",
"44-27":"智嵓絕理，陰孽謀主。十日不食，困於申亥。",
"44-28":"監諸攻玉，無不穿鑿。麟鳳成形，德象君子。三仁翼事，所求必喜。",
"44-29":"昧暮乘車，以至伯家。踰梁渡河，濟脫無他。",
"44-30":"吾有黍𥹭，委積外塲。有用服葙，運我藏，富於喜糧。",
"44-31":"喜笑且語，不能掩口。官爵並至，慶賀盈戶。",
"44-32":"霧露雪霜，日暗不明。陰孽生疾，年榖大傷。",
"44-33":"伯去我東，𩬊飛如蓬。寤寐長歎，展轉空床。內懷悵恨，摧我肝腸。",
"44-34":"亡羊捕牢，母損於憂。",
"44-35":"販鼠賣卜，利少無謀，難以得家。",
"44-36":"西戎為疾，幽君去室。陳子發難，項伯成就。",
"44-37":"秋風生哀，華落生悲。公室多難，羊舌氏衰。",
"44-38":"持福厭患，去除天殘。日長夜盡，喜世蒙恩。",
"44-39":"新授大喜，福復重來。樂且日富，是惟豐財。",
"44-40":"前頓卻躓，左跌右逆。登高安梯，復反來歸。",
"44-41":"夢飯不飽，酒未入口。嬰女雖好，媒鴈不許。",
"44-42":"大都王市，稠人多寶。公孫宜賈，資貨萬倍。",
"44-43":"兩人俱醉，相與悖戾。心乖不同，爭訟匈匈。",
"44-44":"河伯大呼，津不可渡。往復爾故，乃無大悔。",
"44-45":"身無頭足，超蹠空乖。不能遠之，中道廢休，失利後時。",
"44-46":"三人俱行，六目光明。道逢淑女，與我驥子。",
"44-47":"進仕為官，不若復田，獲壽保年。",
"44-48":"先易後否，失我所市。騷蘇自苦，思吾故土。",
"44-49":"蘇氏發言，韓魏無患。張子馳說，燕齊以安。",
"44-50":"武庫軍府，甲兵所聚。非里邑居，不可舍止。",
"44-51":"一身三口，莫適所與。為孺子牛，田氏主咎。",
"44-52":"西山東山，各自止安。心雖相望，竟未上堂。",
"44-53":"不改柯葉，和氣中適。君子所在，安無怵惕。",
"44-54":"將戌擊亥，陽藏不起。君子散亂，太山危殆。",
"44-55":"天官列宿，五神舍室。宮闕完堅，君安其居。",
"44-56":"左手把水，右手把火。如光與鬼，不可得從。",
"44-57":"逐狐東山，水遏我前。深不可涉，失利後便。",
"44-58":"水瀆魚室，來灌吾邑。衝沒我家，與狗俱遊。",
"44-59":"山險難登，澗中多石。車馳轊擊，重載傷軸。擔負善躓，跌踒右足。",
"44-60":"糟空無實，豚彘不食。庶民屈竭，離其居室。",
"44-61":"執熱爛手，火為災咎。公孫母賴，敗我玉寶。",
"44-62":"三虎上山，更相噬嚙。心志不親，如仇與怨。",
"44-63":"西家嫁子，借鄰送女。嘉我眾婿，賓主俱喜。",
"44-64":"克身潔巳，逢禹巡狩。錫我玄圭，拜受福祉。",
"45-1":"碩鼠四足，飛不上屋。顏氏淵德，未有爵祿。",
"45-2":"新受大喜，福履重職，樂且日富。",
"45-3":"剋身整巳，逢禹巡狩。錫我玄珪，拜受福祉。",
"45-4":"置筐失筥，輪破無輔。家伯為政，病我下土。",
"45-5":"機言不發，頑不能達。齊魯為仇，亡我葵丘。",
"45-6":"亡錐失斧，公輸無輔。抱其彛器，適君子處。",
"45-7":"家在海隅，橈短深流。伯氏難行，無目以趨。",
"45-8":"德施流行，利之四鄉。雨師灑道，風伯逐殃。巡狩封禪，以告成功。",
"45-9":"筐傾筥覆，喪我公粒。簡伯無禮，太師正食。",
"45-10":"泥滓汙辱，棄捐溝瀆。為眾所笑，終不顯祿。",
"45-11":"獼猴兔走，腥臊少肉。漏卮承酒，利無所得。",
"45-12":"鹿畏人藏，俱入深谷。命短不長，為虎所得，死於牙腹。",
"45-13":"南山蘭芝，君子所有。東家淑女，生我玉寶。",
"45-14":"左指右揮，邪佞侈靡。執節無良，靈君以亡。",
"45-15":"鬱怏不明，為濕所傷。眾陰群聚，共奪日光。",
"45-16":"穿鼻繫棘，為虎所拘。王母祝福，禍不成災，突然脫來。",
"45-17":"貧鬼守門，日破我盆。毀甖傷釭，空虛無子。",
"45-18":"襄王束帶，鄭人是賴。莊公卿士，皇母憂苦。",
"45-19":"昭君死國，諸夏蒙德。異類既同，宗我王室。",
"45-20":"冬藪枯腐，常風於道。蒙被塵埃，左右勞苦。",
"45-21":"六爻既立，神明喜告。文定吉祥，康叔受福。",
"45-22":"泣涕長訣，我心不快。遠送衛野，歸寧無子。",
"45-23":"三宿無主，南行勞苦。東里失利，喪其珍寶。",
"45-24":"大斧破木，讒佞敗國。東間梁王，禍及三子。晉人亂危，懷公出走。",
"45-25":"乘風上天，為時服軒。周旋萬里，無有患難。",
"45-26":"大樹百根，北與山連。文君作人，受福萬年。",
"45-27":"陽伏在下，陰制祐福。生不逢時，潛龍隱處。",
"45-28":"亂頭多憂，搔虱生愁。膳夫仲尹，使我無聊。",
"45-29":"江河淮海，天之都市。商人受福，國家富有。",
"45-30":"太山幽谷，鳳皇遊宿。威儀有敘，可以來福。",
"45-31":"山水暴怒，壞梁折柱。稽難行旅，留連愁苦。",
"45-32":"阿衡服箱，太一載行。巡時歷舍，所之吉昌。",
"45-33":"三宿無主，南行勞苦。東里失利，喪其珍寶。",
"45-34":"生無父母，出門不喜。買菽失粟，亡我大乘。",
"45-35":"安坐玉堂，聽樂行觴。飲福萬歲，日受無疆。",
"45-36":"登危入厄，四時變易。春霜變雪，物皆凋落。",
"45-37":"衣穴履穿，無以禦寒。細小貧窶，不能自存。",
"45-38":"目不可合，憂來搔足。悚愓恐懼，去其邦域。",
"45-39":"齎貝贖狸，不聽我辭。繫於虎鬚，牽不得來。",
"45-40":"伯夷叔齊，貞廉之師。以德防患，憂禍不存，聲芳後時。",
"45-41":"張王子季，爭財相制。商君頑嚚，不知所申。",
"45-42":"長城既立，四夷賓服。交和結好，昭君受福。",
"45-43":"千懽萬悅，舉事為決。獲受嘉慶，動作有得。",
"45-44":"種一得十，日益有息。仁政獲民，四國睦親。",
"45-45":"蒙慶受福，有所獲得。不利出城，病人困棘。",
"45-46":"安子富有，東國不殃。齊鄭和親，顯比以喜。",
"45-47":"九里十山，道仰峻難。牛馬不前，復反來還。",
"45-48":"鳩杖扶老，衣食百口。增添壽考，凶惡不起。",
"45-49":"霧露雪霜，日暗不明。陰旱為疾，年榖大傷。",
"45-50":"迷行數邪，不知東西。陰強暴逆，道理不通。",
"45-51":"登高上山，見王自言。信理我冤，得職蒙恩。",
"45-52":"三世為德，天祚以國。封建少昊，魯侯之福。",
"45-53":"橋木無息，漢女難得。橘柚請佩，反手難悔。",
"45-54":"東鄰西家，來即我謀。中告吉誠，使君安寧。",
"45-55":"褰衣出戶，心欲北走。王孫母驚，使我長生。",
"45-56":"三日不飲，遠水無酒。晝夜焦喉，傷鬼為咎。",
"45-57":"眾口銷金，愆言不驗。腐臭敗兔，入市不售。",
"45-58":"姬冠應門，與伯爭言。東家失狗，意我不存。爭亂忘因，絕其所懽。",
"45-59":"祚加明德，興我周國。公劉文母，福流子孫。",
"45-60":"針頭刺手，百病瘳愈。抑按捫灸，死人復起。",
"45-61":"元龜象齒，大賂為寶。稽疑當否，衰微復起。",
"45-62":"故室舊廬，消散無餘。不如新創，可以樂居。",
"45-63":"老狐多態，行為蠱怪。驚我主母，終無咎悔。",
"45-64":"愛子多才，起跡空虛。避害如神，水不能濡。",
"46-1":"白鹿鳴呦，呼其老小。喜彼茂草，樂我君子。",
"46-2":"百里南行，雖微得明。去虞適秦，為穆國卿。",
"46-3":"王宜孫喜，張名益有。龍子善行，西得大壽。",
"46-4":"畫龍頭頸，文章不成。所求不得，失利後時。",
"46-5":"商子無良，相怨一方。引剛交爭，咎自以當。",
"46-6":"衰老困極，無齒不食。痔病痟瘵，就陰為室。",
"46-7":"鳶生會稽，稍巨能飛。翱翔桂林，為眾鳥雄。",
"46-8":"安平不傾，載福長生，君子以寧。",
"46-9":"牛驥同槽，郭氏以亡。國破為虛，君奔走逃。",
"46-10":"日中明德，盛興兩國。仁聖會遇，君受其福，臣多榮祿。",
"46-11":"公劉之居，太王所業。可以長生，拜受福爵。",
"46-12":"時凋歲霜，君子疾病。宗女無辜，鄭受其殃。",
"46-13":"濟河踰阨，脫母怵愓。四叔為衛，使惠不廢。",
"46-14":"缺破不完，殘瘵側偏。公孫幽遏，跛踦後門。",
"46-15":"延頸遠望，眛為目病。不見叔姬，使伯憂心。",
"46-16":"上無飛鳥，下無走獸。擾亂未清，民勞於事。",
"46-17":"久陰霖雨，塗行泥潦。商人休止，布空無有。",
"46-18":"盲者張目，跛踦起行。瞻望日月，與王相迎。",
"46-19":"據斗運樞，高步六虛。權既在手，寰宇可驅。國大無憂，與樂並居。",
"46-20":"稼穡不偏，重過不傾。巧言賊忠，傷我申生。",
"46-21":"金城鐵郭，上下同力。政平民親，寇不敢賊。",
"46-22":"目鏡不明，冬災大傷。盜華失實，十年消亡。",
"46-23":"鰥寡孤獨，命祿苦薄。入室無妻，武子悲哀。",
"46-24":"飲酒醉飽，跳起爭鬥。伯喪叔僵，東家治喪。",
"46-25":"介紹微子，使君不殆。二國合懽，燕齊以安。",
"46-26":"牽牛繫尾，詘折幾死。雕世無仁，不知所在。",
"46-27":"東龍冤獨，不知所觸。南北困窮，王子危急。",
"46-28":"疾貧王孫，北陸無禪。祿命苦薄，兩事孤門。",
"46-29":"公孫駕釃，載遊東齊。延陵說產，遺季苧衣。",
"46-30":"王良善御，伯樂知馬。文王東獵，獲喜聖事。開福祐賢，周發興起。",
"46-31":"日月不居，重耳趨舍。遊燕入秦，晉國是霸。",
"46-32":"假文翰翼，隨風偕北。至虞夏國，興愛相得。年歲大樂，邑無盜賊。",
"46-33":"南行無遯，延頸後食。舉止失利，累為我孫。",
"46-34":"開元作喜，建造利事。平準貨寶，海內殷富。",
"46-35":"三犬俱走，鬥於谷口。白鷰不勝，死於阪下。",
"46-36":"驕胡大彤，造惡作凶。無所能成，還自滅身。",
"46-37":"拜跪贊辭，無益於尤。大夫頑囂，使我生憂。",
"46-38":"辰以降婁，王駕巡狩。廣祐施惠，萬國咸喜。",
"46-39":"牽羭上樓，與福俱居。勞躬治國，安樂無憂。",
"46-40":"白鳥銜餌，鳴呼其子。挾施張翅，來從其母。",
"46-41":"盲瞽獨宿，莫與共食。老窮於人，病在心腹。",
"46-42":"登木出淵，稍上升天。明德孔聖，白日載榮。",
"46-43":"彭离濟東，遷廢上庸。佷戾無節，失其寵功。",
"46-44":"讃陽上舞，神明生氣。拜禹受福，君施我德。",
"46-45":"從首至足，部分為六。室家離散，逐南乞食。",
"46-46":"禹鑿龍門，通利水泉。東注滄海，民得安全。",
"46-47":"民迷失道，亂我統紀。空使乾革，實無所有。",
"46-48":"刻畫為飾，嫫母無鹽。毛嬙西施，求事必得。",
"46-49":"居諸日月，御暗不明。長夜喪中，絕其紀綱。",
"46-50":"衣裳顛倒，為王來呼。成就東國，封受大休。",
"46-51":"當變立權，擿解患難。渙然冰釋，六國以寧。",
"46-52":"西戎獯鬻，病於我國。扶陜之岐，以保乾德。",
"46-53":"南行逐羊，予利喜亡。陰孽為病，復反其邦。",
"46-54":"遊戲仁德，日益有福。凶言不至，妖孽滅息。",
"46-55":"奏日新婚，就陽曰溫。喜樂萬歲，獲福有年。",
"46-56":"陰升陽伏，舜失其室。相飾不食，安巢如棘。",
"46-57":"臣尊主卑，威權日衰。侵奪無光，三家逐公。",
"46-58":"反言為殘，戎女生患。亂吾家國，父子相賊。",
"46-59":"迎福開戶，喜隨我後。康伯愷悌，治民以禮。",
"46-60":"日就月將，昭明有功。靈臺歡賞，膠鼓作人。",
"46-61":"百草嘉卉，萌芽將出。昆蟲扶戶，陽明得所。",
"46-62":"天所祐助，萬國日有。福至禍去，壽命長久。",
"46-63":"窮夫失居，惟守弊廬。初憂中懼，惟日兢兢，無悔無虞。",
"46-64":"買玉得石，失其所欲。荷蕢擊磬，隱世無聲。",
"47-1":"烏鵲食榖，張口受哺。蒙被恩德，長大成就。柔順利貞，君臣合好。",
"47-2":"六鷁退飛，為襄敗祥。陳師合戰，右股夷傷。遂以薨崩，霸功不終。",
"47-3":"匍匐出走，驚惶悼恐。白虎王孫，蓐収在後，居中無咎。",
"47-4":"庇盧不明，使孔德妨。女孽亂國，虐政傷仁。",
"47-5":"石鼠四足，不能上屋。顏氏淑德，未有爵祿。",
"47-6":"襄送季女，至于蕩道。齊子旦夕，久留連處。",
"47-7":"麞鹿逐牧，飽歸其居。還反次舍，樂得自如。",
"47-8":"望尚阿衡，太宰周公。藩屏湯武，立為侯王。",
"47-9":"開廓洪緒，王跡所基。報以八子，功得侯時。",
"47-10":"八會大都，饒富有餘。安民利國，可以長居。",
"47-11":"陰雲四方，日在中央。人雖昏霧，我獨昭明。",
"47-12":"薄為災虐，風吹雲卻。欲上不得，復歸其宅。",
"47-13":"昭昭略略，非忠信客。言語反覆，以黑為白。",
"47-14":"三女為姦，俱遊高園。背室夜行，與伯笑言。禍及乃身，冤死誰禱。",
"47-15":"涉尸留鬼，大斧所視。文昌司過，簡公亂死。",
"47-16":"大足長股，利出行道。囷倉充盈，疏齒善市。宜錢富家，事得萬倍。",
"47-17":"筐筥錡釜，可活百口。伊氏鼎俎，大福所起。",
"47-18":"升高登虛，欲有望候。駕之北邑，與喜相扶。",
"47-19":"用彼嘉賓，政平且均。螟蟲不作，民得安寧。",
"47-20":"桃夭少葉，婚說宜家。君子樂胥，長利止居。",
"47-21":"東行失旅，不知所處。西歸無妃，莫與笑語。",
"47-22":"玩好亂目，巧聲迷耳。賊敗貞良，君受其咎。",
"47-23":"明德孔嘉，萬歲無虧。駕龍巡狩，王得安所。",
"47-24":"同本異葉，樂仁上德。東鄰慕義，來興吾國。",
"47-25":"戴山崔嵬，曰高無頹。君主我德，賜以家國。",
"47-26":"築室合懽，千里無患。周公萬年，祐我二人。",
"47-27":"養雞生雛，畜馬得駒。明堂太學，君子所居。",
"47-28":"雷行相逐，無有休息。戰於平陸，為夷所覆。",
"47-29":"委蛇循河，北至海涯。涉歷要荒，君世無他。",
"47-30":"鴻聲大視，高舉神化。背昧向明，以道福功。",
"47-31":"比目四翼，來安吾國。福喜上堂，與我同床。",
"47-32":"先縠彘季，反謀桓子。子從元帥，遂行挑戰。為荊所敗。",
"47-33":"三頭六足，欲盜東國。顏子在邇，禍滅不成。",
"47-34":"縁山升木，中墜於谷。子輿失勞，黃鳥哀作。",
"47-35":"南有嘉魚，駕黃取麟。魴鯉瀰瀰，利來無憂。",
"47-36":"䆳氣作雲，蒙覆大君。塞聰蔽明，殷人賈傷。",
"47-37":"舉翅攄翼，鼓望南國。延頸郄縮，未有所得。",
"47-38":"坎中蝦蟆，乍盈乍虛。三夕二朝，形消無餘。",
"47-39":"僮子射御，不知所定。質疑蓍龜，孰知所避。國安土樂，宜利止居。兵寇不至，民無搔擾。",
"47-40":"陰淫寒疾，水離其室。舟楫大作，傷害黍稷。民飢於食，不無病厄。",
"47-41":"離友絕朋，巧言讒匿。覆白汙玉，顏叔哀哭。",
"47-42":"童女無媒，不宜動搖。安其室廬，傅母何憂。",
"47-43":"作凶作患，北檄困貧。東與禍連，傷我老根。",
"47-44":"東南其戶，風雨不處。曣睨仁人，父子相保。",
"47-45":"被髮獸心，難與比鄰。來如飄風，去如絕絃，為狼所殘。",
"47-46":"天覆地載，日月運照。陰陽允作，方內四富。",
"47-47":"席多針刺，不可以臥。動而有悔，言行俱過。",
"47-48":"桀亂無道，民散不聚。背室棄家，君孤出走。",
"47-49":"申酉稷射，陰慝萌作。柯葭載牧，泥塗不白。",
"47-50":"踝踵足傷，右指病瘍。失旅後時，利走不來。",
"47-51":"四足俱走，駑疲在後。戰既不勝，敗於東野。",
"47-52":"塗行破車，醜女無媒。莫適為偶，孤困獨居。",
"47-53":"搏髀大笑，不知憂懼。開立大路，為主所召。",
"47-54":"伯圭東行，與利相逢。出既遭昧，孰不相知。憂不成凶。",
"47-55":"東行賊家，鄭伯失辭。國無貞良，居受其殃。",
"47-56":"前屈後曲，形體飭急。絞黑大索，困於清室。",
"47-57":"鼓腋大喜，行婚飲酒。嘉彼諸姜，樂我皇考。",
"47-58":"國將有事，狐嘈向城。三日悲鳴，邑主大驚。",
"47-59":"明德克敏，重華貢舉。放勳徵用，公哲蒙祐。",
"47-60":"秋隼冬翔，數被嚴霜。甲兵充庭，萬物不生。雄父夜鳴，民大擾驚。",
"47-61":"絲紵布帛，人所衣服。摻摻女手，紡績善織。南國饒足，取之有息。",
"47-62":"鳳有十子，同巢共母。仁聖在位，懽以相保，興彼周魯。",
"47-63":"雄雞不晨，雌鳴且伸。志庇心離，三旅出哀。",
"47-64":"光祀春成，陳寶雞鳴。陽鳥失道，不能自守。消亡無咎，舉事不成，自取凶咎。",
"48-1":"左輔右弼，金玉滿堂。常盈不亡，富如敖倉。",
"48-2":"雨師娶婦，黃巖季子。相呼而歸，潤澤田里。",
"48-3":"螟蟲為賊，害我稼穡。盡禾殫麥，秋無所得。",
"48-4":"跛躄難步，遲不及舍。露宿澤陂，亡其𥜗褲。",
"48-5":"大夫行父，無地不涉。為吾相土，莫如韓樂。可以居止，長安富有。",
"48-6":"少孤無父，長失慈母。悖悖煢煢，莫與為福。",
"48-7":"側弁醉客，重舌作凶。披髮夜行，迷亂相誤，亡失居止。",
"48-8":"馬驚破處，王孫沉溝。身死魂去，自為患害。",
"48-9":"東行述職，征討不服。侵齊伐陳，銜璧為臣，大得意還。",
"48-10":"百足俱行，相輔為強。三聖翼事，王室寵光。",
"48-11":"本根不固，華葉落去，更為孤嫗。",
"48-12":"牧羊稻園，聞虎喧喧。畏懼休息，終無禍焉。",
"48-13":"履位乘勢，靡有絕蔽。為眾所圖，與眾庶位。",
"48-14":"大輿多塵，小人傷賢。皇甫司徒，使君失家。",
"48-15":"安和太山，福祐屢臻。雖有狼虎，不能危身。",
"48-16":"同氣異門，各別東西。南與凶遇，北傷其孫。",
"48-17":"蜆見不祥，禍起我鄉。行人畏亡，使命不通。",
"48-18":"無事召禍，自取災殃。畜狼養虎，必見賊傷。",
"48-19":"順風吹火，牽騎驥尾。易為功力，因權受福。",
"48-20":"五嶽四瀆，霑濡為德。行不失理，民賴恩福。",
"48-21":"延陵聰敏，樂聽太史。雞鳴大國，姜氏受福。",
"48-22":"神鳥五色，鳳凰為主。集於王谷，使君得所。",
"48-23":"媒妁先明，雖期不得。齊女長子，亂其紀綱。",
"48-24":"明月作晝，大人失居。眾星霄亂，不知所據。",
"48-25":"少康興起，誅澆復祖。微滅復明，大禹享祀。",
"48-26":"千門萬戶，大福所處。黃屋左纛，龍德獨有。",
"48-27":"乾作聖男，坤為智女。配合既成，長生得所。",
"48-28":"羿張烏號，彀䠶驚狼。鍾鼓夜鳴，將軍壯心。趙國雄勇，鬥死滎陽。",
"48-29":"炙魚銅斗，張伺夜鼠。不忍香味，機發為祟。祟在頸頭，笮不得去。",
"48-30":"高飛不視，貪叨所在。臭腐為患，自害躬身。",
"48-31":"鉛刀攻玉，堅不可得。單盡我力，齒為疾賊。",
"48-32":"方啄宣口，聖知仁厚。釋解倒懸，家國大安。",
"48-33":"踟躕南北，誤入喪國。杜季利兵，傷我心腹。",
"48-34":"公孫之政，惠而不煩。喬子相國，終身無患。",
"48-35":"弧矢大張，道絕不通。小人寇賊，君子壅塞。",
"48-36":"藏戟之室，封豕受福。充澤肥腯，子孫蕃息。",
"48-37":"八子同巢，心勞相思，雖苦無憂。",
"48-38":"循理舉手，舉求取予。六體相摩，終無咎殃。",
"48-39":"王子公孫，把絃攝丸。發輒有獲，家室饒足。",
"48-40":"井者有悔，渴蜺為怪。不亟徙鄉，家受其殃。",
"48-41":"鄭會細聲，國亂失頃。弘明早見，止樂不聽。",
"48-42":"穿室鑿墻，不直生訟。褰衣涉露，雖勞無功。",
"48-43":"脫卵免乳，長大成就。君子萬年，動有利得。",
"48-44":"五心乖離，各引是非。莫適為主，道路塞壅。",
"48-45":"百柱載梁，千歲不僵。大願輔福，文武以昌。",
"48-46":"營城洛邑，周公所作。世逮三十，年歷七百。福祐封實，堅固不落。",
"48-47":"牛耳聾蔽，不曉聲味。委以鼎俎，方始亂潰。",
"48-48":"躓跛未起，失利後市，不得鹿子。",
"48-49":"從叔旅行，食於東昌。嘉伯悅喜，與我芝香。",
"48-50":"訾娵開門，鶴鳴彈冠。文章進用，舞韶和鸞。三仁翼政，國無災殃。",
"48-51":"遊魂六子，百木所起。三男從父，三女隨母。至巳而反，各得其所。",
"48-52":"南山藺𮎼，使君媚好。皇女長婦，多孫眾子。",
"48-53":"黃虹之野，賢君在位。榮叚為相，國無災殃。",
"48-54":"穿鑿道路，為君除舍。開闢福門，喜在我鄰。",
"48-55":"商風數起，天下昏晦。旱魃為虐，九土兵作。",
"48-56":"自衛歸魯，時不我與。冰炭異室，仁道隔塞。",
"48-57":"春陽生草，夏長條肄。萬物蕃滋，充實益有。",
"48-58":"六蛇奔走，俱入茂草。驚於長注，畏懼啄口。",
"48-59":"明月照夜，使暗為晝。國有仁賢，君尊如故。",
"48-60":"避蛇東走，反入虎口。制於爪牙，骨為灰土。",
"48-61":"頃迭不行，弱足善僵。孟縶無良，失其寵光。",
"48-62":"十羊俱見，黃頭為首。歲美民安，國樂無咎。",
"48-63":"望風入門，來到我鄰。餔吾養均。",
"48-64":"登高車反，視天彌遠。虎口不張，害賊消亡。",
"49-1":"高原峻山，陸土少泉。草木林麓，嘉得所畜。",
"49-2":"一門二關，結緝不便。峻道異路，日暮不到。",
"49-3":"憂禍解除，喜至慶來。坐立懽門，與樂為鄰。",
"49-4":"殊類異路，心不相慕。牝牛牡猳，鰥無室家。",
"49-5":"太王為父，季歷孝友。文武聖明，仁政興起。旦隆四國，載福綏厚。",
"49-6":"臨河求鯉，燕蜿失餌。屏氣攝息，不得鯉子。",
"49-7":"買利求福，莫如南國。仁德所在，金玉為寶。",
"49-8":"白虎赤憤，闚觀王庭。宮闕被甲，大小出征。天地煩潰，育不能嬰。",
"49-9":"子車針虎，善人危殆。黃鳥悲鳴，傷國無輔。",
"49-10":"兩目失明，日暮無光。脛足跛步，不可以行，頓於丘傍。",
"49-11":"羅網四張，鳥無所翔。征伐困極，飢窮不食。",
"49-12":"伯夷叔齊，貞廉之師。以德防患，憂禍不存。",
"49-13":"疾貧望幸，使伯行販。開牢擇羊，多得大牂。",
"49-14":"南山之陽，華葉鏘鏘。嘉樂君子，為國寵光。",
"49-15":"東壁餘光，數暗不明。主毋嫉妒，亂我業事。",
"49-16":"迷行晨夜，道多湛露。瀐我褲𥜗，重不可涉。",
"49-17":"目瞤足動，喜如其願，舉家蒙寵。",
"49-18":"鷹鸇欲食，雉兔困急。逃頭見尾，為害所賊。",
"49-19":"鼻移在項，枯葉傷生。下朽上榮，家擾不寧，失其金城。",
"49-20":"飛不遠去，法為罔待，祿養未富。",
"49-21":"側基敗宮，重舌作凶。被𩬊長夜，迷亂相誤，深亡吉居。",
"49-22":"亥午相錯，敗亂緒業，民不得作。",
"49-23":"野麋畏人，俱入山谷。命短不長，為虎所得，死於牙腹。",
"49-24":"秋冬探巢，不得鵲雛。銜指北去，愧我少姬。",
"49-25":"雙鳧俱飛，欲歸稻池。經涉雚澤，為矢所射，傷我胸臆。",
"49-26":"天門開闢，牢戶寥廓。桎梏解脫，抅囚縱釋。",
"49-27":"尼父孔丘，善釣鯉魚。羅釣一舉，得獲萬頭，富我家居。",
"49-28":"彭君為妖，暴龍作災。盜堯衣裳，聚跖荷兵。青禽照夜，三日夷亡。",
"49-29":"華言風語，亂相誑誤。終無凶事，安寧如故。",
"49-30":"逃頸見足，身困不辱。欲隱避仇，為害所賊。",
"49-31":"無足斷跟，居處不安，凶惡為殘。",
"49-32":"三人俱行，北求大牂。長孟病足，倩季負囊。柳下之貞，不失我糧。",
"49-33":"退飛見祥，傷敗毀墜。守小失大，功名不遂。",
"49-34":"持心懼怒，善數搖動，不安其處。散災府藏，無有利得。",
"49-35":"牽尾不前，逆理失臣，惠朔以奔。",
"49-36":"祿如周公，父子俱封。",
"49-37":"吾有八人，信允篤畝，為堯所舉。",
"49-38":"久陰霖雨，泥塗行潦。商人休止，市空無寶。",
"49-39":"無足斷跟，居處不安，凶惡為殘。",
"49-40":"馬蹄躓車，婦惡破家。青蠅汙白，恭子離居。",
"49-41":"噂噂不言，莫如我垣。歡樂堅固，可以長安。",
"49-42":"懿公淺愚，不深受謀。無援失國，為狄所賊。",
"49-43":"騏驎綠耳，章明造父。伯夙奉獻，襄續厥緒。佐文成霸，為晉元輔。",
"49-44":"駕車入里，求鮮魴鯉。非其肆居，自令後市。",
"49-45":"求獐嘉鄉，惡地不行。道止中遷，復反其床。",
"49-46":"杖鳩負裝，醉臥道傍。不知何公，竊我錦囊。",
"49-47":"登崑崙，入天門。過糟丘，宿玉泉。同惠歡，見欣君。",
"49-48":"水為火壯，患厭不起。季伯夜行，與喜相逢。",
"49-49":"馬服長股，宜行善布。蒙祐諧偶，獲金五倍。",
"49-50":"烏孫氏女，深目黑醜。嗜欲不同，過時無偶。",
"49-51":"子鉏執麟，春秋作元。陰聖將終，尼父悲心。",
"49-52":"灼火泉原，釣魴山顛。魚不可得，炭不可燃。",
"49-53":"天馬五道，炎火久處。往來上下，非文釣巳。衣衰絲麻，相隨在歌。凶惡如何。",
"49-54":"鴟鴞破斧，沖人危殆。賴旦忠德，轉禍為福，頃危復立。",
"49-55":"杜飛門啟，憂患大解，不為身禍。",
"49-56":"石門晨開，荷蕢疾貧。遁世隱居，竟不逢時。",
"49-57":"兔聚東郭，眾大俱獵。圍缺不成，無所能獲。",
"49-58":"三羊群走，雉兔驚駭。非所畏懼，自令勞苦。",
"49-59":"羽翮病傷，無以為強。宋公德薄，敗於水泓。",
"49-60":"姬姜雅叔，三人偶食。論仁義福，以安王室。",
"49-61":"精誠所在，神為人輔。德教之中，彌世長久。三聖乃興，多受福祉。",
"49-62":"歧周海隅，獨樂不憂。可以避難，全身保才。",
"49-63":"孤獨特處，莫依為輔，心勞志苦。",
"49-64":"顧望登臺，意常欲逃。賈辛醜惡，妻不安夫。",
"50-1":"頃筐卷耳，憂不得傷。心思故人，悲慕失母。",
"50-2":"郤叔賈貸，行祿多悔，利無所得。",
"50-3":"蹙狂跛祍，辟坐不行。棄損平人，名字無中。",
"50-4":"文王四乳，仁愛篤厚。子畜十男，無有折夭。",
"50-5":"容民畜眾，不離其居。",
"50-6":"三推相逐，蠅墜釜中。灌沸淹殪，與母長決。",
"50-7":"所望在外，鼎令方來。拭爵澡罍，炊食待之，不為季憂。",
"50-8":"陸居少泉，高山無雲。車行千里，塗汙尔輪，亦為我患。",
"50-9":"東家殺牛，聞臭腥臊。神背不顧，命衰絕周。亳社災燒，宋人夷誅。",
"50-10":"長子入獄，婦饋毋哭。霜降旬日，鄉晦伏法。",
"50-11":"溫山松柏，常茂不落。鳳凰以庇，得其歡樂。",
"50-12":"大屋之下，朝多君子。德施博育，宋受其福。",
"50-13":"羅張目決，圍合耦缺，魚鳥生脫。",
"50-14":"羔裘豹祛，高易我字。君子維好。",
"50-15":"大頭明目，載受喜福。三雀飛來，與祿相得。",
"50-16":"消鋒鑄刄，縱牛放馬。甲兵解散，夫婦相保。",
"50-17":"吉日舉釣，田弋獵禽。反行飲至，以告喜功。",
"50-18":"商人行旅，資無所有。貪貝逐利，留連玉帛。馭轅內安，公子何咎。",
"50-19":"火井暘谷，揚芒生角。犯歷天門，闚見太微。登上玉床，家易共公。",
"50-20":"秋隼東翔，數被嚴霜。甲兵庭堂，萬物不生。雞釜夜鳴，民擾大驚。",
"50-21":"東行西步，失其次舍。乾侯野井，昭君喪居。",
"50-22":"腫頸病腹，陷厠汙辱。命短時極，孤子哀哭。",
"50-23":"切膚近火，虎絕我鬚。小人橫暴，君復何之。",
"50-24":"女室作毒，為我心疾。和不能治，晉人赴告。",
"50-25":"兵征大宛，北出玉門。與胡寇戰，平城道西。七日無糧，身幾不全。",
"50-26":"九子十夫，莫適與居。貞心不壹，自令老孤。",
"50-27":"東行稻麥，遂至家國。樂土無災，君父何憂。",
"50-28":"作室山根，所以為安。一夕崩顛，破我饔餐。",
"50-29":"六人俱行，各遺其囊。黃鵠失珠，無以為明。",
"50-30":"伯蹇叔盲，莫為守裝。失我衣裘，我是陰鄉。",
"50-31":"褒寵洒尤，敗政傾家。覆我宗國，秦滅周室。",
"50-32":"該言譯語，仇禍相得。冰入炭室，消滅不息。",
"50-33":"彭名為妖，暴龍作災。盜堯衣裳，聚跖荷兵。青禽照夜，三旦夷亡。",
"50-34":"朝露白日，四馬過隙。歲短期促，時難𠕅得。",
"50-35":"耳闕道衰，所為不成，求事匪得。",
"50-36":"申公患楚，危不自安。重耳出奔，側喪其魂。",
"50-37":"南上太山，困於此桑。左砂右石，牛馬無食。",
"50-38":"海隅遼右，福祿所在。柔嘉蒙禮，九夷何咎。",
"50-39":"陽春生長，萬物茂壯。垂枝布葉，君子比德。",
"50-40":"低頭竊視，有所畏避。行作不利，酒酸魚敗。眾莫貪嗜。",
"50-41":"左輔右弼，金玉滿櫃。常盈不亡，富於敖倉。",
"50-42":"坐朝乘軒，據德宰民。虞舜受命，六合和親。",
"50-43":"東行西坐，喪其犬馬。南求驊騮，失車林下。",
"50-44":"砥德礪材，果當成周。拜受大命，封為齊侯。",
"50-45":"西逢王母，慈我九子。相對懽喜，王孫萬戶。家蒙福祉。",
"50-46":"安坐玉床，聽韶行觴。飲福萬歲，日受無疆。",
"50-47":"登高望家，役事未休。王政靡盬，不得逍遙。",
"50-48":"擊鼓陷陔，不得相踰。章父文德，福厭禍消。",
"50-49":"追亡逐北，呼還幼叔。至止而復，得反其室。",
"50-50":"積德之至，君政且溫。伊呂股肱，國富民安。",
"50-51":"老猾大偷，東行盜敖。困於噬敖，幾不得去。",
"50-52":"禹召諸侯，會稽南山。執玉萬國，天下康安。",
"50-53":"忉怛忉怛，如將不活。黍稷之恩，靈輒以存，獲生保年。",
"50-54":"侯叔興起，季子富有。照臨楚國，蠻荊是安。",
"50-55":"白馬駵駁，更生不休。富我商人，利得如丘。",
"50-56":"灼火泉原，釣魴山顛。魚不可得，炭不可燃。",
"50-57":"避患東西，反入禍門。糟糠不足，憂動我心。",
"50-58":"成王多寵，商臣惶恐。生其禍心，使君危殆。",
"50-59":"虎飲欲食，見猬而伏。禹通龍門，避咎除患，元醜以安。",
"50-60":"安民呼池，玉杯大按。泉如白蜜，一色獲願。",
"50-61":"雙鳧鴛鴦，相隨君行。南至饒澤，食魚與梁，君子與長。",
"50-62":"蔡侯朝楚，留連江渚。踰時歷月，思其君后。",
"50-63":"膠車駕東，與雨相逢。五棨解墜，蝢阨獨坐，憂為身禍。",
"50-64":"螟蟲為賊，害我稼穡。盡禾殫麥，利無所得。",
"51-1":"陷塗溺水，火燒我履，憂患重累。",
"51-2":"旦生夕死，名曰嬰鬼。不可得視。",
"51-3":"揚水潛鑿，使君潔白。衣素附珠，遊戲皋沐。得其所願，心志娛樂。",
"51-4":"眾鳥所翔，中有大怪，九身無頭。魂驚魄去，不可以居。",
"51-5":"刖根枯株，不生肌膚。病在於心，日以燋枯。",
"51-6":"府藏之富，王以振貸。捕魚河海，筠笀多得。",
"51-7":"一莖九纒，更相牽攣。宿明俯仰，不得東西。請獻當報，日中被刑。",
"51-8":"耋老鮐背，齒牙動搖。近地遠天，下入黃泉。",
"51-9":"羊舌叔虎，野心善怒。瀆貨無厭，以滅其身。",
"51-10":"謀疑八子，更相欺紿。管叔善止，不見邪期。",
"51-11":"伴跳不遠，心與言反。尼丘顧家，茅蕈朱茟。",
"51-12":"蚍蜉載盆，不能上山。搖推跌䟦，頓傷其顏。",
"51-13":"朝露不久，為恩惠少。膏澗欲盡，咎在枯槁。",
"51-14":"河伯之功，九州攸同。載祀六百，光烈無窮。",
"51-15":"三人北行，大見光明。道逢淑女，與我驥子。",
"51-16":"金精曜怒，帶鈞通午。徘徊高庫，宿於木下。兩虎相拒，弓弩滿野。",
"51-17":"江河淮海，天之奧府。眾利所處，可以富有。好樂喜友。",
"51-18":"不虞之患，禍生無門。奄然暴卒，病傷我心。",
"51-19":"畫龍頭頸，文章未成。甘言美語，說辭無名。",
"51-20":"缺破不成，胎卵不生。不見兆形。",
"51-21":"旁行不遠，三里復反。心多畏惡，日中止舍。",
"51-22":"四隤不安，兵革為患。掠我妻子，家履飢寒。",
"51-23":"喜來如雲，嘉福盈門。眾才君子，舉家蒙懽。",
"51-24":"載金販狗，利棄我走。藏匿淵底，折悔為咎。",
"51-25":"日中為市，各抱所有。交易貲賄，函珠懷寶，心悅懽喜。",
"51-26":"月步日趍，周遍次舍。經歷致遠，無有難處。",
"51-27":"陽明失時，陰凝為憂。主君哀泣，喪其元侯。",
"51-28":"年衰歲暮，精魄遊去。形容消枯，喪子恩呼。",
"51-29":"少無功績，老困失福。跂行徙𠋣，不知所立。",
"51-30":"持心瞿目，善數搖動。自東徂西，不安其處。散渙府藏，無有利得。",
"51-31":"齎貝贖狸，不聽我辭。繫於虎鬚，牽不得來。",
"51-32":"老狼白獹，長尾大胡。前顛郤躓，無有利得。",
"51-33":"背地相憎，心志不同，如火與金。君猛臣慢，虎行兔伏。",
"51-34":"夏臺牖里，湯文阨處。鬼侯歠醢，歧人悅喜。",
"51-35":"牙孽生齒，螳蜋啟戶。幽人利貞，鼓翼起舞。",
"51-36":"列女無夫，閔思苦憂。齊子無良，使我心愁。",
"51-37":"踐履危難，脫阨去患。入福喜門，見悔大君。",
"51-38":"折臂接手，不能進酒。祈祀閑曠，神怒不喜。",
"51-39":"蟻封戶穴，大雨將集。鵲起數鳴，牝雞歎室。相薨雄父，未到在道。",
"51-40":"胡俗戎狄，太陰所積。固冰𣲨寒，君子不存。",
"51-41":"翕翕䡘䡘，稍頹崩顛。減其令名，身不得全。",
"51-42":"災蟲為賊，害我稼穡。盡禾單麥，秋無所得。",
"51-43":"三幸飛來，自我逢時。俱行先至，多得大利。",
"51-44":"龍馬上山，焦無水泉。喉焦唇乾，渴不能言。",
"51-45":"春生孶乳，萬物繁熾。君子所集，禍災不到。",
"51-46":"王孫季子，相與為友。明允篤誠，升擢薦舉。",
"51-47":"六明並照，政紀有統。秦楚戰國，民受其咎。",
"51-48":"蝃蝀充側，佞人所惑。女謁橫行，正道壅塞。",
"51-49":"登崑崙，入天門。過糟丘，宿玉泉。問惠懽，見欣君。",
"51-50":"體重飛難，未能越關。不啻留垣，上下墟塞。心不遑安。",
"51-51":"枯瓠不朽，利以濟舟。渡踰河海，無有溺憂。",
"51-52":"玄黃虺隤，行者勞罷。役夫憔悴，踰時不歸。",
"51-53":"孔德如玉，出於幽谷。飛上高木，鼓其羽翼，輝光照國。",
"51-54":"火雖熾，在吾後。寇雖眾，出我右。身安居，不危殆。",
"51-55":"旃裘羶國，文禮不飾。跨馬控絃，伐我都邑。",
"51-56":"被𩬊八十，慕德獻服。邊鄙不聳，以安王國。",
"51-57":"心得所好，口常為笑。公孫蛾眉，雞鳴樂夜。",
"51-58":"馬能負乘，見邑之野。并獲粢稻，喜悅無咎。",
"51-59":"高飛視下，貪叨所在。腐臭為患，害於躬身。",
"51-60":"東行西步，失其次舍。乾侯野井，昭君喪居。",
"51-61":"神鳥五采，鳳凰為主。集於山谷，使年歲有。",
"51-62":"石門晨關，荷蕢疾貧。遁世隱居，竟不逢時。",
"51-63":"銅銅齧齧，貧鬼相責。無有懽怡，一日九結。",
"51-64":"白日揚光，雷車避藏。雲雨不行，各止其鄉。",
"52-1":"憂驚巳除，禍不為災，安全以來。",
"52-2":"穿匏挹水，篝鐵燃火。勞罷力竭，飢渴為禍。",
"52-3":"蹇牛折角，不能載粟。災害不避，年歲無榖。",
"52-4":"邑將為虛，居之憂危。",
"52-5":"根刖殘樹，華葉落去。卒逢火焱，隨風僵仆。",
"52-6":"元后貪欲，窮極民力。執政乖㸦，為夷所偪。",
"52-7":"北山有棗，使叔壽考。東領多栗，宜行賈市。陸梁雌雉，所至利害。",
"52-8":"高源峻山，陸土少泉。草木林麓，嘉禾所炎。",
"52-9":"辰次降婁，王駕巡時。廣祐施惠，國安無憂。",
"52-10":"䡘䡘轠轠，歲暮偏弊。寵名損棄，君衰於位。",
"52-11":"放銜委轡，奔亂不制。法度無恒，君失其位。",
"52-12":"獨坐西垣，莫與言笑。秋風多哀，使我心悲。",
"52-13":"脛急股攣，不可出門。暮速歸旅，必為身患。",
"52-14":"情偽難知，使我偏頗。小人在位，雖聖何咎。",
"52-15":"黍稷醇醲，敬奉山宗。神嗜飲食，甘雨嘉降。庶物蕃廡，時無災咎。",
"52-16":"公子王孫，把彈攝丸。發輒有獲，室家饒足。",
"52-17":"陰升陽伏，舜失其室。慈母赤子，相餧不食。",
"52-18":"七竅龍身，造易八元。法則天地，順時施恩。利以長存。",
"52-19":"逐狐東山，水遏我前。深不可涉，失利後便。",
"52-20":"銜命辱使，不堪其事。中墜落去，更為負載。",
"52-21":"溫仁君子，忠孝所在。入閨為儀，禍菑不處。",
"52-22":"春多膏澤，夏潤優渥。稼穡成熟，畝獲百斛。師行失律，霸功不遂。",
"52-23":"二女共室，心不聊食。首𩬊如蓬，憂常在中。",
"52-24":"築關石顛，立本泉源。疾病不安，老狐為鄰。",
"52-25":"欲避凶門，反與禍鄰。顛覆不制，痛薫我心。",
"52-26":"踧行竊視，有所畏避。狸首伏藏，以夜為利。",
"52-27":"八面九口，長舌為斧。劈破瑚璉，殷商絕後。",
"52-28":"和氣相薄，膏澤津液，生我嘉榖。",
"52-29":"消金厭兵，雷車不行，民安其鄉。",
"52-30":"秦儀機言，解其國患。一說燕下，齊襄以權。",
"52-31":"旦奭王輔，周德孔明。越裳獻雉，萬國咸康。",
"52-32":"弱足刖跟，不利出門。賈市無盈，折亡為患。",
"52-33":"堅冰黃鳥，帝哀悲愁。不見白粒，但睹藜蒿。數驚鷙鳥，為我心憂。",
"52-34":"魂微惙惙，屬纊聽絕，曠然大通，復更生活。",
"52-35":"陰生獐鹿，鼠舞鬼哭。靈龜墜處。雨甑草生，仁知敗國。桀亂無緒。",
"52-36":"諸石攻玉，無不穿鑿。龍體具舉，魯班為輔。麟鳳成形，德象君子。",
"52-37":"山作天時，陸為海口，民不安處。",
"52-38":"東風啟戶，隱伏歡喜。萌庶蒙恩，復得我子。",
"52-39":"華燈百枝，稍暗衰微。精光欲盡，奄如灰靡。",
"52-40":"三十無室，寄宿桑中。上宮長女，不得來同，使我失期。",
"52-41":"卵與石鬥，麋碎無疑。動而有悔，出不得時。",
"52-42":"秦兵爭強，失其貞良。敗於殽鄉。",
"52-43":"虎除善猛，難為攻醫。驥窮塩車，困於銜箠。",
"52-44":"操笱搏狸，荷弓射魚。非其器用，自令心勞。",
"52-45":"葵丘之盟，晉獻會行。見太宰辭，復為還輿。",
"52-46":"臏詐龐子，夷灶盡毀。兵伏卒發，矢至如雨。魏師驚亂，將獲為虜。㳙死樹下。",
"52-47":"南行出城，世得天福。王姬歸齊，賴其所欲。",
"52-48":"冬采微蘭，地凍堅難。利走室北，暮無所得。",
"52-49":"王僑無病，狗頭不痛。亡𡲆失履，乏我送從。",
"52-50":"宛馬疾步，盲師坐御。目不見路，中宵不到。",
"52-51":"求利難國，亡去我北。憂歸其城，反為吾賊。",
"52-52":"君孤獨處，單弱無輔。名曰困苦。",
"52-53":"比目四翼，安我邦國。上下無患，為吾喜福。",
"52-54":"八材既登，以成股肱。厖降庭堅，國無災凶。",
"52-55":"稍弊穿空，家莫為宗。為身作凶。",
"52-56":"鳥舞國城，邑懼卒驚。仁德不修，為下所傾。",
"52-57":"三榖不熟，民苦困急。亟之南國，嘉樂有得。",
"52-58":"黃裳建元，福德在身。祿祐洋溢，封為齊君。賈市無門，富寶多餐。",
"52-59":"齊東郭廬，嫁於洛都。驪婦美好，利得過倍。",
"52-60":"安床厚褥，不得久宿。棄我嘉宴，困於南國。𭠘抒之憂，不成禍災。",
"52-61":"內崩身傷，中亂無常。雖有美粟，不我食得。",
"52-62":"出門逢患，與禍為怨。更相擊刺，傷我指端。",
"52-63":"出入節時，南北無憂。行者函至，在外歸來。",
"52-64":"公孫駕驪，載游東齊。延陵說產，遺季紵衣。",
"53-1":"旦種菽豆，暮成藿羮。心之所願，志快意愜。",
"53-2":"杜飛門啟，憂患大解，不為身禍。",
"53-3":"東山西山，各自止安。雖相登望，竟未同堂。",
"53-4":"眾鳥所翔，中有大怪，九身無頭，魂驚魄去，不可以居。",
"53-5":"交侵如亂，民無聊賴。追我濟西，敵人破陣。",
"53-6":"麟鳳所翔，國無咎殃。賈市十倍，復歸惠鄉。",
"53-7":"鑿井求玉，非卞氏室。身困名辱，勞無所得。",
"53-8":"文山鴻豹，肥腯多脂。王孫獲願，載福巍巍。",
"53-9":"周成之隆，刑錯除凶。太宰費石，君子作人。",
"53-10":"珪璧琮璜，執贄見王。百里寗戚，應聘齊秦。",
"53-11":"穿空漏徹，破壞我缺。陶弗能治，瓦甓不鑿。",
"53-12":"鴻飛循陸，公出不復。伯氏客宿。",
"53-13":"蝦蟆群聚，從天請雨。雲雷運集，應其願所。",
"53-14":"老弱無子，不能自理。為民所憂，終不離咎。",
"53-15":"蟠梅折枝，與母別離。絕不相知。",
"53-16":"盛中不絕，衰者復掇。盈滿減虧，痴蠡肥腯。鄭昭失國，重耳興立。",
"53-17":"聞虎入邑，必欲逃匿。無據易德，不見藿菽。終無憂慝。",
"53-18":"隨時逐便，不失利門。多獲得福，富於封君。",
"53-19":"禹作神鼎，伯益銜指，斧斤既折，撞立獨𠋣。賣萬不讎，枯槁為禍。",
"53-20":"春鴻飛東，以馬𧵍金。利得十倍，重載歸鄉。",
"53-21":"金齒鐵牙，壽考宜家。年歲有儲，貪利者得，雖憂無咎。",
"53-22":"膏澤沐浴，洗去汙辱。振除災咎，更與福處。",
"53-23":"履階登墀，高登峻巍。福祿洋溢，依天之威。",
"53-24":"坤厚地德，庶物蕃息。平康正直，以綏大福。",
"53-25":"絕域異路，多所畏惡。使我驚懼，思吾故處。",
"53-26":"襁褓孩幼，冠帶成家。出門如賓，父母何憂。",
"53-27":"一尋百節，綢繆相結。其指詰詘，不能解脫。",
"53-28":"鷹鸇獵食，雉兔困急。逃頭見尾，為害所賊。",
"53-29":"危坐至暮，請求不得。膏澤不降，政戾民惑。",
"53-30":"剛柔相呼，二姓為家。霜降既同，惠我以仁。",
"53-31":"慈母念子，饗賜得士。蠻夷來服，以安王國。",
"53-32":"良夫孔悝，脅悝登臺。樂季不扶，衛輒走逃。",
"53-33":"子長忠直，李氏為賊。禍及無嗣，司馬失福。",
"53-34":"節度之德，不涉亂國。雖昧無光，後大受慶。",
"53-35":"驅羊南行，與禍相逢。狼驚我馬，虎盜我子。悲恨自咎。",
"53-36":"尼父孔丘，善釣鯉魚。羅釣一舉，得獲萬頭，富我家居。",
"53-37":"大根不固，華葉落去，更為孤嫗。",
"53-38":"設𦊙捕魚，反得居諸。員困竭忠，伍氏夷誅。",
"53-39":"敏捷極疾，如猿集木。彤弓雖調，終不能獲。",
"53-40":"冠帶南遊，與福相期。徼於嘉國，拜為逢時。",
"53-41":"年豐歲熟，政仁民樂，祿人獲福。",
"53-42":"築闕石顛，立基泉源。疾病不安，老孤無鄰。",
"53-43":"逐狐東山，水遏我前。深不可涉，失利後便。",
"53-44":"麟子鳳雛，生長嘉國。和氣所居，康樂溫仁，邦多聖人。",
"53-45":"西行求玉，冀得瑜璞。反得凶惡，使我驚惑。",
"53-46":"心狂老悖，聽視聾盲。正命無常，下民多孽。",
"53-47":"南國少子，才略美好。求我長女，賤薄不與。反得醜惡，後乃大悔。",
"53-48":"逶迤高原，家伯妄施。亂其五官。",
"53-49":"謝恩拜德，東歸吾國，歡樂有福。",
"53-50":"雞鳴同舉，思配無家。執珮持鳧，無所致之。",
"53-51":"凶重憂累，身受誅罪。神不能解。",
"53-52":"虎豹熊罷，遊戲山谷。仁賢君子，得其所欲。",
"53-53":"別離分散，長子從軍。稚叔就賊，寡老獨居。莫為種瓜。",
"53-54":"海隅遼右，福祿所在。柔嘉蒙祉，九夷何咎。",
"53-55":"華首之山，仙道所遊。利以居止，長無咎憂。",
"53-56":"甲乙戊庚，隨時轉行。不失常節，萌牙律屈，咸達生出，各樂其類。",
"53-57":"跛躓未起，失利後市。不得鹿子。",
"53-58":"怙恃自負，不去於下。血從地出，誅罰失理。",
"53-59":"江河淮海，天之都市。商人受福，國家饒有。",
"53-60":"節情省慾，賦歛有度。家給人足，利以富貴。",
"53-61":"牝牛鳴㕼，呼求其潦。雲雨大會，流成河海。",
"53-62":"日月之塗，所行必到，無有患故。",
"53-63":"乘風而舉，與飛鳥俱。一舉千里，見吾愛母。",
"53-64":"陰醜陽爭，臥木反立。君子攸行，喪其官職。",
"54-1":"荊木冬生，司寇緩刑。威權在下，國亂且順。",
"54-2":"喘牛傷暑，弗能成畝。草莱不闢，年歲無有。",
"54-3":"魚欲負流，眾不同心。至德安樂。",
"54-4":"春耕有息，秋入利福。獻豜大豵，以樂成功。",
"54-5":"生有聖德，上配太極。皇靈建中，授我以福。",
"54-6":"右撫琴頭，左手援帶。凶訟不巳，相與爭戾，失利而歸。",
"54-7":"炙魚枯斗，張伺夜鼠。舌不忍味，機發為祟，笇不得去。",
"54-8":"申酉說服，牛馬休息。君子以安，勞者得懽。",
"54-9":"堯門尹爵，聖德增益。使民不疲，安無怵愓。",
"54-10":"孤公寡婦，獨宿悲苦。目張耳鳴，莫與笑語。",
"54-11":"外得好畜，相與嫁娶。仁賢集聚，諮詢厥事。傾奪我城，使家不寧。",
"54-12":"煎砂盛暑，鮮有不朽。去河三里，敗我利市。老牛盲馬，去之何悔。",
"54-13":"甲乙戊庚，隨時轉行，不失常節，萌牙律屈。咸達出生，各樂其類。",
"54-14":"依宵夜遊，與君相遭。除解煩惑，使心不憂。",
"54-15":"死友絕朋，巧言為讒。覆白汙玉，顏叔哀喑。",
"54-16":"逐利三年，利走如神。糧轉東西，如鳥避丸。",
"54-17":"隄防壞決，河水放逸。傷害稼穡，居孤獨宿，沒溺我邑。",
"54-18":"陰陽隔塞，許嫁不荅。旄丘新臺，悔往歎息。",
"54-19":"伯夷叔齊，貞廉之師。以德防患，憂禍不存。",
"54-20":"陽為狂悖，拔劍自傷，為身生殃。",
"54-21":"進士為官，不若服田。獲壽保年。",
"54-22":"耕石不生，棄禮無名。縫衣失針，𥜗褲弗成。",
"54-23":"靈龜陸處，一旦失所。伊子復耕，桀亂無輔。",
"54-24":"室當源口，溺漂為海。財產單盡，食衣無有。",
"54-25":"雞方啄粟，為狐所逐。走不得食，惶懼喘息。",
"54-26":"家在海隅，繞旋深流。豈敢憚行，無木以趨。",
"54-27":"他山之儲，與環為仇。來攻我城，傷我飢膚。國家騷憂。",
"54-28":"弊鏡無光，不見文章。少女不嫁，棄於其公。",
"54-29":"大蛇巨魚，相搏於郊。君臣隔塞，郭公出廬。",
"54-30":"絕世無嗣，福祿無存。精神渙散，離其躬身。",
"54-31":"文君之德，養仁致福。年無胎夭，國富民實。憂者之望，增參盜息。",
"54-32":"合歡之國，喜為我福。東嶽南山，朝躋成息。",
"54-33":"憂人之患，履悖易顏。為身禍殘。率身自守，與喜相抱。長子成老，封受福祉。",
"54-34":"太公避紂，七十隱處。卒受聖文，為王室輔。",
"54-35":"江漢上流，政逆民憂。陰伐其陽，雌為雄公。",
"54-36":"縮緒亂絲，舉手為災。越畝逐兔，喪其衣褲。",
"54-37":"臭彘腐水，與狼相輔。亡夫失子，憂及父母。",
"54-38":"刲羊不當，女執空筐。兔跛鹿踦，縁山墜墮，讒佞亂作。",
"54-39":"拔劍傷手，見敵不善。良臣無佐，國憂為咎。",
"54-40":"三羖五牂，相隨俱行。迷入空澤，循谷直北，經涉六駁，為所傷賊。",
"54-41":"爭雞失羊，亡其金囊，利得不長。陳蔡之患，賴楚以安。",
"54-42":"三驪負銜，南芷取香。秋蘭芬馥，盈滿神匱，利我仲季。",
"54-43":"孟夏巳丑，哀呼尼父。明德訖終，亂虐兹起。",
"54-44":"履不容足，南山多革。家有芳蘭，乃無病疾。",
"54-45":"三足無頭，弗知所之。心強睛傷，莫使為明，不見月光。",
"54-46":"戴堯扶禹，松喬彭祖。西過王母，道里夷易，無敢難者。",
"54-47":"式微式微，憂禍相絆。隔以嵓山，室家分散。",
"54-48":"靈龜陸處，一旦失所。伊子復耕，桀亂無輔。",
"54-49":"仁德覆洽，恩及異域。澤被殊方，禍災隱伏。蚕不作室，寒無所得。",
"54-50":"夏麥扶䵃，霜擊其芒。疾君敗國，使年夭傷。",
"54-51":"火雖熾，在吾後。寇雖多，出我右。身安吉，不危殆。",
"54-52":"遠遼絕路，客宿多悔。頑囂相聚，生我畏惡。",
"54-53":"懸懸南海，去家萬里。飛兔褭駿，一日見母。除我憂悔。",
"54-54":"堅冰黃裳，鳥哀悲愁。不見白粒，但睹藜蒿。數驚鷙鳥，為我心憂。",
"54-55":"困而後通，雖危不窮。終得其願，姬姜相從。",
"54-56":"西賈巴蜀，寒雪至轂。欲前不得，還反室屋。",
"54-57":"作新初陵，爛陷難登。三駒摧車，躓頓傷頤。",
"54-58":"延頸望酒，不入我口。深目自苦，利得無有。幽人悅喜。",
"54-59":"仲春孟夏，和氣所舍。生我喜福，國無殘賊。",
"54-60":"張羅捕鳩，兔離其災。雌雄俱得，為置所賊。",
"54-61":"三人俱行，一人言北。伯仲欲南，少叔不得。中路分爭，道鬥相賊。",
"54-62":"然諾不行，欺紿誤人。使我露宿，夜歸溫室。神怒不直，鬼欲求獨。刺擊其目，反言自賊。",
"54-63":"陳辭達誠，使安不傾。增祿益壽，以成功名。",
"54-64":"火燒公床，破家滅亡。然得安昌，先憂重喪。",
"55-1":"鼎足承德，嘉謀生福。為王開庭，得心所欲。",
"55-2":"曳綸河海，釣挂魴鯉。王孫利得，以饗仲友。",
"55-3":"東山皋洛，畔逆不服。興師征討，恭子敗覆。",
"55-4":"千里騂駒，為王服車。嘉其麗榮，君子有成。",
"55-5":"二龍北行，道逢六狼。暮宿中澤，為禍所傷。",
"55-6":"天災所遊，凶不可居。轉徙獲福，留止危憂。",
"55-7":"狐狸雉兔，畏人逃去。分走竄匿，不如所處。",
"55-8":"雨師娶婦，黃巖季女成。禮既婚，相呼南去。膏潤下土，年歲大有。",
"55-9":"外栖野鼠，與雞為伍。瘡痍不息，即去其室。",
"55-10":"夭命絕後，孤傷無主。彷徨兩社，獨不得酒。",
"55-11":"鵠思其雄，欲隨鳳東。順里羽翼，出次須日。中苗北邑，復反其室。",
"55-12":"蜲蛇九子，長尾不殆。均明光澤，燕自受福。",
"55-13":"日走月步，趨不同舍。夫妻反目，君主失國。",
"55-14":"宣房戶室，枯期除毒。文德淵府，害不能賊。",
"55-15":"齊東郭盧，嫁於洛都。駿艮美好，謀利過倍。",
"55-16":"病篤難醫，和不能治。命終期訖，下即蒿里。",
"55-17":"開廓緒業，王跡所起。姬德七百，報以八子。",
"55-18":"豐年多儲，江海饒魚。商客善賈，大國富有。",
"55-19":"鵠求魚食，過彼射邑。矰加我頭，繳掛羽翼。欲飛不能，為羿所得。",
"55-20":"望城抱子，見邑不殆。公孫上堂，大君歡喜。",
"55-21":"左指右麾，邪淫侈靡。執節無良，靈公以亡。",
"55-22":"日中為市，各持所有。交易資賄，函珠懷寶。",
"55-23":"山沒丘浮，陸為水魚。鷰雀無廬。",
"55-24":"馬服長股，宜行善市。蒙祐諧偶，獲利五倍。終日在市，詰朝獲利。既享嘉福，得之以義。",
"55-25":"三狸捕鼠，遮遏前後。死於環域，不得脫走。",
"55-26":"鬼舞國社，歲樂民喜。臣忠於君，子孝於父。",
"55-27":"慈母望子，遙思不巳。久客外野，我心悲苦。",
"55-28":"雨師娶婦，黃巖季子。成禮既婚，相呼南去。膏潤下土，年歲大有。",
"55-29":"百狗同室，相嚙爭食。枉矢西流，射我暴國。高宗鬼方，三年乃服。",
"55-30":"早霜晚雪，傷害禾麥。捐功棄力，飢無可食。",
"55-31":"腐臭所在，青蠅集聚。辯變白黑，敗亂邦國。君為臣逐，失其寵祿。",
"55-32":"牽羊不與，心戾旋聞。言語不畜，誤紹丈人。",
"55-33":"甘忍利瘧，還相克賊。商子造刑，鞭喪厥身。",
"55-34":"刲羊不當，女執空筐。",
"55-35":"齗齗齒齒，貧鬼相責。無有歡怡，一日九結。",
"55-36":"兩足四翼，飛入嘉國。寧我伯姊，子母相得。",
"55-37":"文山紫芝，雍梁朱草。生長和氣，王以為寶。公屍侑食，福祿未處。",
"55-38":"絕世遊魂，福祿不存。精神渙散，離其躬身。",
"55-39":"北辰紫宮，衣冠立中。含和建德，常受大福。",
"55-40":"伯蹇叔瘖，莫與守株。矢我衣裘，代爾陰鄉。",
"55-41":"兩女共室，心不聊食。首髪如蓬，憂常在中。",
"55-42":"去辛就蓼，毒愈苦甚，避阱遇坑，憂患日生。",
"55-43":"初病終凶，季為死喪，不見光明。",
"55-44":"三鳥飛來，自到逢時。俱行先至，多得大利。",
"55-45":"鹿食山草，不思邑里，雖久無咎。",
"55-46":"羊腸九縈，相推稍前。止須王孫，乃能上天。",
"55-47":"管仲遇桓，得其願懽。膠牢振寇，寇帶無憂。笑戲不莊，空言妄行。",
"55-48":"桀跖並處，民困愁苦。行旅遲遲，留連齊魯。",
"55-49":"魂孤無室，銜指不食。盜張民餌，見敵失福。",
"55-50":"讒言亂國，覆是為非。伯奇乖難，㳟子憂哀。",
"55-51":"衛侯東遊，惑於少姬。亡我考妣，久迷不來。",
"55-52":"雞鳴同興，思邪無家。執珮持鳧，莫使致之。",
"55-53":"義不勝情，以欲自榮。覬利危寵，摧角折頸。",
"55-54":"臣尊主卑，擁力日衰。侵奪無光，三家逐公。",
"55-55":"諸孺行賈，經涉大阻。與杖為市，不憂危殆，利得十倍。",
"55-56":"叔仲善賈，與喜為市。不憂危殆，利得十倍。",
"55-57":"六蛇奔走，俱入茂草。驚於長路，畏懼啄口。",
"55-58":"水壞我里，東流為海。鳧鼃讙囂，不得安居。",
"55-59":"飛不遠去，卑斯內侍，祿養未富。",
"55-60":"陰變為陽，女化為男。治道大通，君臣相承。",
"55-61":"踐履危難，脫厄去患。入福喜門，見誨大君。",
"55-62":"𦊙宻網縮，動益蹶急，困不得息。",
"55-63":"負牛上山，力劣行難。烈風雨雪，遮遏我前。中道復還。",
"55-64":"喁喁嘉草，思降甘雨。景風升上，沾洽時澍，生我禾稼。",
"56-1":"寄生無根，如過浮雲。立本不固，斯須落去。更為枯樹。",
"56-2":"人無定，法緩降。牛出蛇，雄走趍。陽不制陰，宜其家國。",
"56-3":"眾鳥所聚，中有大怪，九身無頭。魂驚魄去，不可以居。",
"56-4":"封豕溝瀆，灌潰國邑。火宿口中，民多疾病。",
"56-5":"奮翅鼓翼，翱翔外國。逍遙徙𠋣，來歸溫室。",
"56-6":"秋蚕不成，冬種不生。殷王逆理，棄其寵榮。",
"56-7":"衛侯東遊，惑於少姬。忘我考妣，久迷不來。",
"56-8":"鳥合卒會，與惡相得。鴟梟相酬，為心所賊。",
"56-9":"鳴雞無距，與鵲格鬥。翅折目盲，為仇所傷。",
"56-10":"木生內蠹，下上相賊，禍亂我國。",
"56-11":"延陵適魯，觀樂太史。車驎白顛，知秦興起。卒兼其國，一統為主。",
"56-12":"輔相之好，無有休息。時行雲集，所在遇福。",
"56-13":"床傾簀折，屋漏垣缺。季姬不愜。",
"56-14":"東入海口，循流北走。一高一下，五色無主。七日六夜，死於水浦。",
"56-15":"群需入邑，求索肉食。大人御守，君不失國。",
"56-16":"四亂不安，東西為患。退身止足，無出邦域。乃得完全，賴其生福。",
"56-17":"叔肹抱冤，祁子自邑，乘道解患。羊舌以免，賴其福全。",
"56-18":"延頸望酒，不入我口。深目自苦，利得無有。",
"56-19":"仁政之德，㳟㳟日息。成都就邑，人受厥福。",
"56-20":"牽頭繫尾，詘折幾死。周世無人，不知所歸。",
"56-21":"教羊逐兔，使魚相捕。任非其人，費日無功。",
"56-22":"生角有尾，張孽制家，排羊逐狐。張氏易公，憂禍重凶。",
"56-23":"去安就危，墜陷井池，破我玉瑀。",
"56-24":"茹芝餌黃，塗飲玉英。與神流通，長無憂凶。",
"56-25":"體重飛難，未能越關。",
"56-26":"巢成樹折，傷我彜器。伯踒叔跌，亡羊乃追。",
"56-27":"六人俱行，各遺其囊。黃鵠失珠，無以為明。",
"56-28":"蟠梅折枝，與母分離，絕不相知。",
"56-29":"迎福開戶，喜隨我後。曹伯愷悌，為宋國主。",
"56-30":"既痴且狂，兩目又盲。踑踞啞喑，名為無中。",
"56-31":"金梁鐵柱，千年牢固。完全不腐，聖人安處。",
"56-32":"裹糗荷糧，與跖相逢。欲飛不得，為罔所獲。",
"56-33":"彭名為妖，暴龍作災。盜堯衣裳，聚跖荷兵。青禽照夜，三旦夷亡。",
"56-34":"獨夫老婦，不能生子，鰥寡俱處。",
"56-35":"鷦鷯竊脂，巢於小枝。搖動不安，為風所吹。心寒漂搖，常憂危殆。",
"56-36":"素車木馬，不任負重。王子出征，憂危為咎。",
"56-37":"土陷四維，安平不危。利以居止，保有玉女。",
"56-38":"負牛上山，力劣行難。烈風雨雪，遮遏我前，中道復還。",
"56-39":"金城鐵郭，上下同力。政平民親，寇不敢賊。",
"56-40":"清潔淵塞，為人所言。證訊詰問，繫於枳溫。甘棠聽斷，昭然蒙恩。",
"56-41":"皋陶聽理，岐伯悅喜。西登華道，東歸無咎。",
"56-42":"低頭竊視，有所畏避，行作未利。酒酸魚敗，眾莫貪嗜。",
"56-43":"十雉百雛，常與母俱。抱雞搏虎，誰肯為侶。",
"56-44":"高阜山陵，陂陀顛崩。為國妖祥，元后以薨。",
"56-45":"六鷁退飛，為衰敗祥。陳師合戰，左股夷傷。遂以薨崩，霸功不終。",
"56-46":"異國殊俗，情不相得。金木為仇，百戰檀轂。",
"56-47":"鵶呌庭中，以戒災凶。重門擊柝，備憂暴客。",
"56-48":"慈母赤子，饗賜得仕，獲夷服除，以安王家，側陋逢時。",
"56-49":"剗跡惡人，使德不通。炎旱為災，年榖大傷。",
"56-50":"躬履孔德，以待束帶。文君燎獵，呂尚獲福。號稱太師，封建齊國。",
"56-51":"征將止惡，皷鞞除賊。慶仲奔莒，子般獲福。",
"56-52":"良夫淑女，配合相保。多孫眾子，懽樂長久。",
"56-53":"蜲蛇四牡，思念父母。王事靡盬，不我安處。",
"56-54":"水壞我里，東流為海。鳧龜讙囂，不得安居。",
"56-55":"束帛戔戔，賻我孟宣。徵召送君，變號易字。",
"56-56":"羅網四張，鳥無所翔。征伐困極，飢窮不食。",
"56-57":"乾行天德，覆贍六合。嘔呴成熟，使我福德。",
"56-58":"秦晉大國，更相克賊。獲惠質圉，鄭被其咎。",
"56-59":"晦昧昏明，君無紀網。甲子成亂，簡公喪亡。",
"56-60":"三足無頭，弗知所之。心狂精傷，莫使為明，不見月光。",
"56-61":"長夜短日，陰為陽賊。萬物空枯，藏在北陸。",
"56-62":"依宵夜遊，與大君俱。除解煩惑，使我無憂。",
"56-63":"逐麋西山，利入我門。陰陽和調，國無災殘。長子出遊，須其仁君。",
"56-64":"請冀左耳，嗇不我驅，與我父母。",
"57-1":"采唐沬鄉，要期桑中。失信不會，憂思約帶。",
"57-2":"有鳥飛來，集于宮樹。鳴聲可畏，主將出去。",
"57-3":"仁政之德，參參日息。成都就邑，入受厥福。",
"57-4":"他山之儲，與璆為仇。來攻吾城，傷我肌膚。邦家搔憂。",
"57-5":"齎貝贖狸，不聽我辭。繫於虎鬚，牽不得來。",
"57-6":"一簧兩舌，妄言謟語。三姦惑虛，曾母投杼。",
"57-7":"薄行搔尾，逐雲除水。汙泥為陸，下田宜稷。",
"57-8":"天門九重，深內難通。明坐至暮，不見神公。",
"57-9":"闇目失明，耳閼聽聰。陷入深淵，滅頃憂凶。",
"57-10":"霧露早霜，日闇不明。陰陽孽疾，年榖大傷。",
"57-11":"三諧土廊，德義明堂。交譲往來，享讌相承。箕伯朝王，錫我玄黃。",
"57-12":"爭雞失羊，利得不長。陳蔡之患，賴楚以安。",
"57-13":"天旱水涸，枯槁無澤，未有所獲。",
"57-14":"陶朱白珪，善賈息資。公子王孫，富利不貧。",
"57-15":"龜厭江海，陸行不止，自令枯槁，失其都市，憂悔為咎。",
"57-16":"黃鳥採蓄，既稼不荅。念吾父兄，思復邦國。",
"57-17":"田鼠野雛，意常欲逃。拘制籠檻，不得動搖。",
"57-18":"平國不君，夏氏作亂。烏號竊發，靈公殞命。",
"57-19":"巨蛇大鰍，戰於國郊。上下閉塞，君道走逃。",
"57-20":"讒言亂國，覆是為非。伯奇流離，恭子憂哀。",
"57-21":"鬱映不明，為陰所傷。眾霧集聚，共奪日光。",
"57-22":"望城抱子，見邑不殆。公孫上堂，大君歡喜。",
"57-23":"三虫作蠱，剗跡無與。勝母盜泉，君子弗處。",
"57-24":"車馳人趍，卷甲相求。齊魯寇戎，敗於犬丘。",
"57-25":"欲訪子車，善相欺詒，桓叔相迎，不見所期。",
"57-26":"爭雞失羊，亡其金囊，利得不長。陳蔡之患，賴楚以安。",
"57-27":"歲暮華落，陽入陰室。萬物伏藏，匿不可得。",
"57-28":"晨風文翮，大舉就溫。過我城邑，羿無所得。",
"57-29":"時鵠抱子，見蛇何咎。室家俱在，不失其所。",
"57-30":"隱隱大雷，霶霈為雨。有女痴狂，驚駭鄰里。",
"57-31":"無足斷跟，居處不安，凶惡為患。",
"57-32":"破筐弊莒，棄捐於道，不復為寶。",
"57-33":"三雞啄粟，十雛從食。飢鳶卒擊，亡其兩叔。",
"57-34":"乘車七百，以明文德。踐土葵丘，齊晉受福。",
"57-35":"百足俱行，相輔為強。三聖翼事，王室寵光。",
"57-36":"典冊法書，藏閣蘭臺。雖遭潰亂，獨不逢災。",
"57-37":"四誅不服，恃強負力。倍道趨敵，師徒敗覆。",
"57-38":"春陽生草，夏長條肄。萬物蕃滋，充實益有。",
"57-39":"磝磝禿白，不生黍稷。無以供祭，祇靈乏祀。",
"57-40":"褰衣涉河，水深漬罷。賴幸舟子，濟脫無他。",
"57-41":"宜行賈市，所求必倍。戴喜抱子，與利為友。",
"57-42":"兄征東夷，弟伐遼西。大克勝還，封君河間。",
"57-43":"初雖驚惶，後乃無傷。受其福慶。",
"57-44":"隨風乘龍，與利相逢。田獲三倍，商旅有功。憧憧之邑，長安無他。",
"57-45":"魚擾水濁，寇圍吾邑。城危不安，驚恐狂惑。",
"57-46":"雖窮復通，履危不凶，保其明公。",
"57-47":"坤厚地德，庶物蕃息。平康正直，以綏大福。",
"57-48":"山水暴怒，壞梁折柱。稽難行旅，留連愁苦。",
"57-49":"使鷰築室，身不庇宿。家無聊賴，殱我衣服。",
"57-50":"矢石所射，襄公痢劇。吳子巢門，傷病不治。",
"57-51":"日月運行，一寒一暑。榮寵赫赫，不可得保。顛隕墜墮，更為士伍。",
"57-52":"宮門愁鳴，臣圍其君，不得東西。",
"57-53":"戴甕望天，不見星辰。顧小失大，福逃墻外。",
"57-54":"天之所明，禍不遇家。反自相逐，終得和鳴。",
"57-55":"天陰霖雨，塗行泥潦。商人休止，市無所有。",
"57-56":"嘉門福喜，增累盛熾。日就有德，宜民宜國。",
"57-57":"溫山松桓，常茂不落。鸞鳳以庇，得其懽樂。",
"57-58":"南山之陽，華葉將將。喜樂君子，為國寵光。",
"57-59":"畫龍頭頸，文章未成。甘言美語，說辭無名。",
"57-60":"嬰兒孩子，未有所識。彼童而角，亂我正事。",
"57-61":"陰作大姦，欲君勿言。鴻鵠利口，發患禍端。荊季懷憂，張伯被患。",
"57-62":"德之流行，利之四鄉。雨師洒道，風伯逐殃。巡狩封禪，以告成功。",
"57-63":"禹將為君，裝入崑崙。稍進陽光，登見溫湯。功德昭明。",
"57-64":"五岳四瀆，含潤為德。行不失理，民賴㤙福。",
"58-1":"踐履危難，脫厄去患。入福喜門，見悔大君。",
"58-2":"子鉏執麟，春秋作元。陰聖將終，尼父悲心。",
"58-3":"夾河為婚，期至無舡。搖心失望，不見所懽。",
"58-4":"天孫帝子，與日月處。光榮於世，福祿祉祉。",
"58-5":"三人爭妻，相隨奔馳。終日不食，精氣勞罷。",
"58-6":"禹召諸侯，會稽南山。執玉萬國，天下康寧。",
"58-7":"早霜晚雪，傷害禾麥。捐功棄力，飢無所食。",
"58-8":"嵩融持㦸，杜伯荷弩。降觀下國，誅逐無道。夏商之季，失勢外走。",
"58-9":"生有聖德，上配大極。皇靈建中，受我以福。",
"58-10":"下田陸黍，萬華生齒。大雨霖集，波病潰腐。",
"58-11":"子畏於匡，困厄陳蔡。明德不危，竟剋免害。",
"58-12":"有兩赤頭，從五岳來。謠言無祐，趍爾之林。俯伏聽命，不敢動搖。",
"58-13":"當得自如，不逢凶災。衰者復興，終無禍來。",
"58-14":"朽根刖樹，華葉落去。卒逢大焱，隨風偃仆。",
"58-15":"葛生衍蔓，絺綌為願。家道篤厚，父兄悅喜。",
"58-16":"東行求玉，反得弊石。名曰無直，字曰醜惡，眾所賤薄。",
"58-17":"瞻白因絃，駑孱恐怯。任力墮劣，如蝟見鵲。偃視恐伏，不敢拒格。",
"58-18":"瘡痍多病，宋公危殆。吳子巢門，無命失所。",
"58-19":"東山西岳，會合俱食。百喜送從，以成恩福。",
"58-20":"舞非其處，失節多悔，不合我意。",
"58-21":"南循汝水，茂樹斬枝。過時不遇，㑂如旦飢。",
"58-22":"公孫駕驪，載遊東齊。延陵說產，遺我紵衣。",
"58-23":"乘輿八百，以明文德。踐土葵丘，齊晉受福。",
"58-24":"雄處弱水，雌在海邊。別離將食，哀悲於心。",
"58-25":"結網得解，受福安坐。終無患禍。",
"58-26":"秋南春北，隨時休息。處和履中，安無憂凶。",
"58-27":"啟戶開門，巡狩釋冤。夏臺牖里，湯文悅喜。",
"58-28":"符左𢍆右，相與合齒。乾坤利貞，乳生六子。長大成就，風言如母。",
"58-29":"飢蚕作室，絲多亂緒，端不可得。",
"58-30":"東壁飾光，數闇不明。主母嫉妒，亂我業事。",
"58-31":"白茅縮酒，靈巫拜禱。神嗜飲食，使君壽考。",
"58-32":"范公陶夷，巧賈貨資。東之營丘，易字子皮。抱珠載金，多得利歸。",
"58-33":"三羖五牂，相隨俱行。迷入空澤，循谷宜北。經涉六駁，為所傷賊。",
"58-34":"雄鵠延頸，欲飛入關。雨師洒道，瀐我袍裘。重車難前，侍者稽止。",
"58-35":"中年蒙慶，今歲受福，必有所得，榮寵受祿。",
"58-36":"祿如周公，建國洛東，父子俱封。",
"58-37":"安床厚褥，不得久宿。棄我嘉讌，困於東國。投杼之憂，不成災福。",
"58-38":"蓄積有餘，糞土不居。",
"58-39":"心願所喜，乃今逢時。得我利福，不离兵革。",
"58-40":"目不可合，憂來搔足。怵愓危懼，去其邦族。",
"58-41":"福德之士，懽悅日喜。夷吾相桓，三歸為臣。賞流子孫。",
"58-42":"夏姬附耳，心聽悅喜。利以傳取。",
"58-43":"叔迎兄弟，遇恭在陽。君子季姬，並坐鼓簧。",
"58-44":"徙巢去家，南遇白鳥。東西受福，與喜相得。",
"58-45":"舜登大禹，石夷之野。徵詣玉闕，拜治水土。",
"58-46":"江河淮海，天之都市。商人受福，國家富有。",
"58-47":"隱隱塡填，火燒山根。不潤我鄰，獨不蒙恩。",
"58-48":"闇昧不明，耳聾不聽。陷入深淵，滅傾凶憂。傾當作頂。",
"58-49":"鳥鳴喈喈，天火將下。燔我館屋，災及妃后。",
"58-50":"十雌百雛，常與母俱。抱雞搏虎，誰敢難者。",
"58-51":"營城洛邑，周公所作。世建三十，年歷七百。福祐盟執，堅固不落。",
"58-52":"三人俱行，別離將食。一身五心，反覆迷惑。",
"58-53":"三虎搏狼，力不相當。如雉鷹格，一發破亡。",
"58-54":"養虎畜狼，還自賊傷。年歲息長，疾君拜禱。雖危不凶。",
"58-55":"後時失利，不得所欲。",
"58-56":"雉兔之東，以理為傷。見鷹驚走，死於谷口。",
"58-57":"秋蛇向穴，不失其節。",
"58-58":"班馬還師，以息勞疲。後夫嘉喜，入戶見妻。",
"58-59":"鳥鳴巢端，壹呼三顛，搖動東西，危魂不安。",
"58-60":"命夭不遂，死多鬼祟，妻子啼瘖，早失其雄。",
"58-61":"茆屋結席，崇我文德。三辰旂旗，家受行福。",
"58-62":"羅網四張，鳥無所翔。征伐困極，飢窮不食。",
"58-63":"天地城安，積石為山，潤洽萬里，人賴其懽。",
"58-64":"銅人鐵柱，暴露勞苦。終日卒歲，無有休止。",
"59-1":"焱風阻越，車馳揭揭。棄古退思，失其和節。心憂惙惙。",
"59-2":"蛇得澤草，不憂危殆。",
"59-3":"兩犬爭鬥，股瘡無處。不成仇讎，行解邪去。",
"59-4":"因禍受福，喜盈其室，求事皆得。",
"59-5":"江多寶珠，海多大魚。疾行亟至，可以得財。",
"59-6":"二牛生狗，以戌為母。荊夷上侵，姬伯出走。",
"59-7":"安息康居，異國穹廬。非吾習俗，使我心憂。",
"59-8":"行觸天罡，馬死車傷。身無聊賴，困窮乞糧。",
"59-9":"臝裎逐狐，為人觀笑。牝雞雄晨，主作亂門。",
"59-10":"為季求婦，家在東海。水長無船，不見所懽。",
"59-11":"男女合室，二姓同食。婚姻孔云，宜室我家。",
"59-12":"太微帝室，黃帝所直。蕃屏周衛，不可得入。常安常存，終無禍患。",
"59-13":"齎金觀市，欲買駵子。猾偷竊發，盜我黃寶。",
"59-14":"三人俱行，欲歸故鄉。望邑入門，拜見家懽。",
"59-15":"娶於姜呂，駕迎新婦。少齊在門，夫子懽喜。",
"59-16":"伯仲旅行，南求大牂。長孟病足，請季負囊。柳下之貞，不失驪黃。",
"59-17":"潔身白齒，衰老復起。多孫眾子，宜利姑舅。",
"59-18":"獨宿憎夜，嫫母畏晝。平王逐建，荊子憂懼。",
"59-19":"追亡逐北，呼還幼叔。至止而得，復歸其室。",
"59-20":"鳥飛無翼，兔走折足。雖欲會同，未得毉功。",
"59-21":"抱空握虛，鳴教我賈，利去不來。",
"59-22":"山作天池，陸地為海。",
"59-23":"為虎所齧，太山之陽。眾多從者，莫敢救藏。",
"59-24":"逶迤四牡，思歸念母。王事靡盬，不得安處。",
"59-25":"獼猴所言，語無成全。誤我白烏，使乾口來。",
"59-26":"飛不遠去，卑斯內侍。祿養未富。",
"59-27":"大尾細要，重不可搖。陰權制國，平子逐昭。旦生夕死，名曰嬰鬼，不可得視。",
"59-28":"旦生夕死，名曰嬰鬼，不可得祀。",
"59-29":"子畏於匡，困在陳蔡。明德不危，竟免危害。",
"59-30":"畏昏潛處，候時昭昭。卒遭白日，為世榮主。",
"59-31":"白烏銜餌，鳴呼其子。施翼張翅，來從其母。",
"59-32":"宮商角徵，五音和起。君臣父子，弟順有敘。唐虞襲德，國無災咎。",
"59-33":"季姬踟躕，望孟城隅。終日至暮，不見齊侯。",
"59-34":"鬼哭於社，悲傷無後。甲子昧爽，殷人絕祀。",
"59-35":"天子所予，福祿常在，不憂危殆。",
"59-36":"比目附翼，相恃為福。姜氏季女，與君合德。",
"59-37":"翕翕䡘䡘，稍崩墮顛。滅其令名。",
"59-38":"折若蔽目，不見稚叔。三足孤鳥，遠去家室。",
"59-39":"羊腸九縈，相推稍前。止須王孫，乃能上天。",
"59-40":"坤厚地德，庶物蕃息。平康正直，以綏大福。",
"59-41":"有萃外野，不逢堯主。復居窮處，心勞志苦。",
"59-42":"胸長景行，來觀桑柘。上伯日喜，都叔允藏。",
"59-43":"周師伐紂，勝於牧野。甲子平旦，天下大喜。",
"59-44":"踰江求橘，并得大栗。烹羊食炙，飲酒歌笑。",
"59-45":"弊笱在梁，魴𨓜不禁。魚父勞苦，筐莒乾口，空虛無有。",
"59-46":"生有陰孽，制家非陽，遂送還床。張氏易公，憂福重凶。",
"59-47":"絕域異路，多有怪惡。使我驚懼，思我故處。",
"59-48":"迷行失道，不得牛馬。百賈逃亡，市空無有。",
"59-49":"雌鷟生雛，祥異興起。束雲龍騰，民戴為父。",
"59-50":"壘壘纍纍，如歧之室。畜一息十，古公始邑。",
"59-51":"瘡瘍疥搔，孝婦不省。君多疣贅，四牡作去。",
"59-52":"羊頭兔足，羸痩少肉。漏囊敗粟，利無所得。",
"59-53":"薛篾從靡，空無誰是。言季子明，樂減少解。",
"59-54":"妹為皃熟，敗君正色。作事不成，自為心賊。",
"59-55":"四馬共轅，東上太山。騂驪同力，無有重難，與君笑言。",
"59-56":"陰變為陽，女化作男。治道得通，君臣相承。",
"59-57":"南國少子，材略美好。求我長女，賤薄不與。反得醜惡，後乃大悔。",
"59-58":"昭公失常，季氏悖狂。遜齊處野，喪其寵光。",
"59-59":"望幸不到，文章未就。王子逐兔，犬踦不得。",
"59-60":"天山紫芝，雍梁朱草。長生和氣，王以為寶。公尸宥食，福祿來處。",
"59-61":"牽羊不前，與心戾旋。聞言不信，誤紿大人。",
"59-62":"東山西山，各自止安。心雖相望，竟未同堂。",
"59-63":"鹿求其子，虎廬之里。唐伯季耳，貪不我許。",
"59-64":"三虎上山，更相喧喚。志心不親，如仇與怒。",
"60-1":"虎呴怒咆，慎戒外憂。上下俱搔，士民無聊。",
"60-2":"探巢得雛，仇鵲俱來，使我心憂。",
"60-3":"日望一食，常恐不足，祿命寡薄。",
"60-4":"良馬疾走，千里一宿。逃難他鄉，誰能追復。",
"60-5":"鵲巢烏城，上下不親，外內乖畔，子走矢頑。",
"60-6":"雲龍集會，征討西戎。招邊定眾，誰敢當鋒。",
"60-7":"春多膏澤，夏潤優渥。稼穡成熟，畝獲百斛。",
"60-8":"童妾獨宿，長女未室，利無所得。",
"60-9":"四亂不安，東西為患，退止我足。無出邦域，乃得全完，賴其生福。",
"60-10":"長寧理福，安我百國。嘉賓上堂，與季同床。",
"60-11":"騏驎騄耳，章明造父。伯夙成季，共成霸功。為晉元輔。",
"60-12":"張陳嘉謀，贊成漢都。主權民喜，其樂休休。",
"60-13":"大面長頸，未解君憂。",
"60-14":"畏昏不行，待旦昭明。燎獵受福，老賴其慶。",
"60-15":"伯去我東，首𩬊知蓬。長夜不𥧌，憂繋心胸。",
"60-16":"朽條腐索，不堪施用。安靜候時，以待親知。",
"60-17":"比目四翼，相𠋣為福。姜氏季氏，與君合德。",
"60-18":"履階昇墀，登高崔嵬。福祿洋溢，依天之威。",
"60-19":"奢淫愛嗇，神所不福。祇靈憑怒，鬼障其室。",
"60-20":"大步小車，南到喜家。送我豹裘，與福載來。",
"60-21":"東行西步，失次後舍。與陂作期，不真至夜。乾侯野井，昭君失居。",
"60-22":"喜樂抃躍，來迎名家。鵲巢百兩，獲利養福。",
"60-23":"非理後來，誰肯相與。往而不獲，徒勞道路。",
"60-24":"北虜匈奴，數侵邊境。",
"60-25":"征不以禮，伐乃無咎。從獲臣子，霸功不成。",
"60-26":"景星照堂，麟遊鳳翔。仁施大行，訟聲作興。",
"60-27":"文明之世，銷鋒鑄鏑。以道順民，百王不易。",
"60-28":"鳥飛無羽，雞鬥折距。徒自長嗟，誰肯為侶。",
"60-29":"群隊虎狼，齧彼牛羊。道路不通，妨農害商。",
"60-30":"商伯沉酒，庶兄奔走。淫女蕩失，仁德並孤。",
"60-31":"三狸搏鼠，遮遏前後。當此之時，不得脫走。",
"60-32":"陶叔孔圉，不處亂國。初雖未萌，後受福慶。",
"60-33":"奮趐鼓翼，翱翔外國。逍遙北域，不入溫室。",
"60-34":"德音孔博，升在王室。八極蒙祐，受其福祿。",
"60-35":"當變立權，𢳣解患難。霍然冰釋，大國以安。",
"60-36":"羽動角甘，雨續草木。茂年歲熟。",
"60-37":"天所祐助，福來禍去，君王何憂。",
"60-38":"方啄宣口，聖智仁厚。釋解倒懸，唐國大安。",
"60-39":"葛藟蒙棘，棘不得實。讒倿亂政，使恩壅塞。",
"60-40":"皇母多恩，字養孝孫。脫於襁抱，成就為君。",
"60-41":"積冰不溫，北陸苦寒。露宿多風，君子傷心。",
"60-42":"伯夷叔齊，貞廉之師。以德防患，憂福不凶。",
"60-43":"一雌二雄，子不知公。亂我族類，使吾心憤。",
"60-44":"主安多福，天祿所伏。居之寵昌，君子有光。",
"60-45":"千歲槐根，利多斧盤。樹維枯屈，枝葉不出。",
"60-46":"周師伐紂，勝殷牧野。甲子平旦，天下大喜。",
"60-47":"日走月步，趍不同舍。夫妻反目，主君失居。",
"60-48":"宣髪龍叔，為王主國。安土成稷，天下蒙恩。",
"60-49":"諷德誦功，周美盛隆。奭旦輔成，光濟沖人。",
"60-50":"三夜不𥧌，憂來益甚。戒以危懼，棄去安居。",
"60-51":"思願所之，乃今逢時。洗澤故憂，拜其懽來。",
"60-52":"噂噂囁囁，夜作晝伏。謀議我資，來竊吾室。",
"60-53":"牛騂亡子，鳴於大野。申復陰徵，還歸其母，說以除悔。",
"60-54":"王良善御，伯樂知馬。周旋步趍，行中規矩。止息有節，延命壽考。",
"60-55":"釋然遠咎，避患害早。田獲三狐，以貝為寶。",
"60-56":"仁獸所處，國無凶咎。市賈十倍，復歸惠里。",
"60-57":"六目俱視，各欲有志。心意不同，乖戾生訟。",
"60-58":"傅說王良，驂御四龍。周徑萬里，無有危凶。",
"60-59":"仲伯季叔，日暮寢醉。醒失期明，喪其貝囊，臥拜道傍。",
"60-60":"海為水王，聰聖且明。百流歸德，無有叛逆，常饒優足。",
"60-61":"江有寶珠，海多大魚。亟行疾至，可以得財。",
"60-62":"遠視千里，不見所持。離婁之明，無益於耳。",
"60-63":"弱足刖跟，不利岀門。市賈無盈，折亡為患。",
"60-64":"利盡得媒，時不我來。鳴雌深涉，寡宿獨居。",
"61-1":"黃虹之野，賢君所在。管叔為相，國無災咎。",
"61-2":"符左契右，梁叔有若，相與合齒。乾坤利貞，乳生六子。長大成就，抛吾如母。",
"61-3":"蝗齧我稻，驅不可去。實穗無有，但見空藁。",
"61-4":"嬰孫求乳，母歸其子，黃麑悅喜。",
"61-5":"折箬蔽目，父旅相逐。失旅亡民，不見衛國。",
"61-6":"牂羊肥首，君子不飽。年飢孔荒，士民危殆。",
"61-7":"靈龜陸處，磐桓失所。伊子退耕，桀亂無輔。",
"61-8":"威約拘囚，為人所誣。皋陶評理，幾得免脫。",
"61-9":"烏升鵲舉，照臨東海。厖降庭堅，為陶叔後。封於英六，福祿綏厚。",
"61-10":"四目相視，稍近同軌。日昳之後，見吾伯姊。",
"61-11":"大步上車，南到喜家。送我狐裘，與福載來。",
"61-12":"卒都和合，未敢面見。媒妁無良，使我不香。",
"61-13":"鴻飛循陸，公出不復。伯氏客宿。",
"61-14":"代戍失期，患生無聊。懼以發難，為我開基，邦國憂愁。",
"61-15":"齊魯爭言，戰於龍門。構怨結禍，三世不安。",
"61-16":"周政養賤，背生人足。陸行不安，國危為患。",
"61-17":"蜩螗懽翹，草木嘉茂。百菓蕃生，日益多有。",
"61-18":"薄災暴虐，風吹雲郤，欲上不得，復歸其宅。",
"61-19":"乘駵駕驪，遊至東齊。遭遇行旅，逆我以資，厚得利歸。",
"61-20":"鳳生七子，同巢共乳，歡悅相保。",
"61-21":"桃雀竊脂，巢於小枝。搖動不安，為風所吹。心寒漂搖，常憂危殆。",
"61-22":"東山西山，各自止安。雖相登望，竟未同堂。",
"61-23":"匍伏走出，驚懼惶恐。白虎生孫，蓐收在後。",
"61-24":"重或射隼，不知所定。質疑蓍龜，明神祭報。告以肥牲，宜利止居。",
"61-25":"開門內福，喜至我側。嘉門善祥，為吾室宅。宮城洛邑，以昭文德。",
"61-26":"鳥飛狐鳴，國亂不寧。下強上弱，為陰所刑。",
"61-27":"三雞啄粟，八雛從食。飢鳶卒擊，失亡兩叔。",
"61-28":"歎息不悅，憂從中出。喪我金嬰，無妄失位。",
"61-29":"剛柔相呼，三姓為家。霜降既同，惠我以仁。",
"61-30":"送我季女，至于蕩道。齊子旦夕，久留連處。",
"61-31":"低頭竊視，有所遇避。行作不利，酒酢魚餒，眾莫貪嗜。",
"61-32":"典冊法書，藏閣蘭臺。雖遭亂潰，獨不逢災。",
"61-33":"旦醉病酒，暮多瘳愈，不反為咎。",
"61-34":"畫龍頭頸，文章未成。甘言美語，說辭無名。",
"61-35":"日月運行，一寒一暑。榮𠖥赫赫，不可得保。顛隕墜墮，更為士伍。",
"61-36":"爭利王市，朝多君子。蘇氏六國，獲其榮寵。",
"61-37":"六蛇奔走，俱入茂草。驚於長途，畏懼啄口。",
"61-38":"懸桓素餐，食非其任。失輿剝廬，休坐徙居。",
"61-39":"歡欣九子，俱見大喜。攜提福善，王孫是富。",
"61-40":"伯夷叔齊，貞廉之師。以德防患，憂禍不存。",
"61-41":"雄聖伏名，人匿驎驚。走鳳飛北，亂潰未息。",
"61-42":"久鰥無偶，思配織女。求其非望，自令寡處。",
"61-43":"破亡之國，天所不福。難以止息。",
"61-44":"老慵多郤，弊政為賊。阿房驪山，子嬰失國。",
"61-45":"三羖六牂，相隨俱行。迷入空澤，遙涉虎廬。為所傷賊，死於牙腹。",
"61-46":"囁囁處懼，昧冥相搏。多言少實，語無成事。",
"61-47":"武陽漸離，擊筑善歌。慕丹之義，為燕助軻。陰謀不遂，霍自死亡，功名賈施。",
"61-48":"尹氏伯奇，父子分離。無罪被辜，長舌為災。",
"61-49":"五精亂行，政逆皇恩。湯武赫怒，共伐我域。",
"61-50":"西歷玉山，東入玉門。登上福堂，飲萬歲漿。",
"61-51":"行觸天忌，與司命牾。執囚束縛，拘制於吏，幽人有喜。",
"61-52":"機父不賢，朝多讒臣。君失其政，保家久貧。",
"61-53":"三人俱行，北求大牂。長孟病足，請季負囊。柳下之貞，不失我糧。",
"61-54":"鵲思其雄，欲隨鳳東。順理羽翼，出次須日。中留北色，復歸其室。",
"61-55":"嘗得自如，不逢禍災。",
"61-56":"白鵠遊望，君子以寧。履德不愆，福祿來成。",
"61-57":"膚敏之德，發憤晨食。虜豹禽說，為王得福。",
"61-58":"百足俱行，相輔為強。三聖翼事，國富民康。",
"61-59":"生不逢時，困且多憂。年衰老極，中心悲愁。",
"61-60":"出門蹉跌，看道後旅。買羊逸亡，取物逃走。空手握拳，坐恨相咎。",
"61-61":"烏鳥譆譆，天火將下。燔我屋室，災及妃后。",
"61-62":"牧羊稻田，聞虎喧嚾。畏懼悚息，終無禍患。",
"61-63":"龍潛鳳北，其子變服，陰孽萌作。",
"61-64":"國無比鄰，相與爭強，紛紛匈匈，天下擾憂。",
"62-1":"積德累仁，靈祐順信，福祉日增。",
"62-2":"謹慎重言，不幸遭患。周邵述職，脫免牢開。",
"62-3":"鳥飛鼓翼，喜樂堯德。虞夏美功，要荒賓服。",
"62-4":"牙孽生齒，室堂啟戶，幽人利貞，鼓翼起舞。",
"62-5":"使伯東求，拒不肯行。與叔爭訟，更相毀傷。",
"62-6":"手足易處，頭尾顛倒。公為雌嫗，亂其蚕織。",
"62-7":"匠卿操斧，豫章危殆。袍衣脫剝，祿命訖巳。",
"62-8":"天女踞床，不成文章。南箕無舌，飯多砂糖。虛象盜名，雌雄折頸。",
"62-9":"大椎破轂，長舌亂國。牆茨之言，三世不安。",
"62-10":"銜命辱使，不堪厥事。中墜落去，更為負載。",
"62-11":"三蛇共室，同類相得。甘露時降，生我百榖。",
"62-12":"衣繡夜遊，與君相逢。除患解惑，使我不憂。",
"62-13":"被髮獸心，難與為鄰。來如風雲，去如絕絃，為狼所殘。",
"62-14":"剛柔相呼，二姓為家。霜降既同，惠我以仁。",
"62-15":"牛耳聾瞶，不曉齊味。委以鼎俎，治亂憒憒。",
"62-16":"低頭竊視，有所畏避。行作不利，酒酢魚餒，眾莫貪嗜。",
"62-17":"雨師娶婦，黃巖季子。成禮既婚，相呼南上。膏我下土，年歲大有。",
"62-18":"戴盆望天，不見星辰。顧小失大，遁逃墻外。",
"62-19":"二人輦車，徙去其家。井沸釜鳴，不可以居。",
"62-20":"攘臂反肘，怒不可二。佷戾腹心，無以為市。",
"62-21":"湯世之憂，轉解喜來。",
"62-22":"忠信輔成，王政不傾。公劉兆舉，文武綏之。",
"62-23":"登高斬木，頓躓蹈險。車頓馬罷，伯叔吁嗟。",
"62-24":"桑方落隕，黃敗其葉。失勢傾仄，如無所立。",
"62-25":"鸞鳳翱翔，集於喜國。念我伯姊，與母相得。",
"62-26":"陰淫所居，益溢過度，傷害禾稼。",
"62-27":"霄冥高山，道險峻難。王孫罷極，困於阪間。",
"62-28":"和璧隨珠，為火所燒，冥昧失明，奪精無光，棄其道傍。",
"62-29":"虞君好神，惡我老親。恭承宗廟，雖愠不去，復我內事。",
"62-30":"爪牙之夫，怨毒圻父。轉憂與巳，傷不及母。",
"62-31":"倉盈𢈔億，宜稼黍稷，年歲有息。",
"62-32":"䆫牖戶房，通利光明。賢智輔聖，仁德大行。家給人足，海內殷昌。",
"62-33":"切切之患，凶重憂荐，為虎所吞。",
"62-34":"水無魚池，陸為海涯。君子失居，小人相攜。",
"62-35":"九疑欎林，沮濕不中。鸞鳳所惡，君子攸去。",
"62-36":"六翮況飛，走歸不及。脫歸王室，亡其騂特。",
"62-37":"不直莊公，與我爭訟。媒伯無禮，自令塞壅。",
"62-38":"倉𢈔多億，宋公危殆。吴子巢門，殞命失所。",
"62-39":"失羊捕牛，無損無憂。",
"62-40":"夏麥扶䵃，霜擊其芒。疾君敗國，使我誅傷。",
"62-41":"昧昧闇闇，不知白黑。風雨亂擾，光明伏匿，幽王失國。",
"62-42":"執斧破薪，使媒求婦，和合二姓，親迎斯須。色比毛嬙，姑翁悅喜。",
"62-43":"六疾生狂，妄痴走行。北入患門，與禍為鄰。",
"62-44":"驅羊就群，佷不肯前。慶季愎諫，子之被患。",
"62-45":"二人異路，東趍西步。十里之外，不相知處。",
"62-46":"義不勝情，以欲自營。睹利危躬，折角摧頸。",
"62-47":"騷騷擾擾，不安其類。疾在頸項，凶危為憂。",
"62-48":"三河俱合，水怒踴躍。壞我王屋，民困於食。",
"62-49":"陽曜旱疾，傷病稼穡。農人無食。",
"62-50":"流浮出食，載劵入屋。釋鞍繫馬，西南廡下。",
"62-51":"門戶之居，可以止舍，進仕不殆，安樂相保。",
"62-52":"過時不歸，雌雄苦悲。徘徊外國，與母分離。",
"62-53":"中田有廬，壃場有瓜。獻進皇祖，曾孫壽考。",
"62-54":"失恃無友，嘉福出走，傫如喪狗。",
"62-55":"反鼻岐頭，三寡獨居。",
"62-56":"衣裳顛倒，為王來呼。成就東周，封受大福。",
"62-57":"飛不遠去，還歸故處，興事多悔。",
"62-58":"含血走禽，不曉五音，瓠巴鼓瑟，不悅於心。",
"62-59":"求玉獲石，非心所欲，祝願不得。",
"62-60":"山崩谷絕，大福盡歇，涇渭失紀，玉石既巳。",
"62-61":"雜目懼怒，不安其居。散渙府藏，無有利得。",
"62-62":"初雖驚惶，後反無憂。受其福慶。",
"62-63":"眾邪充側，鳳凰折翼，微子復北，去其邦國。",
"62-64":"六月采𦬊，征伐無道。張仲方叔，克敵飲酒。",
"63-1":"遊駒石門，騄耳安全，受福西鄰，歸邑玉泉。",
"63-2":"陽春生草，萬物盛興。君子所居，災禍不到。",
"63-3":"人無𠯁，法緩除。才出雄，走羊驚，不失其家。",
"63-4":"太上止奔，變見太微。陳吳廢忽，作為禍患。",
"63-5":"乘龍吐光，使闇復明。燎獵大得，六師以昌。",
"63-6":"羊頭兔足，羸瘦少肉。漏囊貯粟，利無所得。",
"63-7":"因禍受福，喜盈其室。螟蟲不作，君無可得。",
"63-8":"舜升大禹，石夷之野。徵諸王闕，拜治水土。",
"63-9":"烏子鵲鶵，常與母俱。顧類群族，不離其巢。",
"63-10":"夷羿所射，發輒有獲。矰加鵲鷹，雙鳥俱得。",
"63-11":"晨風文翰，大舉就溫。昧過我邑，羿無所得。",
"63-12":"六喜三福，南至懽國。與喜忻樂，珪我潔德。",
"63-13":"鬥龍股折，日遂不明。自外為主，弟伐其兄。",
"63-14":"蒙慶受福，有所獲得，不利出門。",
"63-15":"蠻戎夷狄，太陰所積。固外𣲨寒，君子不存。",
"63-16":"畏昏潛處，候時昭明。卒遭白日，為榮祿主。",
"63-17":"水流趍下，欲至東海。求我所有，買魴與鯉。",
"63-18":"冠帶南遊，與福喜期。徼於嘉國，拜為逢時。",
"63-19":"莎雞振羽，為季門戶，新沐彈冠，仲父悅喜。",
"63-20":"結衿流粥，遭讒桎梏，周邵述職，身受大福。",
"63-21":"田鼠野雞，意常欲逃，拘制籠檻，不得動搖。",
"63-22":"居華顛，觀浮雲。風之搖，雨不濡。心平安，無咎憂。",
"63-23":"傾𠋣將顛，不能得存。英雄作業，家困無年。",
"63-24":"心願所喜，今乃逢時。保我利福，不离兵革。",
"63-25":"靈龜陸處，盤桓失所。阿衡退耕，憂封於國。",
"63-26":"弱水之右，有西王母。生不知老，與天相保，不利行旅。",
"63-27":"抱瓌求金，日暮坐吟。終月卒歲，竟無成功。",
"63-28":"言笑未畢，憂來暴卒。身加搤㩜，囚繫縛束。",
"63-29":"望幸不到，文章未成。王子逐兔，犬踦不得。",
"63-30":"震慄恐懼，多所畏惡。行道留難，不可以步。",
"63-31":"雄狐綏綏，登山崔嵬。昭告顯功，大福允興。",
"63-32":"火起吾後，喜炙倉廡。龍銜水深，潠注屋柱，雖憂無咎。",
"63-33":"危坐至暮，請求不得。膏澤不降，政戾民忒。",
"63-34":"孟春和氣，鷹隼搏鷙。眾雀憂憒。",
"63-35":"緩法長姦，不肯理冤。浮沉失節，君受其患。",
"63-36":"魚鱉貪餌，死於網釣。受危國寵，為身殃咎。",
"63-37":"金精輝怒，帶劍過午。徘徊高庫，宿於山谷。兩虎相拒，弓矢滿野。",
"63-38":"四目相望，稍近同光，並坐鼓簧。",
"63-39":"茹芝餌黃，飲酒玉英。與神流通，長無憂凶。",
"63-40":"求璋嘉鄉，惡蛇不行。道出歧口，還復其床。",
"63-41":"天門地戶，幽冥不睹。不知所在。",
"63-42":"跌足息肩，有所忌難。金城鐵郭，以銅為關。藩屏自衛，安止無患。",
"63-43":"三鴈俱飛，欲歸稻池。先涉雚澤，為矢所射，傷我胸臆。",
"63-44":"濟流難渡，濡我衣褲。五子善櫂，脫無他故。",
"63-45":"飲酒醉酗，跳起爭鬥。伯傷叔僵，東家治喪。",
"63-46":"跌躓未起，後失利市。蒙被殃咎。",
"63-47":"辰次降婁，建星中堅。子無遠行，外顛霄陷，遂命訖終。",
"63-48":"商風召寇，來呼外盜。間諜內應，與我爭鬥。殫已寶藏，主人不勝。",
"63-49":"甘露醴泉，太平機關。仁德感應，歲樂民安。",
"63-50":"祭仲子突，要門逐急。禍起子商，弟伐其兄。鄭久不昌。",
"63-51":"反孽難步，留不反舍。露宿澤陂，亡其𥜗褲。",
"63-52":"狼虎結謀，相聚為保。伺候牛羊，病我商人。",
"63-53":"明德剋敏，重華貢舉。放勳徵用，八哲蒙祐。",
"63-54":"貧鬼守門，日破我盆。毀罌傷瓶，空虛無子。",
"63-55":"天命赤烏，與兵徼期。征伐無道，箕子遊遨。",
"63-56":"威約拘囚，為人所誣。皋陶平理，剖械出牢。脫歸家閭。",
"63-57":"羊驚虎狼，聳耳群聚。無益威強，為齒所傷。",
"63-58":"初雖號啼，後必慶笑。光明照曜，百喜如意。",
"63-59":"馬服長股，宜行善市。蒙祐諧耦，獲金五倍。",
"63-60":"應門內萌，誅賢煞暴。上下咸悖，景公失位。長歸無恆，望妻來。",
"63-61":"執斧破薪，使媒求婦。和合二姓，親御斯須。色比毛嬙，姑公悅喜。",
"63-62":"兩輪日轉，南上大阪。四馬共轅，無有險難，與禹笑言。",
"63-63":"玄兔指掌，與足相恃。謹訊詰問，誣情自直。宛死誰告，口為身禍。",
"63-64":"千柱百梁，終不傾僵。周宗寧康。",
"64-1":"旦生夕死，名曰嬰鬼。不可得視。",
"64-2":"大步上車，南到喜家。送我狐裘，與福喜來。",
"64-3":"西多小星，參五在東。早夜晨行，勞苦無功。",
"64-4":"北陸藏冰，君子心悲。困於粒食，鬼驚我門。",
"64-5":"山水暴怒，壞梁折柱。稽難行旅，留連愁苦。",
"64-6":"比目四翼，來安吾國。福喜上堂，與我同床。",
"64-7":"狡兔趯趯，良犬逐齚。雄雌爰爰，為鷹所獲。",
"64-8":"增祿益福，喜來入室，解除憂惑。",
"64-9":"騎龍乘風，上見神公。彭祖受刾，王喬贊通。巫咸就位，拜受無窮。",
"64-10":"天火卒起，燒我旁里。延及吾家，空盡已財。",
"64-11":"金帛共寶，宜與我市。嫁娶有息，利得過倍。",
"64-12":"鬼魅之居，凶不可舍。",
"64-13":"鳥飛兔走，各有畏惡。鵰鷹為賊，亂我室舍。",
"64-14":"初雖驚惶，後乃無傷，受其福慶。",
"64-15":"兩金相擊，勇氣均敵。日月鬥戰，不破不缺。",
"64-16":"曳綸河海，挂釣魴鯉。王孫利得，以饗仲友。",
"64-17":"犬畏狼虎，依人有輔。三夫執戰，伏不敢起，身安無咎。",
"64-18":"蜘蛛作網，以伺行旅，青蠅嚵聚，以求膏腴。觸我羅絆，為網所得。",
"64-19":"所望在外，鼎金方來。拭爵條罍，炊食待之，不為季憂。",
"64-20":"日月並居，常暗匪明。高山崩顛，丘陵為谿。",
"64-21":"春服既成，載華復生。莖葉盛茂，實穗泥泥。",
"64-22":"莘首山頭，仙道所由。利以居止，長無咎憂。",
"64-23":"三狐群哭，自悲孤獨。野無所遊，死於丘室。",
"64-24":"火中暑退，禾黍其食。商人不至，市空無有。",
"64-25":"獨立山顛，求鹿耕田，草木不避，秋飢無年。",
"64-26":"火雖熾，在吾後。寇雖近，在吾右。身安吉，不危殆。",
"64-27":"銅銅咭咭，貧鬼相責。無有懽怡，一日九結。",
"64-28":"追亡逐北，呼還幼叔。至山而得，反歸其室。",
"64-29":"銜命辱使，不堪厥事。遂墮落去，更為斯吏。",
"64-30":"被珠函玉，沐浴仁德。應聘唐國，四門穆穆。蟊賊不作，凶惡伏匿。",
"64-31":"機關不便，不能出言。精成通道，為人所冤。",
"64-32":"甕破盆缺，南行亡夫。",
"64-33":"唇亡齒寒，積日凌根。朽不可用，為身哭患。",
"64-34":"蒙惑憧憧，不曉西東。魁罡指南，告我室中。利以宜止，去國憂患。",
"64-35":"鳥鴟搏翼，以避陰賊。盜伺二女，賴厥生福。旱災為疾，君無黍稷。",
"64-36":"名成德就，項領不試，景公耋老，尼父逝去。",
"64-37":"言與心詭，西行東坐，鯀湮鴻水，佞賊為禍。",
"64-38":"獫狁非度，治兵焦穫，伐鎬及方，與周爭𭛌。元戎其駕，衰及夷王。",
"64-39":"三火起明，雨滅其光。高位疾顛，驕恣誅傷。",
"64-40":"承川決水，為吾之祟，使我心憒。毋樹麻枲，居止凶咎。",
"64-41":"厭浥晨夜，道多湛露。瀐衣濡褲，重難以步。",
"64-42":"宜行賈市，所求必倍。載喜抱子，與利為友。",
"64-43":"陰變為陽，女化為男。治道得通，君臣相承。",
"64-44":"樹蔽壯荊，生醫山傍。仇敵背憎，熟肯相迎。",
"64-45":"坐茵乘軒，據德宰臣。虞叔受命，六合和親。",
"64-46":"雲興蔽日，雨集草木。茂年歲熟。",
"64-47":"播梅折枝，與母別離，絕不相知。",
"64-48":"天旱水涸，枯槁無澤。困於沙石，未有所獲。",
"64-49":"珪璧琮璜，執禮見王。百里𡩋戚，應聘齊秦。",
"64-50":"龍渴求飲，黑雲景從。河伯捧醴，跪進酒漿，流潦滂滂。",
"64-51":"雹梅零蔕，心積憒憒，亂我靈氣。",
"64-52":"鹿求其子，虎廬之里。唐伯季耳，貪不我許。",
"64-53":"穿匏挹水，篝鐵然火。勞罷力竭，飢渴為禍。",
"64-54":"龍生馬淵，壽考且神。飛騰上天，舍宿軒轅。常居樂安。",
"64-55":"崔嵬北嶽，天神貴客。溫仁正直，主布恩德。冠衣不巳，蒙受大福。",
"64-56":"鬼夜哭泣，齊失其國。為下所賊。",
"64-57":"二政多門，君失其權。三家專制，禍起季孫。",
"64-58":"望幸不到，文章未就。王子逐兔，大踦不得。",
"64-59":"伯虎仲熊，德義昭明。使布五教，陰陽順敘。",
"64-60":"兩足四翼，飛入家國。寧我伯叔，與母相得。",
"64-61":"春秋禱祀，解禍除憂。君無咎憂。",
"64-62":"牧羊稻園，聞虎喧嚾。懼畏悚息，終無禍患。",
"64-63":"大蛇巨魚，相搏於郊。君臣隔塞，郭公出廬。",
"64-64":"忠慢未習，單酒糗脯。數至神前，欲求所願，反得大患。"
};
